-- Frutos secos: versiones molidas + flags de atragantamiento en los enteros
SELECT m.id, ia.allergen_id FROM public.ingredients m
JOIN public.ingredients e ON e.code = CASE m.code WHEN 'almendra_molida' THEN 'almendra' WHEN 'avellana_molida' THEN 'avellana' END
JOIN public.ingredient_allergens ia ON ia.ingredient_id = e.id
WHERE m.code IN ('almendra_molida','avellana_molida')
  AND NOT EXISTS (SELECT 1 FROM public.ingredient_allergens x WHERE x.ingredient_id=m.id AND x.allergen_id=ia.allergen_id);
UPDATE public.recipe_ingredients SET ingredient_id=(SELECT id FROM public.ingredients WHERE code='almendra_molida') WHERE ingredient_id=(SELECT id FROM public.ingredients WHERE code='almendra');
UPDATE public.recipe_ingredients SET ingredient_id=(SELECT id FROM public.ingredients WHERE code='avellana_molida') WHERE ingredient_id=(SELECT id FROM public.ingredients WHERE code='avellana');
UPDATE public.ingredients SET name='Nueces molidas' WHERE code='nuez';
UPDATE public.ingredients SET name='Frutos secos finamente molidos' WHERE code='fruto_seco_molido';
UPDATE public.ingredients SET is_whole_nut=true, choking_risk=true WHERE code IN ('almendra','avellana','nuez_entera');

-- Edades minimas por riesgo de atragantamiento / sodio
UPDATE public.recipes SET min_age_months=48 WHERE slug IN ('palitos-de-verduras','bastones-de-verduras-con-hummus') AND min_age_months<48;
UPDATE public.recipes SET min_age_months=12 WHERE slug='papilla-de-yogur-con-frutas-y-granola' AND min_age_months<12;
UPDATE public.recipes SET min_age_months=24 WHERE slug='rollitos-de-sandwich-estilo-sushi' AND min_age_months<24;
UPDATE public.recipes SET min_age_months=36 WHERE slug IN ('gomitas-de-frutas','alitas-de-pollo') AND min_age_months<36;
UPDATE public.recipes SET min_age_months=24 WHERE slug='bombones-de-fruta' AND min_age_months<24;
UPDATE public.recipes SET min_age_months=24 WHERE category='lonchera' AND min_age_months<24;

-- Comida de bebe: tope de edad
UPDATE public.recipes SET category='papilla', max_age_months=24 WHERE slug IN ('pure-de-espinacas-y-papa','pure-de-papa-con-brocoli');
UPDATE public.recipes SET max_age_months=24 WHERE max_age_months IS NULL AND slug IN ('pollo-a-la-naranja-para-bebe','pescadito-dorado-con-pure-cremoso','cremita-de-durazno-y-requeson','avena-cremosa-de-camote-y-manzana','avena-cremosa-de-mango-y-platano','avena-cremosa-de-zanahoria-y-huevo','bastones-suaves-de-res-y-camote','cuadritos-blandos-de-huevo-avena-y-calabacita','dedos-blandos-de-lenteja-y-calabaza','batido-de-manzana-y-platano','dulcecito-de-camote-y-canela','macarrones-con-salsa-de-brocoli');
UPDATE public.recipes SET max_age_months=24 WHERE max_age_months IS NULL AND texture_stages <@ ARRAY[1,2,3];

-- OMS: sin sal antes de los 12 meses / sin edulcorantes no nutritivos
UPDATE public.recipe_ingredients ri
   SET note = CASE WHEN coalesce(ri.note,'')='' THEN 'solo desde los 12 meses; omítela para bebés'
                   ELSE ri.note || '; solo desde los 12 meses, omítela para bebés' END
  FROM public.recipes r, public.ingredients i
 WHERE ri.recipe_id=r.id AND ri.ingredient_id=i.id AND i.code='sal' AND r.min_age_months<12 AND coalesce(ri.note,'') !~* '12 meses';
DELETE FROM public.recipe_ingredients ri USING public.recipes r, public.ingredients i
 WHERE ri.recipe_id=r.id AND ri.ingredient_id=i.id AND r.slug='pie-de-limon' AND i.code='stevia';

-- Pasos de seguridad anti-atragantamiento
WITH nuevos(slug, instruccion) AS (VALUES
 ('frutero-del-recreo','Seguridad: corta las uvas en cuartos a lo largo para menores de 4 años; nunca las ofrezcas enteras.'),
 ('ensalada-dulce','Seguridad: corta las uvas en cuartos a lo largo para menores de 4 años; las nueces van siempre molidas.'),
 ('salpicon-de-frutas','Seguridad: corta las uvas en cuartos a lo largo para menores de 4 años; las nueces van siempre finamente molidas.'),
 ('mini-pizza-casera-con-tomates-cherry','Seguridad: corta los tomates cherry en cuartos antes de armar la pizza para menores de 4 años; nunca enteros.'),
 ('salchichas-de-pollo-caseras','Seguridad: corta la salchicha a lo largo en cuartos (nunca en rodajas tipo moneda) para menores de 4 años.'),
 ('yogur-con-fresas-y-arandanos','Seguridad: aplasta o corta en mitades los arándanos para menores de 2 años.'),
 ('costillas-de-cerdo-al-horno-con-papas','Seguridad: retira toda la carne del hueso y desmenúzala antes de servir a menores de 2 años; nunca ofrezcas la costilla con hueso a un bebé.'),
 ('frijoles-blancos-con-costillas-de-cerdo','Seguridad: retira toda la carne del hueso y desmenúzala antes de servir a menores de 2 años; nunca ofrezcas la costilla con hueso a un bebé.'),
 ('pina-asada','Seguridad: retira la fruta del palillo y sírvela suelta a menores de 3 años.'),
 ('brochetas-de-mini-panqueques','Seguridad: retira los alimentos del palillo y sírvelos sueltos a menores de 3 años.'),
 ('pinchos-de-frutas-con-chocolate','Seguridad: retira la fruta del palillo y sírvela suelta a menores de 3 años.'),
 ('bolitas-energeticas-en-palito','Seguridad: retira la bolita del palito y sírvela suelta a menores de 3 años.'),
 ('bombones-de-fruta','Seguridad: retira el palillo antes de servir a menores de 3 años; los frutos secos van siempre finamente molidos.'),
 ('snack-de-manzana','Seguridad: para menores de 4 años sirve la manzana rallada o en láminas muy finas; los trozos duros de manzana cruda son riesgo de atragantamiento.'),
 ('alitas-de-pollo','Seguridad: desmenuza la carne y retira todos los huesos y cartílagos antes de servir a menores de 4 años.'),
 ('gomitas-de-frutas','Seguridad: sirve en trozos pequeños y siempre bajo supervisión de un adulto.')
)
SELECT r.id, (SELECT coalesce(max(rs.step_number),0)+1 FROM public.recipe_steps rs WHERE rs.recipe_id=r.id), n.instruccion, true
FROM nuevos n JOIN public.recipes r ON r.slug=n.slug
WHERE NOT EXISTS (SELECT 1 FROM public.recipe_steps rs2 WHERE rs2.recipe_id=r.id AND rs2.instruction=n.instruccion);

-- ============================================================
-- CONSEJOS ZANA reescritos en lenguaje claro (2026-08-17)
-- Una idea por oracion separada por " · ", sin pronombres ambiguos.
-- ============================================================
UPDATE public.recipes r SET tips = v.tip FROM (VALUES
  ('agua-fresca-de-melon-y-menta', 'Congela el agua fresca que sobre en moldes de paleta · Sirve las paletas al día siguiente como postre helado de fruta · Evita comprar postre extra.'),
  ('albondigas-con-salsa-de-calabaza', 'Agrega una pizca de canela o nuez moscada a la salsa para un toque dulce sin azúcar · Duplica la receta y cocina de una vez para varios días · Congela las albóndigas con su salsa en porciones individuales.'),
  ('albondigas-de-berenjena', 'Congela las albóndigas ya horneadas hasta 2 meses · Recalienta las albóndigas en el horno para que recuperen la textura dorada.'),
  ('albondigas-de-carne-de-res', 'Introduce el huevo y el gluten del pan molido de a uno y observa 2-3 días · Si necesitas versión sin gluten, usa avena molida en lugar de pan molido · Congela las albóndigas cocidas hasta 2 meses.'),
  ('albondigas-de-pavo-y-zanahoria', 'Si necesitas versión sin gluten, usa harina de garbanzo en lugar de pan molido · Congela la mitad de las albóndigas cocidas con su salsa hasta 2 meses · Cuenta con esas albóndigas como otra comida lista.'),
  ('alitas-de-pollo', 'Manda las alitas frías en la lonchera, con gel refrigerante y toallitas para las manos · Sirve las alitas como plato ocasional, porque la marinada lleva miel · Acompaña las alitas con bastones finos de zanahoria y pepino.'),
  ('arepa-de-choclo-con-platano-maduro', 'Prepara doble cantidad y cocina de una vez para varios días · Congela las arepas ya cocidas hasta 2 meses · Calienta las arepas en sartén o tostadora unos minutos.'),
  ('arepa-de-yuca-y-calabaza', 'Congela las arepitas crudas separadas con papel de horno hasta 2 meses · Cocina las arepitas directo del congelador · Si las arepitas van rellenas con queso o aguacate, empaca la lonchera con gel refrigerante.'),
  ('arepas-nutritivas', 'Sirve las arepas doradas y crujientes desde los 12 meses · Haz las arepas finas y blandas para los bebés · Congela las arepas cocidas hasta 3 meses y recalienta en sartén · Rellena las arepas con puré de aguacate o queso fresco sin sal.'),
  ('aros-de-cebolla', 'Sirve los aros de cebolla con una salsa de yogur natural y mostaza suave · Recuerda que los aros llevan huevo, y gluten si usas pan rallado de trigo · Revisa las reglas de alérgenos de la escuela antes de mandar los aros.'),
  ('arroz-a-la-campesina', 'Agrega huevo cocido picado o pollo desmenuzado al final para convertir el arroz en plato completo · Si usas arroz blanco, reduce el caldo a unos 400 ml y cocina 18-20 minutos.'),
  ('arroz-con-arvejas-y-jamon', 'Agrega zanahoria rallada o pimiento rojo en cubitos para sumar color y vitaminas · Cambia el jamón por pollo o pavo cocido desmenuzado si quieres una versión menos procesada · Deja el resto de la receta igual.'),
  ('arroz-con-brocoli-y-queso', 'Llama a los ramilletes de brócoli "arbolitos con nieve de queso": los nombres divertidos animan a los niños a probar la verdura · Usa las sobras al día siguiente como base para croquetas de arroz al horno.'),
  ('arroz-con-leche-de-chocolate', 'Manda el arroz con leche caliente en termo · Manda el arroz con leche frío en recipiente hermético con gel refrigerante · Consume el arroz con leche antes de 4 horas · Guarda el arroz con leche en el refrigerador hasta 2 días.'),
  ('arroz-con-pollo-y-verduras', 'Cocina la zanahoria junto con el arroz y el pollo: la zanahoria cruda rallada no es segura para los bebés · Agrega una pizca de cúrcuma para dar color y sabor sin sal · Congela el arroz en porciones individuales hasta 2 meses.'),
  ('arroz-con-pollo-y-zanahoria', 'Deja el arroz tapado 5 minutos fuera del fuego antes de destapar la olla · Sirve el arroz suelto: ese reposo evita que quede pastoso · Si usas arroz blanco, cocina en la mitad del tiempo con unos 400 ml de caldo.'),
  ('arroz-integral-con-lentejas', 'Si usas lentejas de lata, enjuaga las lentejas bajo el chorro de agua para reducir el sodio · Agrega una hoja de laurel durante la cocción: ese aroma suele gustar a los niños.'),
  ('arroz-salteado-con-huevo-y-verduras', 'Usa arroz del día anterior, frío y suelto: el arroz recién hecho se apelmaza · Guarda el arroz en el refrigerador dentro de las 2 horas siguientes a la cocción · Usa el arroz guardado como máximo al día siguiente.'),
  ('avena-cremosa-de-camote-y-manzana', 'Agrega una pizca de canela en vez de endulzantes · Cocina la manzana hasta que quede suave, nunca cruda rallada · Congela la avena en porciones individuales hasta 3 meses · Sirve la avena en el desayuno o como base de otras papillas.'),
  ('avena-cremosa-de-mango-y-platano', 'Agrega una pizca de canela en vez de endulzantes · Si usas leche materna, cocina la avena en agua y agrega la leche tibia al final, fuera del fuego · Protege así los nutrientes de la leche · Congela la base sin leche materna hasta 3 meses.'),
  ('avena-cremosa-de-manzana-y-canela', 'Prepara doble cantidad de avena para tener el desayuno de mañana listo · Guarda la avena en el refrigerador hasta el día siguiente · Calienta la avena con un chorrito de leche.'),
  ('avena-cremosa-de-zanahoria-y-huevo', 'Usa el huevo entero bien cocido desde los 6 meses: aporta más hierro y proteína que solo la yema · Ofrece el huevo solo la primera vez y observa 2-3 días, porque es alérgeno · Prepara la avena fresca: el huevo cocido no se congela bien.'),
  ('barritas-crocantes-de-mani-y-chocolate', 'Si la escuela no permite maní, cambia la mantequilla de maní por crema de semillas de girasol · Manda las barritas con gel refrigerante para que el chocolate no se derrita.'),
  ('barritas-de-avena-y-frutos-secos', 'Guarda las barritas en recipiente hermético a temperatura ambiente hasta 1 semana · Congela las barritas envueltas una a una hasta 3 meses · Reemplaza los dátiles por medio plátano bien maduro machacado para bajar el azúcar.'),
  ('barritas-de-fruta-y-avena', 'Envuelve las barritas de a una en papel encerado para la lonchera o la merienda · Guarda las barritas en recipiente hermético hasta 1 semana · Si no quieres usar horno, compacta la mezcla, refrigera 2 horas y corta las barritas.'),
  ('barritas-de-manzana-y-amaranto', 'Envuelve las barritas una por una en papel encerado para la lonchera · Guarda el resto de las barritas en el refrigerador hasta 3 días.'),
  ('barritas-energeticas', 'Envuelve las barritas una por una en papel encerado · Guarda las barritas en el refrigerador hasta 1 semana · Manda las barritas en la lonchera con gel refrigerante · Cambia parte de la avena por quinua inflada.'),
  ('bastoncitos-de-calabacin-al-horno', 'Hornea los bastoncitos blandos, no crujientes, para menores de 12 meses: lo crujiente es riesgo de atragantamiento antes del año · Sirve los bastoncitos el mismo día con yogur natural sin azúcar · Recuerda que la avena tiene gluten.'),
  ('bastones-de-verduras-con-hummus', 'Ofrece los bastones crudos solo cuando tu peque ya mastica bien · Si tu peque es más pequeño, cuece los bastones al vapor unos minutos.'),
  ('bastones-suaves-de-res-y-camote', 'Aprovecha la receta para dos o tres comidas · Congela los bastones fríos, separados en bandeja y luego en bolsa, hasta 2 meses · Descongela los bastones en el refrigerador de un día para otro · Calienta bien los bastones antes de servir.'),
  ('batido-de-aguacate', 'Agrega unas gotas de jugo de limón para que el batido no se oscurezca · Prepara el batido el mismo día · Si el batido va a la lonchera, usa termo frío.'),
  ('batido-de-fresa-y-banana', 'Si el batido queda muy espeso, agrega un poco más de leche · Si quieres el batido helado, usa banana congelada en trozos.'),
  ('batido-de-manzana-y-platano', 'Ofrece el batido con cuchara y bien espeso a los 6 meses: es fruta entera, no jugo · Sirve el batido recién hecho para que no se oxide · Congela el batido en moldes de paleta para los niños más grandes.'),
  ('batido-de-papaya', 'Elige una papaya bien madura, que ceda un poco al presionar la cáscara · Sirve el batido sin endulzantes: la papaya madura da dulzor natural.'),
  ('batido-de-vainilla', 'Agrega cubos de hielo al licuar para una textura más espumosa · Si el batido va a la lonchera, usa termo frío · Toma el batido antes de 4 horas.'),
  ('batido-verde-de-mango-y-espinaca', 'Empieza con poca espinaca y aumenta la cantidad poco a poco · Muestra el color verde a tu peque: ese verde suele encantar a los niños.'),
  ('berenjenas-empanizadas', 'Usa las berenjenas como base de mini pizzas: agrega salsa de tomate y queso encima · Gratina las mini pizzas unos minutos · Recuerda que las berenjenas llevan huevo, y gluten si usas pan rallado de trigo.'),
  ('bizcocho-de-calabaza-blw', 'Usa el polvo de hornear y el aceite de la receta: sin esos dos ingredientes el bizcocho queda denso y gomoso · Baña el bizcocho con salsa de algarroba (ver receta) para un toque especial · Congela el bizcocho hasta 3 meses.'),
  ('bizcocho-relleno', 'Duplica las cantidades de la receta · Hornea en moldes de muffin para tener bizcochitos listos para dos días · Rellena los bizcochitos el mismo día que van a la lonchera, así el yogur llega fresco'),
  ('bocaditos-de-chocolate-y-avellana', 'Revisa la política del colegio antes de enviar los bocaditos, porque muchas escuelas no permiten maní ni frutos secos · Guarda los bocaditos en recipiente hermético en el refrigerador hasta 1 semana')
) AS v(slug, tip) WHERE r.slug = v.slug;UPDATE public.recipes r SET tips = v.tip FROM (VALUES
  ('bolitas-de-brocoli-pollo-y-papa', 'Duplica la cantidad de bolitas · Congela sin hornear la mitad de las bolitas · Lleva las bolitas del congelador al horno sin descongelar y suma unos 5 minutos de cocción'),
  ('bolitas-de-espinacas-y-queso', 'Congela las bolitas ya horneadas hasta 2 meses · Calienta las bolitas en el horno para que vuelvan a quedar crujientes · Si van a la lonchera, empaca las bolitas con un gel refrigerante'),
  ('bolitas-de-nueces-y-ciruelas', 'Guarda las bolitas en recipiente hermético en el refrigerador hasta 1 semana · Sirve las bolitas bien frías, porque la textura mejora · Si la escuela restringe los frutos secos, cambia las nueces por semillas de girasol'),
  ('bolitas-de-pollo', 'Cocina doble tanda de bolitas de una vez · Congela las bolitas ya cocidas hasta 2 meses · Empaca las bolitas con gel refrigerante en la lonchera · Sirve las bolitas antes de 4 horas'),
  ('bolitas-energeticas-en-palito', 'Si la escuela es libre de maní, prepara las bolitas con crema de semillas de girasol · Decora las bolitas con semillas trituradas · Guarda las bolitas en recipiente hermético en el refrigerador hasta 5 días'),
  ('bombones-de-chocolate-y-frutos-secos', 'Cambia el cacao por harina de algarroba en la misma cantidad para ofrecer los bombones desde el año · Usa algarroba porque es dulce y no tiene cafeína · Guarda los bombones en recipiente hermético en el refrigerador hasta 5 días'),
  ('bombones-de-fruta', 'Baña los bombones en chocolate amargo derretido para ocasiones especiales · Si la escuela es libre de maní, usa crema y semillas de girasol'),
  ('brochetas-de-mini-panqueques', 'Agrega 1 cucharada de remolacha cocida triturada para panqueques rosados sin colorantes · Usa banana madura machacada para más dulzor sin miel extra · Congela los panqueques solos hasta 2 meses · Descongela los panqueques en el tostador'),
  ('brownies-saludables', 'Si la escuela restringe los frutos secos, usa harina de avena en lugar de harina de almendras · Refrigera los brownies en recipiente hermético · Congela los brownies hasta 2 meses · Envía los brownies a la lonchera con gel refrigerante'),
  ('budin-de-pan-y-platano', 'Usa el pan duro de ayer, porque el pan seco absorbe mejor la leche · Congela el budín en porciones envueltas una por una hasta 2 meses · Pasa las porciones al refrigerador la noche anterior para descongelar'),
  ('burrito-de-frijoles', 'Rocía el aguacate con unas gotas de limón para que no se oscurezca hasta el recreo · Envuelve el burrito en papel de horno · Empaca el burrito en lonchera térmica con gel refrigerante, porque lleva queso'),
  ('caldo-de-pescado', 'Ofrece el pescado solo y en poca cantidad, porque es un alérgeno · Observa a tu peque 2 o 3 días antes de repetir · Cuela muy bien el caldo y revisa que no queden espinas · Congela el caldo en cubetera hasta 2 meses'),
  ('caldo-de-pollo', 'Enfría el caldo en el refrigerador y retira la grasa de la superficie para un caldo más ligero · Congela el caldo en cubetera hasta 2 meses · Usa cebolla cocida, apta desde los 6 meses, para dar sabor sin sal'),
  ('caldo-de-verduras', 'Haz puré con las verduras coladas y aprovecha ese puré en otra comida · Congela el caldo en porciones pequeñas hasta 3 meses · Usa el caldo para arroces, sopas y papillas'),
  ('cerdo-con-verduras', 'Cocina el cerdo hasta que quede muy tierno y fácil de triturar · Agrega un chorrito de aceite de oliva al final para mejorar la textura y la absorción de nutrientes · Congela el cerdo con verduras en porciones individuales hasta 2 meses'),
  ('chips-de-verduras-y-frutas', 'Si tienes deshidratador, seca los chips a unos 60 °C por 6 a 8 horas · Espolvorea canela sobre las frutas antes de secar para un toque dulce sin azúcar · Guarda los chips apenas enfríen para que no se ablanden con la humedad'),
  ('chocolate-caliente-sin-azucar', 'Bate bien la mezcla para que no queden grumos de cacao · Prueba la temperatura del chocolate antes de servir a tu peque'),
  ('chorizo-de-vegetales', 'Duplica la receta para cocinar de una vez para varios días · Congela los chorizos ya cocidos hasta 3 meses · Acompaña los chorizos con arroz o arepitas en la lonchera · Empaca los chorizos con gel refrigerante'),
  ('churros-caseros-de-avena', 'Acompaña los churros con salsa de algarroba o con fresas cortadas en cuartos a lo largo · Sirve los churros recién horneados, cuando están crujientes · Si necesitas versión sin gluten, usa avena certificada sin gluten'),
  ('compota-de-pera-y-canela', 'Congela la compota en cubetera hasta 3 meses · Guarda la compota en frasco de vidrio tapado hasta 5 días en el refrigerador · Empaca la compota con gel refrigerante en la lonchera · Suma una pizca de jengibre para los más grandes'),
  ('costillas-de-cerdo-al-horno-con-papas', 'Retira toda la carne del hueso y revisa que no queden esquirlas · Hornea las costillas tapadas con papel aluminio para más ternura · Si la carne queda dura, hierve las costillas 15 minutos antes de hornear · Sirve con puré de calabacita'),
  ('crema-de-avellanas-y-cacao', 'Si la escuela es libre de frutos secos, cambia las avellanas por semillas de girasol tostadas · Sirve la crema con confianza, porque queda igual de cremosa y es segura para todos los compañeros'),
  ('crema-de-calabaza', 'Agrega al final un chorrito de leche materna, fórmula o aceite de oliva para una crema más cremosa · Congela la crema en cubetera hasta 3 meses para tener porciones listas'),
  ('crema-de-semola-con-durazno', 'Recalienta la sémola con un chorrito de leche, porque la sémola espesa al enfriarse · Bate la crema de nuevo para que quede cremosa · Si no hay duraznos, usa pera madura rallada, mango o papaya'),
  ('cremita-de-durazno-y-requeson', 'Usa mango, pera o papaya bien maduros fuera de temporada · Evita los duraznos en almíbar, porque llevan azúcar añadida · Si la cremita se separa tras un par de horas en el refrigerador, bate la cremita antes de servir'),
  ('crepes-de-avena', 'Si rellenas los crepes con crema de maní, unta una capa muy fina · Confirma la política de alérgenos del colegio, porque muchas escuelas son libres de maní · Cambia la crema de maní por crema de semillas de girasol'),
  ('crepes-de-queso', 'Suma jamón o espinaca salteada al relleno para una versión más completa · Enfría los crepes por completo antes de cerrar la lonchera · Empaca los crepes siempre con un gel refrigerante'),
  ('croquetas-de-arroz', 'Cambia el arroz blanco por arroz integral o quinua cocida para variar · Empaca las croquetas frías en recipiente hermético con gel refrigerante para la lonchera'),
  ('croquetas-de-calabaza-y-brocoli', 'Si la masa queda muy húmeda, agrega pan molido de a poco hasta poder formar las croquetas · Si necesitas versión sin gluten, cambia el pan molido por hojuelas de avena certificada sin gluten trituradas'),
  ('croquetas-de-pollo-y-brocoli', 'Aprovecha sobras de pollo y verduras en esta receta · Congela la masa cruda o las croquetas ya formadas hasta 2 meses · Si necesitas versión sin gluten, usa pan rallado sin gluten'),
  ('croquetas-de-verduras-al-horno', 'Congela las croquetas crudas separadas en una bandeja · Pasa luego las croquetas a una bolsa · Hornea las croquetas directo del congelador y suma unos 5 minutos extra'),
  ('cuadritos-blandos-de-huevo-avena-y-calabacita', 'Guarda los cuadritos en recipiente hermético en el refrigerador hasta 2 días · Congela los cuadritos hasta 2 meses · Cambia la calabacita por zanahoria rallada fina o brócoli cocido y picado muy menudo'),
  ('cupcakes-de-naranja', 'Usa una banana bien madura, con manchitas en la cáscara, para que los cupcakes queden dulces · Espolvorea una pizca de canela al final para dar aroma extra'),
  ('cuscus-con-pollo-y-verduras', 'Cambia el pollo por pavo o cerdo magro en trocitos bien cocidos · Empaca el cuscús frío con gel refrigerante o caliente en termo · Muele las almendras y pica las pasas muy finito, porque enteras no son seguras antes de los 5 años'),
  ('deditos-de-pescado-empanizados', 'Revisa los alérgenos de la escuela, porque los deditos llevan pescado, huevo y gluten · Congela los deditos crudos empanizados en una bandeja · Hornea los deditos congelados y suma 5 minutos · Empaca los deditos con gel refrigerante'),
  ('dedos-blandos-de-lenteja-y-calabaza', 'Congela los dedos horneados y fríos, separados en bandeja y luego en bolsa · Calienta los dedos congelados 10 minutos en el horno · Sirve después media naranja o mandarina, porque la vitamina C ayuda a absorber el hierro de la lenteja'),
  ('donas-caseras', 'Si no tienes tiempo o usas harina de avena, cambia la levadura por 2 cucharaditas de polvo de hornear · Hornea las donas de inmediato, sin dejar leudar la masa · Si hay celiaquía en casa, usa avena certificada sin gluten'),
  ('dulce-de-guayaba', 'Combina un cuadrito de dulce con cubos de queso fresco en la lonchera: el dúo clásico de guayaba con queso · Guarda el dulce de guayaba tapado en el refrigerador hasta 2 semanas'),
  ('dulcecito-de-camote-y-canela', 'Congela el puré de camote en cubetera hasta 3 meses · Descongela un cubo por porción en el refrigerador · Cambia el camote por calabaza (zapallo) madura: queda más cremoso'),
  ('empanadas-de-atun', 'Congela las empanadas crudas hasta 2 meses · Hornea las empanadas directo del congelador y suma 5 minutos · Empaca las empanadas en la lonchera con gel refrigerante · Sirve las empanadas antes de 4 horas')
) AS v(slug, tip) WHERE r.slug = v.slug;UPDATE public.recipes r SET tips = v.tip FROM (VALUES
  ('enrollado-de-garbanzos-y-zanahoria', 'Deja el enrollado entero 5 minutos en el refrigerador antes de cortar: las ruedas quedan parejas · Guarda la pasta de garbanzos tapada en el refrigerador hasta 2 días · Unta la pasta de garbanzos en galletas de agua'),
  ('ensalada-de-frutas-de-invierno', 'Sirve la ensalada recién hecha: así la fruta no se oxida · Suma unas gotas de limón para mantener el color · Sirve solo la fruta antes del año · Agrega un chorrito de jugo de naranja o mandarina desde los 12 meses, en poca cantidad'),
  ('ensalada-de-lentejas-con-pollo', 'Aplasta bien las lentejas antes de los 12 meses para evitar atragantamientos · Manda la ensalada fría en la lonchera, con gel refrigerante · Agrega un chorrito de aceite de oliva: queda más suave y nutritiva'),
  ('ensalada-de-quinua-y-garbanzos', 'Espolvorea un puñadito de semillas de ajonjolí o girasol para dar un toque crujiente · Manda la ensalada fría en la lonchera, en contenedor hermético con gel refrigerante'),
  ('ensalada-dulce', 'Manda la ensalada en la lonchera en contenedor hermético con gel refrigerante · Sirve la ensalada antes de 4 horas · Evita la miel y el azúcar: la fruta ya endulza'),
  ('espaguetis-carbonara-blw', 'Agrega una pizca de nuez moscada para dar aroma sin usar sal · Recuerda que la pasta contiene gluten · Si es la primera vez que ofreces pasta, sirve poca cantidad y observa 2-3 días'),
  ('espaguetis-de-calabacita-con-tomate', 'Cocina la calabacita poco tiempo para que no suelte agua · Si quieres sumar proteína y grasas buenas, espolvorea nueces o almendras finamente molidas · Sirve las nueces siempre molidas, nunca enteras, antes de los 5 años'),
  ('estofado-de-pollo-y-verduras', 'Congela el estofado en porciones individuales hasta 2 meses · Descongela el estofado en el refrigerador y recalienta bien antes de servir · Si usas caldo comprado, elige uno bajo en sodio o prepara caldo casero sin sal'),
  ('filetes-de-merluza-al-limon', 'Hornea los filetes a 180 °C por 12-15 minutos si prefieres · Si no consigues merluza, usa otro pescado blanco (corvina, tilapia, bacalao fresco) · Ralla solo la parte amarilla del limón: da aroma sin acidez'),
  ('flan-suave-de-platano', 'Usa mitad leche y mitad yogur natural: queda más cremoso · Agrega ralladura de naranja o limón: realza el sabor del plátano · Guarda el flan tapado en el refrigerador hasta 3 días · Evita congelar el flan: el huevo queda granuloso'),
  ('frijoles-blancos-con-costillas-de-cerdo', 'Retira todos los huesos y revisa la carne con los dedos para descartar esquirlas antes de servir · Aplasta bien los frijoles antes de los 12 meses · Cocina la costilla hasta que la carne se desprenda sola · Usa caldo casero sin sal'),
  ('frutero-del-recreo', 'Elige frutas firmes: manzana, pera de pulpa dura, mandarina, uva y plátano resisten los golpes de la mochila · Deja fuera la fresa, el melón y la papaya en trozos: se aguan en pocas horas sin frío'),
  ('galletas-clasicas-de-avena-y-platano', 'Usa plátano maduro: endulza las galletas sin azúcar añadida · Guarda las galletas en recipiente hermético hasta 4 días · Si necesitas versión sin gluten, usa avena certificada sin gluten'),
  ('galletas-de-almendra-y-miel', 'Congela las bolitas de masa crudas · Hornea las bolitas directo del congelador y suma 2 o 3 minutos · Si hay alergia a frutos secos, cambia la harina de almendra por la misma cantidad de harina de avena y 1 cucharada extra de aceite'),
  ('galletas-de-avena-y-manzana', 'Si buscas versión sin huevo, usa medio plátano maduro o 1 cucharada de chía hidratada en 3 de agua · Guarda las galletas en el refrigerador de inmediato, en recipiente hermético, hasta 4 días · Manda gel refrigerante en la lonchera'),
  ('galletas-de-avena-y-manzana-sin-huevo', 'Hornea las galletas blandas y apenas doradas · Deja las galletas crujientes para mayores de 12 meses · Guarda las galletas en frasco hermético hasta 2 días o congeladas hasta 3 meses · Si hay celiaquía, usa avena certificada sin gluten'),
  ('galletas-de-chocolate', 'Duplica o triplica las cantidades para cocinar de una vez para varios días · Si la escuela es libre de maní, prepara las galletas con crema de semillas de girasol'),
  ('galletas-de-coco', 'Usa plátano bien maduro: las galletas quedan más dulces · Guarda las galletas en recipiente hermético hasta 2 días · Congela las galletas ya horneadas hasta 2 meses'),
  ('galletas-rellenas-de-ciruela-pasa', 'Guarda las galletas en frasco hermético a temperatura ambiente hasta 1 semana · Congela las galletas de a una en bolsa hasta 3 meses · Si quieres otro relleno, usa orejones de durazno hidratados 20 minutos en agua caliente'),
  ('garbancitos-en-salsa-de-tomate', 'Si trituras todo el guiso, obtienes una crema de garbanzos · Sirve la crema para untar o mojar con pan'),
  ('garbanzos-con-pescado-blanco-y-tomate', 'Recuerda que el pescado es un alérgeno · Presenta el pescado solo la primera vez y observa 2-3 días · Aplasta bien los garbanzos antes de los 12 meses: enteros pueden atragantar · Usa caldo de pescado casero y sin sal'),
  ('garbanzos-crujientes', 'Guarda los garbanzos en un frasco hermético, no en bolsa, en la despensa hasta 3-4 días · Si los garbanzos pierden lo crujiente, tuesta los garbanzos 5 minutos más en el horno'),
  ('gelatina-de-frutas-naturales', 'Corta la fruta en trozos pequeños · Evita el kiwi y la piña crudos: impiden que la gelatina cuaje'),
  ('gomitas-de-frutas', 'Engrasa los moldes con aceite de coco para desmoldar las gomitas fácilmente · Guarda las gomitas en recipiente hermético en el refrigerador hasta 5 días · Manda las gomitas a la escuela con gel refrigerante para que no se ablanden'),
  ('granola-casera', 'Si la escuela es libre de frutos secos, cambia los frutos secos por la misma cantidad de semillas de girasol y calabaza: queda igual de crocante · Sirve la granola con yogur natural para que la granola se ablande'),
  ('guiso-arcoiris-de-verduras', 'Convierte el guiso en plato completo con huevo cocido en trocitos o pollo desmenuzado · Agrega el huevo o el pollo al momento de servir'),
  ('guiso-de-cerdo-con-papas-y-verduras', 'Si quieres el caldo más espeso, machaca unas papas dentro de la olla al final · Suma arvejas (chícharos) o champiñones junto con la zanahoria · Guarda las sobras en el refrigerador hasta 2 días'),
  ('guiso-de-pavo-con-papas-y-verduras', 'Guarda el guiso en el refrigerador hasta 3 días: sabe aún mejor al día siguiente · Congela el guiso en porciones individuales · Si quieres el guiso más espeso, machaca algunas papas y mezcla las papas con el caldo'),
  ('guiso-express-de-frijoles-y-platano-maduro', 'Elige plátano con la cáscara bien manchada de negro · Evita el plátano amarillo firme: queda duro y poco dulce · Congela el guiso en porciones individuales hasta 3 meses · Descongela el guiso la noche anterior en el refrigerador'),
  ('hamburguesa-de-salmon', 'Acompaña las hamburguesas con una salsa rápida de yogur natural, limón y eneldo · Congela las hamburguesas crudas separadas con papel para hornear · Descongela las hamburguesas en el refrigerador antes de cocinar'),
  ('hamburguesa-superpoderosa', 'Sirve el huevo entero bien cocido desde los 6 meses y observa 2-3 días · Congela las hamburguesas crudas o cocidas, separadas con papel, hasta 2 meses · Manda las hamburguesas frías con gel refrigerante para el mismo día'),
  ('hamburguesas-de-lentejas-y-papa', 'Si necesitas versión sin gluten, cambia el pan molido por harina de garbanzo o avena certificada · Congela las hamburguesas ya formadas, separadas con papel, hasta 3 meses · Acompaña las hamburguesas con tomate para aprovechar el hierro'),
  ('hamburguesas-de-pollo-con-aguacate', 'Si buscas versión sin gluten, cambia el pan molido por avena certificada sin gluten triturada · Congela las hamburguesas crudas separadas con papel para hornear · Cocina las hamburguesas directo del congelador y suma unos minutos'),
  ('hamburguesas-superpoderosas-de-pollo', 'Prepara el doble para cocinar de una vez para varios días · Congela las hamburguesas crudas separadas con papel para hornear hasta 2 meses · Si van a la lonchera, empaca las hamburguesas bien frías y siempre con gel refrigerante'),
  ('helado-cremoso-de-platano', 'Congela rodajas de plátano muy maduro y tendrás base de helado lista cualquier día · Agrega 1 cucharada de cacao en polvo sin azúcar para la versión de chocolate · Mezcla el plátano con yogur natural para un helado más cremoso'),
  ('helado-de-mango', 'Si la mezcla no gira en la licuadora, agrega 1 o 2 cucharadas de agua fría · Raspa los bordes de la licuadora y vuelve a licuar · Usa mango bien maduro y no necesitarás endulzante'),
  ('helado-de-mango-y-avena', 'Cambia el mango por 4 higos maduros lavados y sin tallo · Sirve el helado cremoso o semiderretido, nunca en trozos duros congelados: hay riesgo de atragantarse · Recuerda que la bebida de avena no sustituye la leche materna ni la fórmula'),
  ('helado-de-mango-y-yogur', 'Cambia el mango por fresas o plátano congelado para nuevos sabores · Si el helado pasa más de 1 hora en el congelador, vuelve a batir la mezcla antes de servir · Deja el helado 5 minutos fuera del congelador antes de porcionar'),
  ('helado-de-sandia', 'Pica finas unas hojas de menta · Agrega la menta a la capa de sandía para una versión aún más refrescante'),
  ('huevito-en-salsa-de-tomate', 'Duplica la salsa y guarda la salsa extra en el refrigerador hasta 3 días · Usa la salsa en pasta, arroz o para mojar tortillas · Si el tomate está ácido, ralla media zanahoria en la salsa mientras se cocina y redondea el sabor sin azúcar')
) AS v(slug, tip) WHERE r.slug = v.slug;UPDATE public.recipes r SET tips = v.tip FROM (VALUES
  ('huevos-de-colores', 'Prepara los tintes la noche anterior · Usa agua de remolacha para un rosado intenso · Usa cúrcuma para un amarillo brillante, sin colorantes artificiales'),
  ('huevos-escondidos-en-salsa-de-tomate', 'Si la salsa queda ácida, no agregues azúcar: cocina una zanahoria rallada fina junto con el tomate y la salsa se endulza sola · Prepara la salsa desde el mediodía y agrega los huevos a la hora de la cena'),
  ('huevos-revueltos-con-espinaca-y-queso', 'Cocina los huevos a fuego bajo · Revuelve los huevos suave para que queden cremosos y no secos'),
  ('huevos-revueltos-con-espinacas', 'Sirve los huevos el mismo día y no guardes la espinaca cocida para recalentar · Ofrece la espinaca en porciones moderadas, no todos los días, por sus nitratos · Si hay menores de 5 años, corta los tomates cherry en cuartos a lo largo'),
  ('hummus-clasico', 'Acompaña el hummus con bastones de zanahoria blanqueada o de pepino · Unta el hummus en pan integral · Avisa en la escuela que el tahini contiene sésamo (ajonjolí), un alérgeno'),
  ('hummus-de-remolacha', 'Cambia la remolacha por aguacate maduro para una versión verde · Avisa en la escuela que el tahini contiene sésamo (ajonjolí), un alérgeno'),
  ('jugo-vitamina-c', 'Manda el jugo a la lonchera en termo o botella bien fría con gel refrigerante · Sirve el jugo antes de 3-4 horas, porque pierde color y frescura · Ofrece la fruta entera en trocitos la mayoría de los días para dar más fibra'),
  ('laminas-crocantes-de-masa', 'Guarda las láminas en un recipiente hermético hasta 4-5 días · Si se ablandan, vuelve a hornear las láminas 3-4 minutos para recuperar lo crocante'),
  ('lasana-de-platano-maduro', 'Congela la lasaña ya horneada en porciones individuales hasta 2 meses · Manda la lasaña a la lonchera bien caliente en termo o bien fría con gel refrigerante · Sirve la lasaña antes de 4 horas'),
  ('lasana-de-pollo-y-espinacas', 'Agrega una capa de ricotta o requesón entre los pisos: la lasaña queda más cremosa y suma calcio · Congela la lasaña ya horneada en porciones individuales y tendrás almuerzos listos para los días con prisa'),
  ('lasana-de-verduras', 'Arma la lasaña un día antes · Guarda la lasaña tapada en el refrigerador · Hornea la lasaña justo antes de comer · Congela porciones individuales ya horneadas'),
  ('leche-de-avena-casera', 'Cuela la leche con un paño limpio para que quede bien lisa · Guarda la leche de avena en un frasco tapado hasta 3 días'),
  ('lentejitas-superpoderosas', 'Usa lentejas de frasco ya cocidas cuando tengas poco tiempo · Agrega las lentejas junto con el caldo · Cocina el guiso solo 15 minutos y queda listo en menos de media hora'),
  ('macarrones-con-queso-y-coliflor', 'Precalienta el termo con agua hirviendo 5 minutos · Llena el termo con los macarrones bien calientes para que lleguen calientes y seguros hasta el recreo'),
  ('macarrones-con-salsa-de-brocoli', 'Introduce cada alérgeno por separado: la pasta lleva gluten y la salsa puede llevar lácteos · Funde encima queso pasteurizado sin sal para los más grandes · Prepara la salsa al momento y no vuelvas a hervir ni a guardar la leche materna'),
  ('machacado-de-pollo-choclo-y-papa-con-trocitos', 'Guarda el caldo de cocción en un frasco aparte · Usa el caldo para ajustar la textura del machacado y para las papillas siguientes · Guarda el caldo 24 horas en el refrigerador o congela el caldo en porciones hasta 2 meses'),
  ('mantequilla-de-mani-casera', 'Cambia el maní por semillas de girasol tostadas para la lonchera, porque muchas escuelas son libres de maní · Guarda el frasco en el refrigerador hasta 1 mes'),
  ('manzana-asada-rellena-de-avena', 'Si no tienes horno, cocina las manzanas tapadas en el microondas 4 a 5 minutos a máxima potencia hasta que estén blandas · Elige manzanas dulces y maduras: gala, roja deliciosa o fuji · Evita las muy ácidas, porque piden azúcar'),
  ('medallones-de-pescado-blanco-y-papa', 'Hornea los medallones a 200 °C por 15-18 minutos para usar menos aceite · Voltea los medallones a la mitad del horneado · Agrega un poco de ralladura de limón a la mezcla para un toque fresco'),
  ('mermelada-de-fresa', 'Cambia las fresas por moras o mango para variar el sabor · Guarda la mermelada bien tapada en el refrigerador 5-7 días · Congela la mermelada en porciones pequeñas hasta 3 meses'),
  ('mini-lasana-de-carne-de-res', 'Agrega una capa fina de ricotta a la lasaña · Esconde zanahoria y calabacita ralladas en la salsa: suman verduras sin cambiar el sabor · Arma la lasaña con pollo o pavo molido si prefieres'),
  ('mini-lasanas-de-calabacita-y-atun', 'Asa las láminas de calabacita 2-3 minutos en sartén para que la lasaña no suelte agua · Usa atún claro en agua, el de menor contenido de mercurio · Ofrece el atún un par de veces por semana como máximo'),
  ('mini-lasanas-de-calabacita-y-pollo', 'Cambia el pollo por espinacas salteadas con champiñones para una versión vegetariana · Agrega una capa fina de ricotta entre los pisos y la lasaña queda extra cremosa'),
  ('mini-muffins-de-zanahoria-y-queso', 'Presenta los alérgenos (huevo, queso y avena) por separado la primera vez y observa 2-3 días · Usa queso pasteurizado y sin sal · Si los muffins van a la lonchera, suma un gel refrigerante · Usa avena certificada sin gluten'),
  ('mini-pizza-casera-con-tomates-cherry', 'Deja que cada niño arme su propia mini pizza con champiñones o espinaca picada: comen con más ganas lo que ellos mismos prepararon · Manda la pizza fría a la lonchera con gel refrigerante'),
  ('mousse-de-aguacate-y-cacao', 'Endulza la mousse solo con dátil: la miel no va antes de los 12 meses por riesgo de botulismo · Cambia los dátiles por medio plátano maduro y el cacao por harina de algarroba · Sirve la mousse con frutas o en pan integral'),
  ('mousse-de-chocolate-y-aguacate', 'Tapa la mousse con plástico pegado a la crema para que no se oscurezca en el refrigerador hasta 2 días · Agrega 2 cucharadas de crema batida fría o aquafaba (líquido de garbanzos cocidos) para más aire · Evita la clara de huevo cruda'),
  ('mousse-de-fresa-y-yogur', 'Evita las claras de huevo crudas en postres infantiles · Usa crema batida o 3 cucharadas de aquafaba (líquido de garbanzos) a punto de nieve · Usa yogur vegetal para la versión vegana · Refrigera y sirve la mousse antes de 24 horas'),
  ('muffins-de-avena-y-fresas', 'Ofrece fresas desde los 6 meses, no hace falta esperar al año · Presenta las fresas solas la primera vez y observa 2-3 días · Agrega el polvo de hornear y el aceite para una miga más esponjosa · Congela los muffins hasta 3 meses'),
  ('muffins-de-calabaza', 'Guarda los muffins tapados en el refrigerador hasta 4 días · Congela los muffins hasta 2 meses · Si los muffins van a la lonchera, suma un gel refrigerante · Evita cambiar la avena por harina de almendra o de coco: usa avena certificada'),
  ('muffins-de-manzana-y-canela', 'Presenta los muffins solos la primera vez y observa 2-3 días: llevan huevo y gluten · Usa avena certificada sin gluten si hay celiaquía · Guarda los muffins tapados a temperatura ambiente 1-2 días · Congela los muffins hasta 2 meses'),
  ('muslos-de-pollo-asados-con-manzana', 'Retira toda la carne del hueso, porque el pollo va con hueso · Revisa la carne con los dedos para descartar esquirlas antes de servir · Usa la manzana horneada para dar dulzor sin azúcar · Acompaña el pollo con puré de papa o camote'),
  ('nachos-caseros', 'Sazona los nachos recién salidos del horno con paprika (pimentón dulce), ajo en polvo o comino · Sirve los nachos con guacamole o salsa de yogur · Guarda los nachos en frasco hermético hasta 3 o 4 días y siguen crujientes'),
  ('natilla-de-maiz-con-pera', 'Usa una pera muy madura: es lo único que endulza la natilla · Si la pera está dura, la natilla queda desabrida · Guarda la natilla tapada en el refrigerador hasta 2 días · Evita congelar la natilla: la fécula se separa y queda aguada'),
  ('nido-de-pan-integral-con-huevo', 'Tuesta en la misma sartén los círculos de pan que sacaste del centro · Sirve los círculos crocantes para que tu hijo moje el huevo · Revisa que el primer ingrediente del pan sea harina integral y que no lleve azúcar añadida'),
  ('nuggets-de-brocoli', 'Prepara doble tanda y cocina de una vez para varios días · Congela los nuggets ya cocidos hasta 2 meses · Pasa los nuggets del congelador a la lonchera térmica con gel refrigerante y se descongelan para el recreo'),
  ('nuggets-de-pollo', 'Congela los nuggets empanizados y sin cocinar hasta 2 meses · Hornea los nuggets directo del congelador · Suma 5 minutos al tiempo indicado si horneas los nuggets congelados'),
  ('nuggets-de-pollo-caseros', 'Congela los nuggets empanizados en crudo, separados con papel para hornear, hasta 2 meses · Hornea los nuggets congelados y suma 5 minutos · Empaca los nuggets fríos con gel refrigerante · Si buscas versión sin gluten, usa harina de maíz'),
  ('nuggets-de-pollo-sin-huevo', 'Sirve los nuggets con salsa de tomate casera sin sal o puré de verduras · Congela los nuggets ya horneados hasta 2 meses · Usa muslo en vez de pechuga para más jugosidad · Si necesitas versión sin gluten, usa pan rallado y avena sin gluten'),
  ('omelette-de-calabacita', 'Agrega queso rallado o un poco de orégano a la mezcla para variar el sabor · Si quieres el omelette más esponjoso, bate los huevos con una cucharada de leche antes de cocinar')
) AS v(slug, tip) WHERE r.slug = v.slug;UPDATE public.recipes r SET tips = v.tip FROM (VALUES
  ('omelette-de-papa-y-brocoli', 'Corta el omelette frío en cubos para la lonchera · Empaca el omelette bien frío con gel refrigerante · Agrega queso rallado a la mezcla para un omelette más cremoso · Deja que los niños separen el brócoli en arbolitos con las manos'),
  ('omelette-de-verduritas', 'Bate los huevos con una cucharada de leche para un omelette más esponjoso · Agrega un poco de queso rallado justo antes de doblar el omelette'),
  ('paletas-de-sandia-y-kiwi', 'Usa fruta bien madura y no necesitas endulzante · Evita la miel, sobre todo en menores de 2 años · Varía las capas con mango, durazno o fresas · Congela las paletas hasta 3 meses, con mejor sabor las primeras 2 semanas'),
  ('paletas-heladas-de-fruta', 'Agrega yogur natural para paletas más cremosas · Congela capas de frutas de distintos colores por etapas para un efecto arcoíris · Si no tienes moldes, usa vasitos de yogur y clava palitos de madera cuando la mezcla esté medio firme'),
  ('palitos-crocantes-de-avena-y-ajonjoli', 'Guarda los palitos parados en un frasco de vidrio con tapa hasta 10 días · Si los palitos se ablandan con la humedad, hornea los palitos 5 minutos a 160 °C y vuelven a quedar crujientes'),
  ('palitos-de-arroz', 'Enfría el arroz cocido rápido, porque el arroz tibio puede desarrollar la bacteria Bacillus cereus · Guarda el arroz en el refrigerador máximo 24 horas · Cambia la zanahoria por calabaza (zapallo) cocida y machacada'),
  ('palitos-de-verduras', 'Envía los bastones de verdura en un contenedor hermético con un paño húmedo y llegan crujientes · Empaca la salsa de yogur en un frasquito cerrado junto al gel refrigerante'),
  ('palomitas-de-maiz', 'Si quieres palomitas saladas sin azúcares, omite la miel y la canela · Usa solo la mantequilla con una pizca de sal · Guarda las palomitas en un frasco hermético hasta 2 días'),
  ('pan-de-calabacin', 'Rebana el pan y congela las rebanadas con papel encerado entre cada una · Descongela las rebanadas en el tostador en minutos para armar sándwiches · Usa las rebanadas como base con guacamole'),
  ('pan-de-camote-y-ajonjoli', 'Guarda el pan envuelto en papel dentro de un frasco hermético hasta 3 días a temperatura ambiente · Congela las rebanadas separadas con papel encerado · Manda una rebanada congelada en la lonchera y llega descongelada y fresca al recreo'),
  ('pan-de-queso', 'Congela las bolitas crudas en una bandeja y luego en bolsa · Hornea las bolitas directo del congelador y suma 5 minutos · Si no tienes horno, cocina las bolitas tapadas en sartén a fuego medio-bajo 15 a 20 minutos, girando hasta dorar'),
  ('pan-integral-casero', 'Rebana el pan ya frío y congela las rebanadas separadas con papel encerado · Saca solo las rebanadas que necesitas: se descongelan en minutos para la lonchera · Agrega semillas de chía o linaza a la masa'),
  ('pan-rosado', 'Pinta los panecillos con un poco de aceite antes de hornear · Espolvorea semillas de ajonjolí o chía · Congela los panecillos ya horneados en bolsa cerrada · Pasa un panecillo congelado a la lonchera y se descongela solo a media mañana'),
  ('panecitos-de-maiz-y-choclo', 'Guarda los panecitos bien tapados hasta 2 días a temperatura ambiente · Congela los panecitos hasta 3 meses · Agrega a la mezcla una cucharada de perejil picado o de zanahoria rallada fina antes de hornear'),
  ('panqueques-de-banana', 'Agrega 2 cucharaditas de cacao puro en polvo para versión de chocolate · Guarda los panqueques 3 días en el refrigerador o 2 meses en el congelador · Descongela los panqueques en el refrigerador la noche anterior a la lonchera'),
  ('panqueques-de-camote', 'Cocina el camote la noche anterior o usa puré congelado y tendrás panqueques en 15 minutos · Congela los panqueques ya listos y recalienta en sartén o tostadora · Manda los panqueques fríos con gel refrigerante, porque llevan huevo'),
  ('panqueques-de-espinaca', 'Ofrece la espinaca en porciones pequeñas y ocasionales antes del año, porque la espinaca concentra nitratos · Congela los panqueques separados con papel encerado hasta 2 meses'),
  ('panqueques-de-manzana-y-canela', 'Congela los panqueques con papel para hornear entre uno y otro · Recalienta los panqueques en tostadora o sartén · Agrega 1 cucharada de yogur natural a la masa para más proteína · Manda los panqueques con gel refrigerante en la lonchera'),
  ('panqueques-de-papa-y-calabacita', 'Agrega zanahoria rallada o espinaca picada a la masa para variar el color · Hornea los panqueques a 200 °C unos 15 minutos en lugar de usar sartén · Voltea los panqueques a la mitad del horneado'),
  ('panqueques-de-platano-y-avena', 'Ofrece el huevo solo la primera vez y observa 2-3 días por alergia · Cocina los panqueques hasta que no queden partes líquidas · Congela los panqueques separados con papel hasta 2 meses · Manda los panqueques con gel refrigerante'),
  ('papas-empanizadas-al-horno', 'Espolvorea queso parmesano rallado sobre los gajos de papa · Agrega el parmesano antes de hornear para un toque extra de sabor'),
  ('papilla-de-avena-con-platano', 'Si hay celiaquía en casa, usa avena certificada sin gluten · Cocina la avena en agua y agrega la leche materna tibia al final · Evita hervir la leche materna: pierde nutrientes · Prepara la papilla al momento para conservar nutrientes'),
  ('papilla-de-avena-y-pera', 'Si en casa hay celiaquía, usa avena certificada sin gluten · Si usas leche materna o fórmula, cocina la avena en agua y agrega la leche tibia al final, fuera del fuego · Congela la papilla en cubetera hasta 3 meses'),
  ('papilla-de-carne-de-res-y-papa', 'Sirve una fruta o verdura con vitamina C en la misma comida para aprovechar mejor el hierro de la carne · Congela la papilla en porciones individuales hasta 2 meses'),
  ('papilla-de-cereal-con-leche-materna', 'Introduce un cereal a la vez y espera 2-3 días antes de probar otro · Si hay celiaquía, elige cereal certificado sin gluten · Agrega la leche materna tibia al final, nunca hervida · Descarta las sobras con saliva del bebé'),
  ('papilla-de-espinaca-y-ricotta', 'Espera a los 12 meses: la espinaca es rica en nitratos · Sirve porciones pequeñas y guarda la papilla máximo 24 horas sin recalentar · Usa ricotta pasteurizada y sin sal · Ofrece la ricotta sola la primera vez y observa 2-3 días'),
  ('papilla-de-frijoles-negros-y-platano', 'Aplasta o tritura muy bien los frijoles antes del año para evitar atragantamientos · Prepara los frijoles sin sal · Congela la papilla en porciones hasta 3 meses'),
  ('papilla-de-frutas-mixtas', 'Ofrece las fresas desde los 6 meses, aunque son un alérgeno a vigilar · Introduce las fresas solas, en poca cantidad y de día la primera vez · Observa 2-3 días después de dar fresas · Congela la papilla en cubetera hasta 3 meses'),
  ('papilla-de-kiwi-y-espinaca', 'Ofrece el kiwi solo la primera vez y observa 2-3 días por alergia · Sirve poca espinaca antes de los 12 meses, porque contiene nitratos · Consume la papilla el mismo día · Prepara la papilla fresca, sin congelar'),
  ('papilla-de-lentejas-y-calabaza', 'Aplasta las lentejas sin dejar grumos antes de los 12 meses para evitar atragantamientos · Sirve una fruta rica en vitamina C, como naranja o mango, para aprovechar mejor el hierro · Congela la papilla en porciones hasta 3 meses'),
  ('papilla-de-lentejas-y-zanahoria', 'Agrega unas gotas de jugo de limón o naranja al servir: ayuda a aprovechar el hierro de las lentejas · Cocina y tritura muy bien las lentejas antes de los 12 meses para evitar atragantamientos · Congela la papilla en cubetera hasta 3 meses'),
  ('papilla-de-maiz-y-pavo', 'Cocina el pavo sin sal: es una carne magra y muy suave para el bebé · Congela la papilla que no uses el mismo día en porciones individuales hasta 2 meses'),
  ('papilla-de-mango-y-aguacate', 'Sirve la papilla recién hecha: el aguacate se oscurece al reposar · Si quieres una textura más suave o un sabor de mango menos fuerte, mezcla la papilla con un poco de plátano maduro'),
  ('papilla-de-pasta-con-tomate-y-espinaca', 'Ofrece la espinaca en porción pequeña y ocasional antes de los 12 meses: concentra nitratos · Sirve la papilla recién hecha, máximo 24 horas y sin recalentar · Prueba la pasta de trigo sola la primera vez y observa 2 o 3 días: tiene gluten'),
  ('papilla-de-pera-y-yogur', 'Usa yogur natural entero, pasteurizado y sin azúcar · Ofrece el yogur solo la primera vez y observa 2 o 3 días: es alérgeno · Consume la papilla dentro de 24 horas · Evita congelar la papilla: el yogur se corta'),
  ('papilla-de-pollo-con-arroz-integral', 'Refrigera el arroz cocido de inmediato · Consume la papilla dentro de 24 horas · Acompaña la papilla con una fruta rica en vitamina C, como naranja o mango, para aprovechar el hierro del pollo'),
  ('papilla-de-pollo-y-calabacin', 'Cocina una pechuga extra y congela la papilla en porciones hasta 2 meses · Usa siempre caldo casero sin sal · Agrega una cucharadita de aceite de oliva al final si quieres más energía'),
  ('papilla-de-quinoa-con-mango', 'Lava muy bien la quinua antes de cocinarla para quitar el sabor amargo natural · Elige un mango bien maduro: conserva mejor el color · Congela la papilla en porciones hasta 3 meses'),
  ('papilla-de-quinoa-espinaca-y-queso', 'Usa queso fresco pasteurizado y sin sal · Prepara la papilla al momento, máximo 24 horas y sin recalentar: la espinaca tiene nitratos · Sirve porciones pequeñas antes del año · Ofrece el queso solo la primera vez y observa 2-3 días'),
  ('papilla-de-salmon-y-camote', 'Ofrece el salmón solo la primera vez, en poca cantidad y de día: el pescado es un alérgeno frecuente · Observa 2 o 3 días antes de repetir el salmón · Congela la papilla en porciones individuales hasta 2 meses')
) AS v(slug, tip) WHERE r.slug = v.slug;UPDATE public.recipes r SET tips = v.tip FROM (VALUES
  ('papilla-de-vegetales-suaves', 'Cuela el puré si tu bebé recién empieza: queda mucho más fino · Usa caldo casero sin sal y nunca cubos comerciales, que tienen demasiado sodio · Congela el puré en cubetera hasta 3 meses'),
  ('papilla-de-yogur-con-frutas-y-granola', 'Ofrece el yogur solo la primera vez y observa 2 o 3 días: es un lácteo · Usa yogur natural pasteurizado y sin azúcar · Muele la granola muy fina y solo desde los 12 meses, nunca entera'),
  ('papilla-suave-de-pollo-y-arroz', 'Refrigera el arroz cocido de inmediato · Consume la papilla dentro de 24 horas o congela la papilla en porciones hasta 2 meses · Agrega la cúrcuma solo si quieres: aporta color y aroma suaves'),
  ('pasta-con-brocoli-y-queso', 'Si agregas almendras tostadas, muele las almendras primero: enteras o en láminas no son seguras antes de los 5 años · Cambia la leche por caldo de verduras si quieres una salsa más ligera'),
  ('pasta-con-espinacas-y-pollo', 'Si a tu hijo le cuestan las espinacas, pica las espinacas muy finas para que se fundan con la salsa · Ofrece un alimento nuevo 10 a 15 veces en distintas ocasiones: la aceptación toma tiempo'),
  ('pasta-con-pavo-y-pimientos', 'Agrega una pizca de cúrcuma o comino: da color dorado y un aroma que suele gustar a los niños · Corta el pavo en tiras delgadas y parejas para que se cocine rápido y quede jugoso'),
  ('pasta-de-aguacate', 'Prepara la salsa el mismo día que la sirvas: el jugo de limón retrasa que el aguacate se oscurezca · Empaca la salsa bien fría con gel refrigerante si va en la lonchera · Sirve la pasta antes de 4 horas'),
  ('pasta-jardin-de-verduras', 'Prepara el doble de salsa y congela la salsa extra en porciones hasta 3 meses: te sirve para pasta, arroz o pizza · Agrega albahaca fresca al servir para un toque especial'),
  ('pastel-de-avena-y-platano', 'Conserva la harina de avena: coco y almendra absorben distinto y arruinan la masa · Usa avena certificada sin gluten si hace falta · Refrigera el pastel tapado hasta 3 días · Suma gel refrigerante en la lonchera: lleva huevo'),
  ('pastel-de-naranja', 'Baña el pastel aún tibio con un par de cucharadas de jugo de naranja extra · Sirve el pastel sin glaseado: así queda húmedo y aromático'),
  ('pastel-de-zanahoria-sin-azucar-refinada', 'Separa los huevos en el paso 2 y suma las claras batidas al final: el pastel queda más esponjoso · Refrigera el pastel desde el primer día si hace calor · Conserva el pastel hasta 2 días a temperatura ambiente en recipiente hermético'),
  ('pescadito-dorado-con-pure-cremoso', 'Usa cualquier pescado blanco local: merluza, corvina o tilapia funcionan igual · Sirve el puré en forma de nube o volcán y deja que tu hijo ponga el pescado encima · Juega con la presentación: ayuda con los niños más reservados'),
  ('pescado-blanco-con-salsa-de-kiwi', 'Introduce el pescado y el kiwi por separado: observa 2 o 3 días cada alérgeno · Revisa el pescado con los dedos y quita las espinas · Sirve la salsa de kiwi recién hecha, sin guardar sobras · Refrigera el pescado cocido máximo 24 horas'),
  ('picadillo-de-res-con-zanahoria-y-arvejas', 'Desarma la carne molida con una cuchara de madera apenas cae a la sartén · Evita dejar la carne en bloque: suelta agua, se cuece al vapor y queda gris · Congela el picadillo en porciones planas hasta 2 meses'),
  ('pie-de-limon', 'Si en la escuela no permiten maní, prepara la base con crema de semillas de girasol · Empaca el pie en un frasco pequeño con tapa · Suma siempre gel refrigerante en la lonchera'),
  ('pina-asada', 'Espolvorea una pizca de canela al servir para realzar el dulzor · Guarda la piña asada en un recipiente hermético: fría también es deliciosa · Envía la piña con gel refrigerante en días calurosos'),
  ('pinchos-de-frutas-con-chocolate', 'Corta la fruta en rodajas gruesas y dale formas con moldes · Inserta un solo palito por figura · Baña la fruta hasta la mitad en chocolate derretido y espolvorea coco rallado antes de que seque · Suma gel refrigerante en la lonchera'),
  ('pizza-de-berenjena', 'Cambia el jamón por pollo cocido desmenuzado o tofu para variar la proteína · Recalienta las sobras en horno o sartén, nunca en microondas: la berenjena queda aguada'),
  ('pizza-de-coliflor-blw', 'Usa avena certificada sin gluten para que la pizza sea realmente sin gluten · Cubre la pizza con verduras ralladas o pollo cocido para una cena más completa · Corta la pizza en tiras: así tu bebé agarra mejor'),
  ('pizza-de-pollo', 'Cambia el pollo por coliflor rallada, cocida y bien escurrida para una versión vegetariana · Envía la pizza fría en la lonchera, en porciones pequeñas y con gel refrigerante'),
  ('pizza-de-pollo-y-queso', 'Si no tienes base, prepara la de coliflor o una masa integral casera · Usa siempre pollo ya cocido y queso pasteurizado sin sal · Agrega verduras ralladas para más color y nutrientes'),
  ('platano-maduro-dorado-con-queso-fresco', 'Si prefieres evitar la sartén, hornea las rodajas 20 minutos a 200 °C sobre papel para hornear · Voltea las rodajas a la mitad del horneado · Elige plátano bien maduro: el verde queda duro, seco y nada dulce'),
  ('pollo-a-la-naranja', 'Precalienta el termo con agua hirviendo 5 minutos, vacía el termo y agrega el pollo bien caliente · Acompaña el pollo con arroz · Sirve este plato de forma ocasional: lleva una cucharadita de miel'),
  ('pollo-a-la-naranja-para-bebe', 'Ofrece este pollo a partir de los 12 meses: el jugo de naranja se reduce y concentra su dulzor natural · Acompaña el pollo con arroz o papa blanda para una comida completa'),
  ('pollo-al-horno-con-verduras', 'Marina el pollo con el aceite y las especias 30 minutos antes, siempre dentro del refrigerador: queda más jugoso · Prueba también con tomillo y romero'),
  ('pollo-guisado-con-pimientos-y-tomate', 'Asa el pimiento antes de triturarlo: la piel sale fácil y el pimiento queda más digerible y dulce · Usa siempre caldo casero sin sal · Sirve el pollo con arroz o puré de papa para una comida completa'),
  ('postre-dulce-de-aguacate', 'Cambia la crema de leche por yogur griego natural si quieres una versión más ligera · Prepara el postre máximo un día antes de servirlo · Agrega el jugo de limón: mantiene el color verde'),
  ('puchero-suave-con-garbanzos', 'Prepara el puchero con carne de res magra o muslo de pollo sin piel · Usa caldo casero sin sal · Agrega puré de calabaza o camote para una textura más aterciopelada · Refrigera el puchero 48 horas o congela porciones hasta 2 meses'),
  ('pudin-de-chocolate', 'Cubre cada vasito con plástico tocando la superficie mientras el pudín se enfría para que no forme nata · Empaca el pudín en recipiente hermético con gel refrigerante para la lonchera'),
  ('pure-de-berenjena', 'Combina la berenjena con papa, zanahoria o calabaza para suavizar el sabor y dar más cuerpo al puré · Pela bien la berenjena para quitar el amargor · Congela el puré en porciones individuales hasta 3 meses'),
  ('pure-de-brocoli-y-espinaca', 'Ofrece la espinaca en poca cantidad y como acompañamiento antes de los 12 meses: tiene nitratos · Sirve el puré recién hecho, sin recalentar · Guarda el puré hasta 24 horas máximo · Si tu bebé rechaza el verde, agrega manzana'),
  ('pure-de-brocoli-y-pollo', 'Agrega una cucharadita de aceite de oliva al final para dar energía y aprovechar las vitaminas del brócoli · Congela el puré en porciones individuales hasta 2 meses'),
  ('pure-de-calabacin-y-papa', 'Agrega una cucharadita de aceite de oliva al servir para aprovechar mejor las vitaminas · Congela el puré en cubetera de hielo · Descongela solo los cubos que vas a usar'),
  ('pure-de-calabaza-asada-y-manzana', 'Elige una calabaza pesada y de piel firme para un sabor más dulce · Si no quieres encender el horno, cocina la calabaza y la manzana al vapor · Congela el puré en porciones individuales hasta 3 meses'),
  ('pure-de-espinaca-y-papa', 'Prepara el puré al momento: la espinaca concentra nitratos · Guarda el puré máximo 24 horas, sin recalentar · Ofrece porciones pequeñas a menores de 1 año · Agrega una gota de aceite de oliva para aprovechar las vitaminas'),
  ('pure-de-espinacas-y-papa', 'Ofrece este puré en porciones pequeñas y ocasionales a menores de 1 año: las espinacas concentran nitratos · Evita servir el puré de espinacas todos los días · Agrega queso rallado al final para un puré más cremoso'),
  ('pure-de-fresas-y-platano', 'Ofrece fresa desde los 6 meses: es un alérgeno frecuente · Da la fresa sola la primera vez y observa 2 o 3 días · Sirve la fresa cruda: cocinar la fresa no reduce el riesgo de alergia · Prepara el puré fresco para que no se oscurezca'),
  ('pure-de-lentejas-y-calabacin', 'Tritura o aplasta bien las lentejas antes de los 12 meses para evitar atragantamientos · Agrega una pizca de comino para dar aroma sin usar sal · Congela el puré en porciones individuales hasta 3 meses'),
  ('pure-de-mango-y-coco', 'Prepara el puré justo antes de servir: sin cocción se disfruta mejor recién hecho · Guarda el puré máximo un día en el refrigerador · Usa leche de coco natural sin azúcar añadida'),
  ('pure-de-papa-con-brocoli', 'Precalienta el termo con agua caliente 5 minutos · Vacía el agua y llena el termo con el puré bien caliente · Cierra el termo: el puré se mantiene a temperatura segura hasta el almuerzo · Agrega queso rallado para un puré más cremoso')
) AS v(slug, tip) WHERE r.slug = v.slug;UPDATE public.recipes r SET tips = v.tip FROM (VALUES
  ('pure-de-papa-y-aguacate', 'Mezcla solo el aguacate que vas a servir: al reposar se oscurece y amarga · Agrega el resto del aguacate justo al momento de servir · Guarda el puré sobrante tapado en el refrigerador y sirve el puré ese mismo día'),
  ('pure-de-papa-y-coliflor', 'Congela el puré en cubetera de hielo · Descongela solo los cubos que vas a usar · Agrega una cucharadita de aceite de oliva al servir para sumar energía y suavizar el puré'),
  ('pure-de-pera-y-papa', 'Elige una pera bien madura para dar dulzor sin endulzar · Congela el puré en cubetera de hielo hasta 3 meses · Descongela solo los cubos que vas a usar'),
  ('pure-de-remolacha-y-naranja', 'Ofrece poca remolacha antes de los 12 meses: tiene nitratos · Guarda el puré hasta 24 horas · Usa la naranja entera triturada, no en jugo: el jugo no se recomienda antes del año · Si el pañal se tiñe de rojo, es normal por la remolacha'),
  ('pure-de-sandia-y-fresas', 'Ofrece la fresa sola, en poca cantidad y de día la primera vez: es un alérgeno a vigilar · Observa a tu peque 2 o 3 días después · Congela el puré en moldes de paleta para los más grandes: es un premio ideal para el calor'),
  ('pure-de-zanahoria-y-chirivia', 'Si no encuentras chirivía, usa una papa blanca o más zanahoria: el puré queda igual de rico · Congela el puré en cubetera de hielo hasta 3 meses'),
  ('pure-de-zanahoria-y-papa', 'Agrega una cucharadita de aceite de oliva al servir para absorber mejor las vitaminas y suavizar el puré · Congela el puré en cubetera y descongela solo los cubos que necesitas · Usa siempre caldo casero sin sal'),
  ('pure-espeso-de-camote-y-papa', 'Mezcla este puré con pollo desmenuzado o lentejas bien aplastadas para armar un plato completo · Congela el puré en cubetera · Descongela solo los cubos que vas a usar'),
  ('pure-rapido-de-platano-y-durazno', 'Prepara el puré justo antes de servir: el plátano se oscurece enseguida con el aire · Si tu peque recién empieza, ofrece el durazno solo unos días antes de combinar las frutas · Observa cómo tolera el durazno'),
  ('quequitos-de-pure-de-manzana', 'Cambia la manzana por puré de pera o durazno maduro: el dulzor viene solo de la fruta · Ofrece el huevo solo y observa 2 o 3 días la primera vez: estos quequitos llevan huevo · Congela los quequitos hasta 2 meses'),
  ('quesadilla-mananera-de-frijol-y-queso', 'Prepara el doble de pasta de frijol y guarda la pasta tapada en el refrigerador hasta 3 días · Usa esa pasta para untar pan o rellenar arepas · Si tu niño recién empieza, cuela los frijoles para quitar las cáscaras y suavizar la pasta'),
  ('quesadillas-de-atun-y-calabacita', 'Escurre muy bien la calabacita rallada apretando con las manos · Si la calabacita suelta agua, la tortilla queda blanda · Guarda el relleno tapado en el refrigerador hasta 24 horas · Sirve el relleno al día siguiente sobre pan tostado'),
  ('quinoa-con-verduras-al-vapor', 'Enjuaga bien la quinua antes de cocinar para quitar el sabor amargo · Agrega pollo desmenuzado o lentejas aplastadas para una comida más completa · Congela solo la versión sin proteína animal hasta 3 meses'),
  ('quinua-salteada-con-pavo-y-verduras', 'Cocina el doble de quinua el domingo y guarda la quinua en el refrigerador · Arma esta cena en 10 minutos cualquier día con la quinua ya lista'),
  ('risotto-de-champinones', 'Usa arroz redondo tipo arborio: su almidón da la cremosidad · Si solo tienes arroz integral, no será un risotto tradicional: cocina el arroz aparte 40-45 minutos con más caldo · Mezcla el arroz al final con los champiñones y el queso'),
  ('rollitos-de-banana', 'Si el colegio no permite maní, unta crema de semillas de girasol · Empaca las rueditas en recipiente hermético con gel refrigerante · Sirve las rueditas el mismo día'),
  ('rollitos-de-calabacita-y-jamon', 'Elige jamón cocido de buena calidad y bajo en sal: el jamón es un embutido · Sirve estos rollitos de jamón solo de vez en cuando · Cambia el jamón por pechuga de pavo natural: funciona igual de bien'),
  ('rollitos-de-jamon', 'Empaca los rollitos con gel refrigerante · Consume los rollitos antes de 4 horas · Reserva estos rollitos para loncheras ocasionales: el jamón es un embutido · Alterna el jamón con pollo cocido y desmenuzado en casa'),
  ('rollitos-de-pan-rellenos', 'Si la escuela no permite maní, rellena los rollitos con crema de semillas de girasol · Prueba también relleno de queso crema con fruta: queda igual de rico y es seguro para todos los compañeros'),
  ('rollitos-de-sandwich-estilo-sushi', 'Empaca los rollitos con gel refrigerante: el pescado nunca debe viajar sin frío · Sirve los rollitos antes de 4 horas · Suma tiras finas de aguacate o pimiento morrón al relleno'),
  ('rollo-de-zanahoria', 'Envuelve el rollo en papel encerado para la lonchera · Lleva el rollo siempre con gel refrigerante · Sirve el rollo antes de 4 horas'),
  ('salchichas-de-pollo-caseras', 'Congela las salchichas ya cocidas hasta 2 meses · Descongela las salchichas en el refrigerador la noche anterior · Empaca las salchichas en lonchera térmica con gel refrigerante · Sirve las salchichas antes de 4 horas'),
  ('salpicon-de-frutas', 'Empaca el salpicón frío en recipiente hermético con gel refrigerante · Agrega canela o ralladura de limón · Tritura fino los frutos secos y confirma los alérgenos con la escuela · Sirve solo la fruta picada sin jugo antes de los 12 meses'),
  ('salsa-de-algarroba', 'Sirve la salsa tibia o fría sobre panqueques, avena o frutas blandas · Usa algarroba en lugar de cacao: no tiene cafeína ni teobromina · Guarda la salsa tapada en el refrigerador hasta 3 o 4 días'),
  ('salsa-de-tomate-casera', 'Prepara esta salsa para varias comidas · Guarda la salsa en frasco en el refrigerador hasta 4 días · Congela la salsa en porciones hasta 3 meses · Sirve la salsa desde los 12 meses con pollo en trocitos pequeños dorado en la sartén'),
  ('sandwich-de-frutas', 'Rocía la banana y el aguacate con unas gotas de jugo de limón para que no se oscurezcan hasta el recreo · Empaca el sándwich con gel refrigerante'),
  ('snack-de-manzana', 'Rocía las rodajas de manzana con unas gotas de jugo de limón para que no se oxiden en la lonchera · Si la escuela es libre de maní, cambia la crema de maní por crema de semillas de girasol, que no es un fruto seco'),
  ('sopa-casera-de-verduras-con-fideos', 'Congela la sopa en porciones individuales · Sirve una porción como cena de emergencia en los días sin tiempo'),
  ('sopa-de-fideos-con-pollo-y-zanahoria', 'Cuece los fideos aparte si vas a guardar sobras, porque siguen absorbiendo caldo · Une los fideos y el caldo al momento de servir para que no se deshagan · Corta el pollo en tiras delgadas y se cocina en la mitad del tiempo'),
  ('sorbete-de-mango-y-avena', 'Añade un poco de yogur natural antes de licuar · Licúa hasta que el sorbete de mango quede bien cremoso'),
  ('tacos-caseros', 'Empaca el relleno aparte para que las tortillas no se humedezcan · Deja que tu hijo arme el taco en el recreo · Manda la lonchera con gel refrigerante · Cambia el pollo por lentejas o champiñones salteados para la versión vegetariana'),
  ('tallarines-con-salsa-de-calabaza', 'Asa la calabaza en vez de hervir la calabaza, así concentra su dulzor y la salsa queda más sabrosa · Prepara doble cantidad de salsa · Congela la salsa extra en porciones para una cena exprés'),
  ('tarta-de-cacao-y-espelta-inflada', 'Cambia el cacao por la misma cantidad de harina de algarroba para evitar la teobromina en los niños menores · Ofrece esta tarta ocasionalmente por los azúcares concentrados de los dátiles triturados · Recuerda que la espelta tiene gluten'),
  ('tarta-de-manzana-sin-azucar', 'Cambia el huevo por medio plátano maduro machacado o por 1 cucharada de chía en 3 de agua · Ofrece el huevo y la avena en poca cantidad la primera vez y observa 2-3 días, son alérgenos · Refrigera la tarta hasta 48 horas'),
  ('tarta-fria-de-fresas-y-platano', 'Ofrece la tarta ocasionalmente, no a diario, por los azúcares concentrados de los dátiles y las pasas · Guarda la tarta tapada en el refrigerador hasta 24 horas · Prueba las fresas solas la primera vez y observa 2-3 días, son un alérgeno'),
  ('tequenos', 'Congela los tequeños crudos hasta 2 meses · Hornea los tequeños directo del congelador y suma unos minutos · Empaca la lonchera con gel refrigerante y sirve los tequeños antes de 4 horas'),
  ('tilapia-al-horno-con-tomate-y-perejil', 'Si el filete es más delgado que un dedo, baja el tiempo a 15 minutos justos para que no se reseque · Cubre el filete con papel aluminio los primeros 8 minutos · Usa otro pescado blanco (basa, corvina, merluza, bagre) con el mismo tiempo'),
  ('torrejas-blw-sin-lactosa', 'Usa bebida de avena en lugar de bebida de almendras si quieres evitar los frutos secos · Sirve las torrejas con puré de fruta · Introduce el huevo, los frutos secos y el gluten por separado y observa 2-3 días cada alérgeno'),
  ('torta-de-avena-y-zanahoria', 'Hornea la masa en moldes de muffin de 15 a 18 minutos para porciones individuales de lonchera · Congela los muffins horneados · Saca un muffin del congelador la noche anterior'),
  ('torta-de-pera-y-remolacha', 'Corta la torta en cuadritos y congela los cuadritos por separado · Pon un cuadrito congelado en la lonchera en la mañana · Sirve el cuadrito ya descongelado en el recreo')
) AS v(slug, tip) WHERE r.slug = v.slug;UPDATE public.recipes r SET tips = v.tip FROM (VALUES
  ('tortilla-colorida', 'Ofrece el huevo solo la primera vez y observa 2-3 días, es un alérgeno · Usa poca espinaca antes de los 12 meses por sus nitratos, o mejor omite la espinaca · Empaca la tortilla fría con gel refrigerante y en tiras del grosor de un dedo'),
  ('tortilla-de-huevo-doradita', 'Observa 2-3 días al introducir el huevo y el queso, son alérgenos · Suma una cucharada de espinaca cocida y picada fina, mejor desde los 12 meses o muy poca cantidad antes · Evita recalentar la espinaca sobrante'),
  ('tortilla-de-papa-y-zanahoria-al-horno', 'Corta la tortilla en cuadritos y guarda los cuadritos tapados en el refrigerador · Sirve los cuadritos en la cena, en la lonchera del día siguiente o como merienda'),
  ('tortilla-de-papas-blw', 'Sirve la tortilla tibia o fría · Guarda la tortilla en el refrigerador hasta 48 horas · Empaca la tortilla con un gel refrigerante si va en la lonchera'),
  ('tortilla-de-quinua-y-arroz', 'Si cocinas la quinua desde cero, enjuaga los granos bajo el chorro de agua antes de la cocción · Quita así el amargor natural de la cubierta de la quinua'),
  ('tortipizza-de-calabacita-y-jamon', 'Usa el jamón cocido solo de vez en cuando, es carne procesada · Elige un jamón de buena calidad y bajo en sal · Cambia el jamón por pechuga de pollo o pavo natural desmenuzada · Empaca la tortipizza bien fría con gel refrigerante'),
  ('tortitas-de-calabaza', 'Congela las tortitas con papel de horno entre capas hasta 2 meses · Calienta las tortitas directo en el tostador o la sartén · Acompaña la lonchera con yogur natural o fruta fresca y un gel refrigerante'),
  ('tortitas-de-lentejas', 'Cocina de una vez para varios días · Congela las tortitas ya cocidas hasta 2 meses · Descongela las tortitas en el refrigerador la noche anterior a la lonchera'),
  ('tortitas-de-papa-y-queso', 'Forma bolitas ovaladas para la versión ratoncitos · Decora las bolitas antes de hornear con trocitos de aceituna para los ojos y láminas finas de zanahoria cocida para las orejas · Empaca las tortitas con un gel refrigerante'),
  ('tostadas-francesas', 'Si la escuela es libre de frutos secos, decora las tostadas con semillas de girasol molidas · Empaca las tostadas ya frías en la lonchera con un gel refrigerante'),
  ('tostadas-rellenas-de-yogur-y-frutas', 'Prepara las tostadas la noche anterior · Deja las tostadas en el refrigerador hasta la mañana · Empaca la lonchera con gel refrigerante · Sirve las tostadas frías, como un pastelito de queso'),
  ('trufas-de-cacao-y-coco', 'Guarda las trufas en un recipiente hermético en el refrigerador hasta 5 días · Empaca las trufas en la lonchera con un gel refrigerante · Si la escuela es libre de maní, prepara las trufas con crema de semillas de girasol'),
  ('trufas-de-pasas-y-coco', 'Aplana cada trufa en un disco fino hasta los 3 años para evitar el atragantamiento · Ofrece la almendra molida, nunca entera antes de los 5 años, es un alérgeno · Sirve las trufas ocasionalmente por los azúcares concentrados de las pasas'),
  ('untable-de-girasol-y-coco', 'Guarda el untable en un frasco limpio y seco hasta 3 semanas a temperatura ambiente y lejos del sol · Si el aceite sube a la superficie, revuelve el untable con una cuchara · Sigue usando el untable, no está echado a perder'),
  ('vasito-citrico-de-naranja-y-jengibre', 'Si el jengibre resulta fuerte, empieza con la mitad de la cantidad · Aumenta el jengibre poco a poco · Sirve el vasito bien frío y recién colado'),
  ('waffles-blw', 'Ofrece el huevo solo la primera vez y observa 2-3 días, es un alérgeno · Congela los waffles con papel de horno entre capas hasta 2 meses · Calienta los waffles en la tostadora · Si no tienes wafflera, usa la sartén y cocina panqueques'),
  ('waffles-de-pollo', 'Corta los waffles en bastones · Empaca los waffles con una salsa de yogur natural y limón para mojar · Manda la lonchera con gel refrigerante y sirve los waffles antes de 4 horas'),
  ('wrap-integral-de-pollo-y-aguacate', 'Envuelve el wrap en papel encerado · Corta el wrap a la mitad para que entre fácil en la lonchera y no se desarme'),
  ('yogur-con-compota-de-manzana', 'Prepara el doble de compota · Guarda la compota en un frasco de vidrio en el refrigerador hasta 5 días · Suma la compota a yogur, panqueques o avena · Manda el vasito bien frío con gel refrigerante, el yogur no aguanta horas fuera del frío'),
  ('yogur-con-fresas-y-arandanos', 'Deja macerar la fruta picada 10 minutos antes de mezclar, así suelta su jugo y endulza el yogur de forma natural · Manda el vasito bien frío con un gel refrigerante · Usa yogur griego natural para más cremosidad y proteínas'),
  ('yogur-griego-casero', 'Reserva 200 ml de este yogur como cultivo para la siguiente preparación · Aprovecha el suero colado en batidos o panqueques · Empaca el yogur en un recipiente hermético con gel refrigerante')
) AS v(slug, tip) WHERE r.slug = v.slug;
