INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Para la salsa, sofríe el resto de la cebolla y el otro diente de ajo en el aceite restante hasta que estén tiernos.', false FROM public.recipes r WHERE r.slug='albondigas-con-salsa-de-calabaza' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Agrega la calabaza en trozos y cocina 10 minutos.', false FROM public.recipes r WHERE r.slug='albondigas-con-salsa-de-calabaza' ON CONFLICT (recipe_id, step_number) DO NOTHING;
