INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'En un tazón, mezcla el pavo molido con la zanahoria rallada, el ajo, la cebolla, el huevo, el pan molido, el perejil, el orégano y la pizca de sal (omítela si comerán menores de 1 año).', false FROM public.recipes r WHERE r.slug='albondigas-de-pavo-y-zanahoria' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Forma albóndigas pequeñas, del tamaño de una nuez: así se cocinan parejas por dentro.', false FROM public.recipes r WHERE r.slug='albondigas-de-pavo-y-zanahoria' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'En una sartén con una cucharada de aceite de oliva, dora las albóndigas 5 minutos y resérvalas.', false FROM public.recipes r WHERE r.slug='albondigas-de-pavo-y-zanahoria' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Para la salsa, sofríe la cebolla y el ajo restantes en la otra cucharada de aceite de oliva hasta que estén tiernos.', false FROM public.recipes r WHERE r.slug='albondigas-de-pavo-y-zanahoria' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Añade el tomate triturado y cocina 10 minutos a fuego medio.', false FROM public.recipes r WHERE r.slug='albondigas-de-pavo-y-zanahoria' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Vierte el caldo de verduras y deja cocinar a fuego lento.', false FROM public.recipes r WHERE r.slug='albondigas-de-pavo-y-zanahoria' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Incorpora las albóndigas a la salsa y cocínalas 10-15 minutos más, hasta que estén completamente cocidas por dentro: parte la más grande por la mitad y comprueba que no quede rosada.', true FROM public.recipes r WHERE r.slug='albondigas-de-pavo-y-zanahoria' ON CONFLICT (recipe_id, step_number) DO NOTHING;
