INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Mezcla en un bol la mostaza, la miel, el ajo en polvo, la paprika, la pizca de sal y la pimienta.', false FROM public.recipes r WHERE r.slug='alitas-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Cubre las alitas con la mezcla y déjalas marinar al menos 30 minutos, siempre dentro del refrigerador.', false FROM public.recipes r WHERE r.slug='alitas-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Al horno: precalienta a 200 °C y hornéalas 35-40 minutos sobre una bandeja, volteándolas a la mitad del tiempo, hasta que estén doradas.', false FROM public.recipes r WHERE r.slug='alitas-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'En sartén: cocínalas tapadas a fuego medio 20-25 minutos, volteándolas con frecuencia para que se cocinen parejo.', false FROM public.recipes r WHERE r.slug='alitas-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Verifica la cocción completa: pincha junto al hueso y comprueba que los jugos salgan claros, sin ninguna parte rosada.', true FROM public.recipes r WHERE r.slug='alitas-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Para menores de 5 años, retira la piel, el hueso y los cartílagos, y desmenuza la carne antes de servir.', true FROM public.recipes r WHERE r.slug='alitas-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Evita las alitas con hueso en menores de 5 años: usa filetitos de pechuga sin hueso con la misma marinada (hornea 15-20 minutos) y córtalos en tiras; si sirves alitas, retira piel, hueso y cartílagos y desmenuza la carne.' FROM public.recipes r WHERE r.slug='alitas-de-pollo' ON CONFLICT (recipe_id, age_band) DO NOTHING;
