INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Pela y ralla las manzanas; exprime muy bien el exceso de jugo con las manos o con un paño limpio para que las barritas compacten.', false FROM public.recipes r WHERE r.slug='barritas-de-manzana-y-amaranto' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Mezcla la manzana rallada con la miel o la pasta de dátiles hasta integrar.', false FROM public.recipes r WHERE r.slug='barritas-de-manzana-y-amaranto' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Incorpora el amaranto expandido (y el ajonjolí o el coco, si los usas) y mezcla hasta obtener una masa que se compacte al presionarla.', false FROM public.recipes r WHERE r.slug='barritas-de-manzana-y-amaranto' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Con las manos ligeramente húmedas, forma barritas y acomódalas en la bandeja.', false FROM public.recipes r WHERE r.slug='barritas-de-manzana-y-amaranto' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Hornea a 170-180 °C durante 25-30 minutos, hasta que se doren y se sientan firmes al tacto.', false FROM public.recipes r WHERE r.slug='barritas-de-manzana-y-amaranto' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Déjalas enfriar por completo antes de despegarlas: al enfriarse terminan de compactar.', false FROM public.recipes r WHERE r.slug='barritas-de-manzana-y-amaranto' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Corta cada barrita en trozos del tamaño de un bocado y sírvelos sentado: son densas y masticables. Omite el ajonjolí y el coco deshidratado si el niño todavía se atraganta con texturas pequeñas y sueltas.' FROM public.recipes r WHERE r.slug='barritas-de-manzana-y-amaranto' ON CONFLICT (recipe_id, age_band) DO NOTHING;
