INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 75, 'g', NULL, 6 FROM public.recipes r, public.ingredients i WHERE r.slug='barritas-energeticas' AND i.code='arandano_deshidratado' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 60, 'g', NULL, 7 FROM public.recipes r, public.ingredients i WHERE r.slug='barritas-energeticas' AND i.code='chips_chocolate' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Derrite a fuego bajo la mantequilla con la miel y el azúcar morena, revolviendo hasta integrar por completo: esta mezcla caliente es la que liga las barritas.', false FROM public.recipes r WHERE r.slug='barritas-energeticas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Retira del fuego, agrega la avena y la sal y mezcla hasta cubrir todos los copos.', false FROM public.recipes r WHERE r.slug='barritas-energeticas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Deja entibiar 5 minutos e incorpora los arándanos y las chispas de chocolate, para que no se derritan del todo.', false FROM public.recipes r WHERE r.slug='barritas-energeticas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Vuelca la mezcla en un molde cubierto con papel encerado y presiónala muy firme con el dorso de una cuchara: de esto depende que no se desarmen.', false FROM public.recipes r WHERE r.slug='barritas-energeticas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Refrigera 1-2 horas hasta que endurezcan, desmolda y corta las barritas.', false FROM public.recipes r WHERE r.slug='barritas-energeticas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Pica un poco los arándanos deshidratados antes de incorporarlos y corta las barritas en cubos pequeños para los más chicos.' FROM public.recipes r WHERE r.slug='barritas-energeticas' ON CONFLICT (recipe_id, age_band) DO NOTHING;
