INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 0.5, 'unidad', 'en bastones del tamaño de un dedo', 1 FROM public.recipes r, public.ingredients i WHERE r.slug='bastoncitos-de-calabacin-al-horno' AND i.code='calabacin' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 2, 'cucharada', 'contiene gluten; usa avena certificada sin gluten si hay celiaquía', 2 FROM public.recipes r, public.ingredients i WHERE r.slug='bastoncitos-de-calabacin-al-horno' AND i.code='harina_avena' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'cucharadita', NULL, 3 FROM public.recipes r, public.ingredients i WHERE r.slug='bastoncitos-de-calabacin-al-horno' AND i.code='aceite_oliva' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Precalienta el horno a 180 °C y cubre una bandeja con papel para hornear.', false FROM public.recipes r WHERE r.slug='bastoncitos-de-calabacin-al-horno' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Lava el calabacín y córtalo en bastones del tamaño de un dedo.', false FROM public.recipes r WHERE r.slug='bastoncitos-de-calabacin-al-horno' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Reboza los bastoncitos en la harina de avena hasta cubrirlos por todos lados.', false FROM public.recipes r WHERE r.slug='bastoncitos-de-calabacin-al-horno' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Colócalos separados en la bandeja y rocíalos con el aceite de oliva.', false FROM public.recipes r WHERE r.slug='bastoncitos-de-calabacin-al-horno' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Hornea 15-20 minutos. Para menores de 12 meses retíralos antes, cuando estén blandos y aún no crujientes.', true FROM public.recipes r WHERE r.slug='bastoncitos-de-calabacin-al-horno' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Deja enfriar hasta que estén tibios antes de servir.', false FROM public.recipes r WHERE r.slug='bastoncitos-de-calabacin-al-horno' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Corta bastones gruesos, del largo de un dedo adulto, y hornéalos solo hasta que estén blandos (no crujientes) para que pueda sostenerlos y aplastarlos con las encías. También puedes machacar el calabacín cocido con un tenedor.' FROM public.recipes r WHERE r.slug='bastoncitos-de-calabacin-al-horno' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Córtalos en trozos pequeños tamaño garbanzo, siempre blandos, para que practique la pinza.' FROM public.recipes r WHERE r.slug='bastoncitos-de-calabacin-al-horno' ON CONFLICT (recipe_id, age_band) DO NOTHING;
