INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 200, 'g', 'pide que la muelan dos veces para que quede más fina', 1 FROM public.recipes r, public.ingredients i WHERE r.slug='bastones-suaves-de-res-y-camote' AND i.code='carne_molida_res' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 250, 'g', 'pelado y en cubos', 2 FROM public.recipes r, public.ingredients i WHERE r.slug='bastones-suaves-de-res-y-camote' AND i.code='camote' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 40, 'g', '½ taza, pasadas por licuadora hasta textura de harina', 3 FROM public.recipes r, public.ingredients i WHERE r.slug='bastones-suaves-de-res-y-camote' AND i.code='hojuelas_avena' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 2, 'cucharada', 'rallada muy fina', 4 FROM public.recipes r, public.ingredients i WHERE r.slug='bastones-suaves-de-res-y-camote' AND i.code='cebolla' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'cucharada', NULL, 5 FROM public.recipes r, public.ingredients i WHERE r.slug='bastones-suaves-de-res-y-camote' AND i.code='aceite_oliva' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Cocina el camote al vapor de 15 a 18 minutos, hasta que se deshaga al pincharlo, escúrrelo muy bien y machácalo hasta obtener un puré sin grumos.', false FROM public.recipes r WHERE r.slug='bastones-suaves-de-res-y-camote' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Calienta el aceite en una sartén y sofríe la cebolla rallada 3 minutos a fuego bajo, sin que se dore.', false FROM public.recipes r WHERE r.slug='bastones-suaves-de-res-y-camote' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Agrega la carne molida y cocínala de 8 a 10 minutos deshaciéndola con una cuchara de madera, hasta que no quede ni una sola parte rosada: la carne molida debe cocinarse por completo, nunca jugosa por dentro.', true FROM public.recipes r WHERE r.slug='bastones-suaves-de-res-y-camote' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Retira del fuego, deja entibiar 5 minutos y mezcla la carne con el puré de camote y la avena molida hasta formar una masa que se pueda moldear.', false FROM public.recipes r WHERE r.slug='bastones-suaves-de-res-y-camote' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Precalienta el horno a 190 °C y forra una bandeja con papel para hornear.', false FROM public.recipes r WHERE r.slug='bastones-suaves-de-res-y-camote' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Con las manos húmedas forma 12 bastones del largo y grosor de tu dedo índice, unos 8 cm por 1,5 cm. Ese tamaño permite que el bebé lo sostenga con el puño cerrado y muerda la punta que sobresale.', true FROM public.recipes r WHERE r.slug='bastones-suaves-de-res-y-camote' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Hornea 18 minutos, girándolos a la mitad del tiempo, hasta que estén firmes por fuera y bien calientes en el centro.', false FROM public.recipes r WHERE r.slug='bastones-suaves-de-res-y-camote' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Antes de servir, comprueba que cada bastón se aplasta sin esfuerzo entre tu pulgar y tu índice. Si opone resistencia, no es seguro: desármalo y ofrécelo machacado con un poco de caldo o agua.', true FROM public.recipes r WHERE r.slug='bastones-suaves-de-res-y-camote' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 9, 'Deja entibiar hasta temperatura de mano y ofrece un bastón a la vez, con el bebé sentado erguido y siempre acompañado mientras come.', true FROM public.recipes r WHERE r.slug='bastones-suaves-de-res-y-camote' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Puedes darles forma de albondiguita y sazonarlas con una pizca de sal y orégano. Sírvelas partidas por la mitad a lo largo, acompañadas de puré de papa o arroz.' FROM public.recipes r WHERE r.slug='bastones-suaves-de-res-y-camote' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Sírvelas enteras como plato principal con verduras al vapor; a esta edad ya puede usar tenedor y mojarlas en salsa de tomate casera.' FROM public.recipes r WHERE r.slug='bastones-suaves-de-res-y-camote' ON CONFLICT (recipe_id, age_band) DO NOTHING;
