INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Cuece el brócoli al vapor o en agua 5-7 minutos hasta que esté tierno y pícalo finamente.', false FROM public.recipes r WHERE r.slug='bolitas-de-brocoli-pollo-y-papa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'En un tazón grande mezcla el puré de papa, el brócoli picado y el pollo desmenuzado.', false FROM public.recipes r WHERE r.slug='bolitas-de-brocoli-pollo-y-papa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
