INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Déjalas entibiar unos minutos antes de servir.', false FROM public.recipes r WHERE r.slug='bolitas-de-brocoli-pollo-y-papa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
