INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Ensarta en los palillos alternando mini panqueques y frutas.', false FROM public.recipes r WHERE r.slug='brochetas-de-mini-panqueques' ON CONFLICT (recipe_id, step_number) DO NOTHING;
