INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Precalienta el horno a 180 °C y engrasa un molde pequeño con la mantequilla.', false FROM public.recipes r WHERE r.slug='budin-de-pan-y-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Corta el pan en cubos, colócalo en un bol y cúbrelo con la leche; déjalo remojar 10 minutos, hasta que esté completamente blando.', false FROM public.recipes r WHERE r.slug='budin-de-pan-y-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
