INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Bate los huevos e incorpóralos al pan remojado junto con el puré de plátano, la canela y la vainilla; mezcla aplastando hasta lograr una masa húmeda y homogénea.', false FROM public.recipes r WHERE r.slug='budin-de-pan-y-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Vierte la mezcla en el molde y hornea de 35 a 40 minutos, hasta que la superficie esté dorada y el centro firme: al insertar un palillo en el medio debe salir limpio, sin mezcla húmeda. El huevo tiene que quedar completamente cocido.', true FROM public.recipes r WHERE r.slug='budin-de-pan-y-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Deja enfriar 15 minutos, desmolda y corta en cubos del tamaño de un bocado para los más pequeños.', true FROM public.recipes r WHERE r.slug='budin-de-pan-y-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Si va a la lonchera, guárdalo en un recipiente hermético con un gel refrigerante: lleva huevo y leche y necesita cadena de frío.', true FROM public.recipes r WHERE r.slug='budin-de-pan-y-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
