INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Lava bien las frutas y verduras. Puedes usar otras de tu preferencia siguiendo el mismo método.', false FROM public.recipes r WHERE r.slug='chips-de-verduras-y-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Córtalas en rodajas muy finas y uniformes (2 a 3 mm) con mandolina, pelador o cuchillo afilado: este paso es solo para el adulto.', false FROM public.recipes r WHERE r.slug='chips-de-verduras-y-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Espolvorea una pizca de sal sobre las verduras y deja reposar 20 minutos para que suelten el exceso de agua; luego sécalas con papel absorbente.', false FROM public.recipes r WHERE r.slug='chips-de-verduras-y-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Acomoda las rodajas en bandejas con papel encerado, en una sola capa y sin encimarlas.', false FROM public.recipes r WHERE r.slug='chips-de-verduras-y-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Deshidrata en el horno a 90-110 °C durante 1.5 a 3 horas, con la puerta apenas entreabierta, volteando las rodajas a la mitad del tiempo. A temperaturas más altas se hornean en vez de deshidratarse, así que no subas el fuego para acelerar.', false FROM public.recipes r WHERE r.slug='chips-de-verduras-y-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Deja enfriar por completo (terminan de ponerse crujientes al enfriar) y guarda en un frasco hermético.', false FROM public.recipes r WHERE r.slug='chips-de-verduras-y-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
