INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Procesa las lentejas cocidas con la avena molida hasta obtener una mezcla densa.', false FROM public.recipes r WHERE r.slug='chorizo-de-vegetales' ON CONFLICT (recipe_id, step_number) DO NOTHING;
