INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Elige duraznos bien maduros, que cedan al presionarlos suavemente: de ellos sale todo el dulzor de este postre.', false FROM public.recipes r WHERE r.slug='cremita-de-durazno-y-requeson' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Pélalos, ábrelos por la mitad y retira el carozo completo, revisando que no quede ningún trocito duro dentro de la pulpa.', true FROM public.recipes r WHERE r.slug='cremita-de-durazno-y-requeson' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Corta la pulpa en trozos y tritúrala junto con el requesón hasta obtener una crema homogénea.', false FROM public.recipes r WHERE r.slug='cremita-de-durazno-y-requeson' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Prueba la textura con una cuchara: para los más pequeños no debe quedar ni un grumo. Sirve fría con una pizca de canela.', false FROM public.recipes r WHERE r.slug='cremita-de-durazno-y-requeson' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Licúa hasta que quede completamente lisa y usa solo una cucharada de requesón. Si el durazno no está bien maduro, cocínalo al vapor 3 minutos antes de triturarlo.' FROM public.recipes r WHERE r.slug='cremita-de-durazno-y-requeson' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Machaca con tenedor en lugar de licuar y deja trocitos muy blandos para que practique la masticación.' FROM public.recipes r WHERE r.slug='cremita-de-durazno-y-requeson' ON CONFLICT (recipe_id, age_band) DO NOTHING;
