INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Si no tienes sobras, cuece el brócoli hasta que esté muy blando y cocina los muslos de pollo (guisados u horneados) hasta que estén completamente cocidos; retira huesos y piel.', true FROM public.recipes r WHERE r.slug='croquetas-de-pollo-y-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Calienta el aceite en una cazuela y saltea el brócoli unos minutos, deshaciéndolo un poco.', false FROM public.recipes r WHERE r.slug='croquetas-de-pollo-y-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Pica el pollo en trocitos muy pequeños e incorpóralo a la cazuela; remueve.', false FROM public.recipes r WHERE r.slug='croquetas-de-pollo-y-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Disuelve la harina de garbanzo en el agua hasta que quede como huevo batido y viértela sobre el brócoli y el pollo; remueve hasta formar una masa.', false FROM public.recipes r WHERE r.slug='croquetas-de-pollo-y-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Pasa la masa a un recipiente y deja enfriar; puedes refrigerarla o congelarla.', false FROM public.recipes r WHERE r.slug='croquetas-de-pollo-y-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Con una cuchara, toma porciones y dales forma de croqueta; pásalas por pan rallado sin sal.', false FROM public.recipes r WHERE r.slug='croquetas-de-pollo-y-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Colócalas sobre papel de horno en una bandeja y hornea a 180-200 °C unos 10 minutos, hasta que el rebozado empiece a dorarse.', false FROM public.recipes r WHERE r.slug='croquetas-de-pollo-y-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
