INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 3, 'cucharada', 'para ablandar la avena', 5 FROM public.recipes r, public.ingredients i WHERE r.slug='cuadritos-blandos-de-huevo-avena-y-calabacita' AND i.code='agua' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Precalienta el horno a 180 °C y forra un molde cuadrado pequeño, de unos 15 x 15 cm, con papel para hornear.', false FROM public.recipes r WHERE r.slug='cuadritos-blandos-de-huevo-avena-y-calabacita' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Ralla la calabacita, colócala en un colador y exprímela con las manos hasta sacarle todo el líquido posible: si queda mojada, la mezcla no cuaja.', false FROM public.recipes r WHERE r.slug='cuadritos-blandos-de-huevo-avena-y-calabacita' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Mezcla las hojuelas de avena con el agua y déjalas hidratar 5 minutos.', false FROM public.recipes r WHERE r.slug='cuadritos-blandos-de-huevo-avena-y-calabacita' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Bate los huevos enteros con un tenedor hasta que la yema y la clara queden completamente integradas.', false FROM public.recipes r WHERE r.slug='cuadritos-blandos-de-huevo-avena-y-calabacita' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Une los huevos batidos con la avena hidratada, la calabacita exprimida y el aceite de oliva, y revuelve bien. No agregues sal: los menores de 12 meses no deben consumir sal añadida.', false FROM public.recipes r WHERE r.slug='cuadritos-blandos-de-huevo-avena-y-calabacita' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Vierte la mezcla en el molde formando una capa de 2 cm de alto y alísala con una cuchara.', false FROM public.recipes r WHERE r.slug='cuadritos-blandos-de-huevo-avena-y-calabacita' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Hornea de 22 a 25 minutos, hasta que el centro esté firme al tacto y no quede nada de huevo líquido al insertar un cuchillo. El huevo debe quedar siempre bien cocido, sin partes babosas.', true FROM public.recipes r WHERE r.slug='cuadritos-blandos-de-huevo-avena-y-calabacita' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Deja entibiar, desmolda y corta en tiras del ancho de tu dedo, de unos 2 cm por 7 cm, nunca en cubos pequeños y redondeados que puedan atragantar.', true FROM public.recipes r WHERE r.slug='cuadritos-blandos-de-huevo-avena-y-calabacita' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 9, 'Comprueba que la tira se aplasta con facilidad entre tus dedos y ofrécele una a la vez, con el bebé sentado erguido y bajo tu supervisión durante toda la comida.', true FROM public.recipes r WHERE r.slug='cuadritos-blandos-de-huevo-avena-y-calabacita' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Agrega 2 cucharadas de queso rallado a la mezcla y una pizca de sal, y corta los cuadritos un poco más grandes para que practique el mordisco.' FROM public.recipes r WHERE r.slug='cuadritos-blandos-de-huevo-avena-y-calabacita' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Sírvelos como tortilla en porciones triangulares, acompañados de bastones de pan integral y ensalada de tomate picado fino.' FROM public.recipes r WHERE r.slug='cuadritos-blandos-de-huevo-avena-y-calabacita' ON CONFLICT (recipe_id, age_band) DO NOTHING;
