INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Pica el pimiento, la calabacita, la cebolla y la zanahoria en trozos pequeños.', false FROM public.recipes r WHERE r.slug='cuscus-con-pollo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'En una sartén con el aceite de oliva, sofríe la cebolla y el ajo picados hasta que estén dorados.', false FROM public.recipes r WHERE r.slug='cuscus-con-pollo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Agrega el pollo en trozos y cocínalo hasta que esté dorado y completamente cocido por dentro, sin partes rosadas.', true FROM public.recipes r WHERE r.slug='cuscus-con-pollo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Incorpora el pimiento, la zanahoria y la calabacita y cocina 5 minutos.', false FROM public.recipes r WHERE r.slug='cuscus-con-pollo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Agrega la cúrcuma y el comino y revuelve bien para integrar los sabores.', false FROM public.recipes r WHERE r.slug='cuscus-con-pollo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Vierte el caldo de verduras caliente y lleva a ebullición.', false FROM public.recipes r WHERE r.slug='cuscus-con-pollo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Retira del fuego, agrega el cuscús y tapa la sartén para que absorba el líquido.', false FROM public.recipes r WHERE r.slug='cuscus-con-pollo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Deja reposar 5 minutos y suelta los granos con un tenedor.', false FROM public.recipes r WHERE r.slug='cuscus-con-pollo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 9, 'Prueba y ajusta con muy poca sal y pimienta antes de servir.', false FROM public.recipes r WHERE r.slug='cuscus-con-pollo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
