INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Corta los filetes de pescado en tiras del tamaño de un dedo.', false FROM public.recipes r WHERE r.slug='deditos-de-pescado-empanizados' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Pasa los dedos por cada tira y retira cualquier espina que encuentres.', true FROM public.recipes r WHERE r.slug='deditos-de-pescado-empanizados' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Condimenta las tiras con el jugo de limón, la pizca de sal, la pimienta y el ajo en polvo.', false FROM public.recipes r WHERE r.slug='deditos-de-pescado-empanizados' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Bate el huevo con la mostaza en un tazón.', false FROM public.recipes r WHERE r.slug='deditos-de-pescado-empanizados' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Pasa cada tira por el huevo batido y luego por el pan rallado hasta cubrirla bien.', false FROM public.recipes r WHERE r.slug='deditos-de-pescado-empanizados' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Al horno: precalienta a 200 °C y hornea 15-20 minutos hasta que estén dorados. En sartén: cocina con el aceite a fuego medio, 3-4 minutos por lado.', false FROM public.recipes r WHERE r.slug='deditos-de-pescado-empanizados' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Verifica que el pescado esté completamente cocido: debe verse blanco opaco y deshacerse en lascas.', true FROM public.recipes r WHERE r.slug='deditos-de-pescado-empanizados' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Prepara sin sal, cocina el pescado hasta que esté completamente opaco y sírvelo desmenuzado en lascas, revisando de nuevo que no haya espinas.' FROM public.recipes r WHERE r.slug='deditos-de-pescado-empanizados' ON CONFLICT (recipe_id, age_band) DO NOTHING;
