INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 40, 'g', '½ taza, pasadas por licuadora hasta textura de harina', 3 FROM public.recipes r, public.ingredients i WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' AND i.code='hojuelas_avena' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'cucharada', NULL, 4 FROM public.recipes r, public.ingredients i WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' AND i.code='aceite_oliva' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 300, 'ml', 'para cocer las lentejas, sin sal', 5 FROM public.recipes r, public.ingredients i WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' AND i.code='agua' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Enjuaga las lentejas rojas bajo el chorro de agua y cocínalas en los 300 ml de agua sin sal durante 15 minutos, hasta que se deshagan por completo y no quede líquido suelto.', false FROM public.recipes r WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Cocina la calabaza al vapor de 12 a 15 minutos, hasta que la puedas aplastar sin fuerza con un tenedor, y escúrrela muy bien.', false FROM public.recipes r WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Machaca la calabaza con las lentejas hasta obtener una pasta espesa y homogénea, sin trozos firmes que el bebé no pueda deshacer con las encías.', true FROM public.recipes r WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Agrega la avena molida y el aceite de oliva, mezcla bien y deja reposar 10 minutos para que la avena absorba la humedad y la masa se pueda moldear.', false FROM public.recipes r WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Precalienta el horno a 200 °C y forra una bandeja con papel para hornear.', false FROM public.recipes r WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Con las manos húmedas forma 10 bastones del largo y grosor de tu dedo índice, aproximadamente 8 cm por 1,5 cm: ese tamaño es el que el bebé puede sostener con el puño dejando un pedacito afuera para morder.', true FROM public.recipes r WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Hornea 20 minutos, gíralos con cuidado y hornea 5 minutos más, hasta que estén firmes por fuera pero blandos por dentro.', false FROM public.recipes r WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Antes de servir, aplasta un bastón entre tu pulgar y tu índice: debe ceder sin resistencia. Si no se aplasta con facilidad, devuélvelo unos minutos al vapor o desármalo y ofrécelo machacado.', true FROM public.recipes r WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 9, 'Sirve un solo dedo a la vez, con el bebé sentado y erguido en su silla, nunca acostado ni en el asiento del auto, y acompáñalo durante toda la comida.', true FROM public.recipes r WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Ya puedes darles forma de croqueta o de tortita y sazonar la mezcla con comino y una pizca de sal. Sírvelos con salsa de tomate casera para mojar.' FROM public.recipes r WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Hornéalos 5 minutos más para que queden más doraditos por fuera y acompáñalos con arroz y ensalada picada fina como plato principal.' FROM public.recipes r WHERE r.slug='dedos-blandos-de-lenteja-y-calabaza' ON CONFLICT (recipe_id, age_band) DO NOTHING;
