INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Disuelve la levadura en la leche tibia con una cucharadita del azúcar y deja reposar 10 minutos, hasta que forme espuma (si no espuma, la levadura ya no sirve).', false FROM public.recipes r WHERE r.slug='donas-caseras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Bate los huevos con el resto del azúcar hasta obtener una mezcla cremosa.', false FROM public.recipes r WHERE r.slug='donas-caseras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Agrega el aceite y las ralladuras de naranja y limón.', false FROM public.recipes r WHERE r.slug='donas-caseras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Incorpora la harina y la levadura disuelta y amasa 8-10 minutos, hasta lograr una masa elástica.', false FROM public.recipes r WHERE r.slug='donas-caseras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Tapa la masa con un paño y déjala leudar 1 hora en un lugar tibio, hasta que doble su volumen.', false FROM public.recipes r WHERE r.slug='donas-caseras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Forma las rosquillas, colócalas en una bandeja engrasada y déjalas leudar 30 minutos más.', false FROM public.recipes r WHERE r.slug='donas-caseras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Hornea a 180 °C por 15-18 minutos, hasta que estén doradas y bien cocidas por dentro: al pinchar el centro con un palillo debe salir seco, señal de que el huevo quedó completamente cocido. Antes de servir puedes espolvorear un poco de canela.', true FROM public.recipes r WHERE r.slug='donas-caseras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
