INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 2, 'unidad', 'opcionales, para aromatizar', 5 FROM public.recipes r, public.ingredients i WHERE r.slug='dulce-de-guayaba' AND i.code='clavo_olor' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Lava las guayabas y pártelas por la mitad.', false FROM public.recipes r WHERE r.slug='dulce-de-guayaba' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Cocínalas 10 minutos a fuego medio-alto en una olla con agua que apenas las cubra, junto con la canela y los clavos si los usas.', false FROM public.recipes r WHERE r.slug='dulce-de-guayaba' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Escurre, retira la canela y los clavos, licúa la fruta y cuela la mezcla para eliminar todas las semillas.', false FROM public.recipes r WHERE r.slug='dulce-de-guayaba' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Regresa la pulpa a la olla con el azúcar y cocina a fuego medio-bajo removiendo constantemente; este paso es solo para adultos porque la mezcla salpica al espesar.', false FROM public.recipes r WHERE r.slug='dulce-de-guayaba' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Agrega el jugo de limón y sigue removiendo hasta que la pasta se espese y se despegue del fondo de la olla.', false FROM public.recipes r WHERE r.slug='dulce-de-guayaba' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Vierte en un molde rectangular engrasado, deja enfriar y refrigera al menos 24 horas antes de desmoldar y cortar en cuadritos.', false FROM public.recipes r WHERE r.slug='dulce-de-guayaba' ON CONFLICT (recipe_id, step_number) DO NOTHING;
