INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 0.25, 'cucharadita', 'opcional, solo la parte naranja de la cáscara', 4 FROM public.recipes r, public.ingredients i WHERE r.slug='dulcecito-de-camote-y-canela' AND i.code='ralladura_naranja' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Lava, pela y corta el camote en cubos parejos para que se cocinen todos al mismo tiempo.', false FROM public.recipes r WHERE r.slug='dulcecito-de-camote-y-canela' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Cocínalo al vapor durante 15 minutos, o hiérvelo en poca agua, hasta que un tenedor entre sin ningún esfuerzo.', false FROM public.recipes r WHERE r.slug='dulcecito-de-camote-y-canela' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Machácalo aún caliente con el tenedor o el prensapapas hasta que quede cremoso y sin hilos.', false FROM public.recipes r WHERE r.slug='dulcecito-de-camote-y-canela' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Deja entibiar el puré y recién entonces agrega la leche materna o la fórmula, poco a poco, hasta lograr la textura que tu bebé necesita. La leche materna nunca se hierve ni se calienta al fuego: se suma tibia y fuera de la olla.', true FROM public.recipes r WHERE r.slug='dulcecito-de-camote-y-canela' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Perfuma con la canela y la ralladura de naranja, mezcla bien y sirve tibio.', false FROM public.recipes r WHERE r.slug='dulcecito-de-camote-y-canela' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Pasa el puré por un colador fino o licúalo con un poco más de leche materna o fórmula hasta que quede completamente liso, sin grumos ni hilos.' FROM public.recipes r WHERE r.slug='dulcecito-de-camote-y-canela' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Déjalo con textura de puré machacado y sirve al lado dos o tres bastones de camote cocido para que practique llevárselos solo a la boca.' FROM public.recipes r WHERE r.slug='dulcecito-de-camote-y-canela' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Prepáralo con leche entera en lugar de fórmula y sírvelo con una cucharada de yogur natural encima.' FROM public.recipes r WHERE r.slug='dulcecito-de-camote-y-canela' ON CONFLICT (recipe_id, age_band) DO NOTHING;
