INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'cucharadita', 'para engrasar la bandeja', 8 FROM public.recipes r, public.ingredients i WHERE r.slug='empanadas-de-atun' AND i.code='aceite_vegetal' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Mezcla en un bol la harina con la sal y la mantequilla fría hasta obtener una textura arenosa.', false FROM public.recipes r WHERE r.slug='empanadas-de-atun' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Agrega el jugo de limón y el agua fría y amasa hasta que la masa quede elástica. Forma una bola, cúbrela con un paño húmedo y déjala reposar 15 minutos.', false FROM public.recipes r WHERE r.slug='empanadas-de-atun' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Mientras reposa la masa, cocina las papas en cubos en agua hirviendo por 12-15 minutos, hasta que estén tiernas. Escúrrelas y machácalas ligeramente con un tenedor.', false FROM public.recipes r WHERE r.slug='empanadas-de-atun' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Mezcla el atún bien escurrido con la papa machacada hasta integrar el relleno.', false FROM public.recipes r WHERE r.slug='empanadas-de-atun' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Extiende la masa con un rodillo y corta círculos medianos con un vaso o cortador.', false FROM public.recipes r WHERE r.slug='empanadas-de-atun' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Coloca una cucharada de relleno en cada círculo, dobla y sella los bordes presionando con un tenedor.', false FROM public.recipes r WHERE r.slug='empanadas-de-atun' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Acomoda las empanadas en la bandeja engrasada y hornéalas a 200 °C por 20-25 minutos, hasta que estén doradas y crujientes. También funcionan en freidora de aire a 190 °C por 12-15 minutos.', false FROM public.recipes r WHERE r.slug='empanadas-de-atun' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Sirve la empanada tibia y partida en trocitos pequeños; machaca bien el relleno y usa la mínima sal en la masa.' FROM public.recipes r WHERE r.slug='empanadas-de-atun' ON CONFLICT (recipe_id, age_band) DO NOTHING;
