INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Agrega la pizca de sal solo sobre la tortilla destinada a los mayores de 1 año.', false FROM public.recipes r WHERE r.slug='enrollado-de-garbanzos-y-zanahoria' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Enrolla cada tortilla bien apretada, empezando por el lado con relleno y terminando en el borde libre.', false FROM public.recipes r WHERE r.slug='enrollado-de-garbanzos-y-zanahoria' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Corta cada rollo en ruedas de dos dedos de ancho con un cuchillo de sierra, apoyando el rollo con la costura hacia abajo.', false FROM public.recipes r WHERE r.slug='enrollado-de-garbanzos-y-zanahoria' ON CONFLICT (recipe_id, step_number) DO NOTHING;
