INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 500, 'ml', 'o bebida vegetal sin azúcar', 2 FROM public.recipes r, public.ingredients i WHERE r.slug='flan-suave-de-platano' AND i.code='leche' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 3, 'unidad', NULL, 3 FROM public.recipes r, public.ingredients i WHERE r.slug='flan-suave-de-platano' AND i.code='huevo' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 2, 'cucharada', 'o jarabe (miel) de agave; suma 2 cucharadas más si preparas el caramelo opcional del molde', 4 FROM public.recipes r, public.ingredients i WHERE r.slug='flan-suave-de-platano' AND i.code='miel' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'cucharadita', NULL, 5 FROM public.recipes r, public.ingredients i WHERE r.slug='flan-suave-de-platano' AND i.code='esencia_vainilla' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'pizca', NULL, 6 FROM public.recipes r, public.ingredients i WHERE r.slug='flan-suave-de-platano' AND i.code='canela_polvo' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Precalienta el horno a 180 °C. Ten listo un molde para flan y una bandeja honda donde quepa, para el baño maría.', false FROM public.recipes r WHERE r.slug='flan-suave-de-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Caramelo opcional: en una olla pequeña calienta a fuego bajo 2 cucharadas de miel (aparte de las de la mezcla) con 1 cucharadita de agua, de 1 a 2 minutos, solo hasta que burbujee suave y tome color dorado. No la dejes hervir fuerte, porque la miel se quema muy rápido. Viértela de inmediato en el fondo del molde y ladéalo para cubrirlo.', false FROM public.recipes r WHERE r.slug='flan-suave-de-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Pela los plátanos y tritúralos con un tenedor o en la licuadora hasta obtener un puré sin grumos.', false FROM public.recipes r WHERE r.slug='flan-suave-de-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'En un bol grande, bate los huevos con las 2 cucharadas de miel de la mezcla.', false FROM public.recipes r WHERE r.slug='flan-suave-de-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Agrega la leche, la esencia de vainilla y la canela, y mezcla bien.', false FROM public.recipes r WHERE r.slug='flan-suave-de-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Incorpora el puré de plátano y bate hasta que la mezcla quede homogénea.', false FROM public.recipes r WHERE r.slug='flan-suave-de-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Vierte la mezcla en el molde. Coloca el molde dentro de la bandeja y llena la bandeja con agua caliente hasta la mitad de la altura del molde.', false FROM public.recipes r WHERE r.slug='flan-suave-de-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Hornea de 35 a 40 minutos, hasta que los bordes estén firmes y el centro tiemble apenas, como gelatina. La prueba del palillo no sirve para el flan, porque termina de cuajar al enfriarse; lo que no puede quedar es mezcla líquida: el huevo tiene que estar completamente cocido.', true FROM public.recipes r WHERE r.slug='flan-suave-de-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 9, 'Deja enfriar a temperatura ambiente y refrigera por lo menos 2 horas antes de servir.', false FROM public.recipes r WHERE r.slug='flan-suave-de-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 10, 'Pasa un cuchillo por el borde, desmolda y sirve frío, decorado con coco rallado fino.', false FROM public.recipes r WHERE r.slug='flan-suave-de-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Sirve una porción pequeña y decora solo con coco rallado fino: para menores de 5 años los frutos secos van siempre bien molidos, nunca enteros ni en trozos.' FROM public.recipes r WHERE r.slug='flan-suave-de-platano' ON CONFLICT (recipe_id, age_band) DO NOTHING;
