INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 0.25, 'taza', NULL, 1 FROM public.recipes r, public.ingredients i WHERE r.slug='frijoles-blancos-con-costillas-de-cerdo' AND i.code='frijol_blanco' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'unidad', 'sin grasa', 2 FROM public.recipes r, public.ingredients i WHERE r.slug='frijoles-blancos-con-costillas-de-cerdo' AND i.code='costilla_cerdo' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 0.5, 'taza', 'casero y sin sal, o agua', 3 FROM public.recipes r, public.ingredients i WHERE r.slug='frijoles-blancos-con-costillas-de-cerdo' AND i.code='caldo_verduras' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Cocina la costilla en agua hasta que la carne esté muy tierna y se desprenda fácilmente del hueso.', true FROM public.recipes r WHERE r.slug='frijoles-blancos-con-costillas-de-cerdo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Retira toda la carne del hueso, revísala con los dedos para descartar esquirlas y desménuzala.', true FROM public.recipes r WHERE r.slug='frijoles-blancos-con-costillas-de-cerdo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Mezcla los frijoles cocidos con la carne desmenuzada; si el niño tiene menos de 12 meses, aplasta bien los frijoles.', true FROM public.recipes r WHERE r.slug='frijoles-blancos-con-costillas-de-cerdo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Cocina todo junto unos minutos con el caldo para integrar los sabores y ajustar la textura.', false FROM public.recipes r WHERE r.slug='frijoles-blancos-con-costillas-de-cerdo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Retira cualquier fibra de carne difícil de masticar y sirve a temperatura tibia.', false FROM public.recipes r WHERE r.slug='frijoles-blancos-con-costillas-de-cerdo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Tritura los frijoles con la carne deshuesada y un poco de caldo hasta obtener un puré suave y sin grumos firmes.' FROM public.recipes r WHERE r.slug='frijoles-blancos-con-costillas-de-cerdo' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Aplasta los frijoles con un tenedor y desmenuza la carne bien fina, dejando una textura espesa y blanda.' FROM public.recipes r WHERE r.slug='frijoles-blancos-con-costillas-de-cerdo' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipes (slug, title, description, category, min_age_months, max_age_months, texture_stages, prep_minutes, cook_minutes, servings, difficulty, suitable_slots, is_batch_friendly, is_lunchbox_friendly, is_economic, requires_oven, requires_blender, conservation, is_freezable, freezer_months, protein_group, veggie_colors, carb_base, has_free_sugars, is_occasional_sweet, nutrition_blurb, tips, family_mode_note, source_book, source_numbers, image_filename, fallback_image) VALUES (
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'unidad', 'pelada y separada en gajos', 1 FROM public.recipes r, public.ingredients i WHERE r.slug='frutero-del-recreo' AND i.code='mandarina' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'unidad', 'pequeña y firme', 2 FROM public.recipes r, public.ingredients i WHERE r.slug='frutero-del-recreo' AND i.code='manzana' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 8, 'unidad', 'lavadas', 3 FROM public.recipes r, public.ingredients i WHERE r.slug='frutero-del-recreo' AND i.code='uva' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'unidad', 'firme, con cáscara', 4 FROM public.recipes r, public.ingredients i WHERE r.slug='frutero-del-recreo' AND i.code='platano' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'cucharadita', 'para que la manzana no se oxide', 5 FROM public.recipes r, public.ingredients i WHERE r.slug='frutero-del-recreo' AND i.code='limon' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Lava todas las frutas bajo el chorro de agua, frotando la cáscara de la manzana y las uvas con la mano, y sécalas bien con un paño limpio: la humedad acelera que se estropeen.', false FROM public.recipes r WHERE r.slug='frutero-del-recreo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Parte cada uva en cuartos a lo largo, nunca por la mitad ni entera: las frutas redondas del tamaño de la tráquea son la principal causa de atragantamiento en menores de 5 años.', true FROM public.recipes r WHERE r.slug='frutero-del-recreo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Corta la manzana en bastones delgados de medio centímetro de grosor, sin cáscara si el niño tiene menos de 3 años, y descarta el corazón con las semillas.', true FROM public.recipes r WHERE r.slug='frutero-del-recreo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Rocía los bastones de manzana con el jugo de limón y muévelos para cubrirlos: así llegan blancos y no oscurecidos al recreo.', false FROM public.recipes r WHERE r.slug='frutero-del-recreo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Pela la mandarina, separa los gajos y retira las semillas y los hilos blancos que sean duros.', true FROM public.recipes r WHERE r.slug='frutero-del-recreo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Acomoda las uvas, la manzana y la mandarina en compartimentos separados de un recipiente hermético para que no se mezclen los jugos, y guarda el plátano entero con su cáscara al lado, no dentro del recipiente.', false FROM public.recipes r WHERE r.slug='frutero-del-recreo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Cierra bien la lonchera y guárdala lejos del sol directo. Así preparada aguanta sin problema entre 4 y 5 horas a temperatura ambiente.', false FROM public.recipes r WHERE r.slug='frutero-del-recreo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Ofrece solo fruta blanda o cocida: gajos de mandarina sin semillas ni hollejo duro, plátano en bastones y manzana rallada o cocida al vapor. La manzana cruda en bastones todavía es demasiado dura a esta edad.' FROM public.recipes r WHERE r.slug='frutero-del-recreo' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Ya puede con manzana cruda en bastones finos, pero las uvas siguen yendo siempre partidas en cuartos a lo largo y bajo supervisión mientras come.' FROM public.recipes r WHERE r.slug='frutero-del-recreo' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_9a'::public.age_band, 'Puede llevar la fruta entera y pelarla en la escuela; incluye una mandarina, una manzana pequeña y un puñado de uvas partidas por la mitad.' FROM public.recipes r WHERE r.slug='frutero-del-recreo' ON CONFLICT (recipe_id, age_band) DO NOTHING;
