INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Mezcla la harina de avena, el puré de plátano, el aceite de coco y la canela hasta formar una masa homogénea.', false FROM public.recipes r WHERE r.slug='galletas-clasicas-de-avena-y-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Forma pequeñas bolitas y aplánalas para darles forma de galleta; colócalas en la bandeja con espacio entre ellas.', false FROM public.recipes r WHERE r.slug='galletas-clasicas-de-avena-y-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Hornea 15 minutos o hasta que estén doradas.', false FROM public.recipes r WHERE r.slug='galletas-clasicas-de-avena-y-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Deja enfriar antes de servir.', false FROM public.recipes r WHERE r.slug='galletas-clasicas-de-avena-y-platano' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Hornéalas un par de minutos menos para que queden más blandas y ofrécelas en piezas grandes que el bebé pueda sostener y chupar.' FROM public.recipes r WHERE r.slug='galletas-clasicas-de-avena-y-platano' ON CONFLICT (recipe_id, age_band) DO NOTHING;
