INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Agrega el aceite y amasa hasta integrarlo por completo.', false FROM public.recipes r WHERE r.slug='galletas-de-almendra-y-miel' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Forma unas 12 bolitas de masa y aplástalas ligeramente para dar forma a las galletas. Los niños pueden ayudar en este paso.', false FROM public.recipes r WHERE r.slug='galletas-de-almendra-y-miel' ON CONFLICT (recipe_id, step_number) DO NOTHING;
