INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Hornea de 12 a 15 minutos, hasta que estén doradas por los bordes. Si las quieres más crujientes, déjalas 2 minutos más.', false FROM public.recipes r WHERE r.slug='galletas-de-almendra-y-miel' ON CONFLICT (recipe_id, step_number) DO NOTHING;
