INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Toma pequeñas porciones, forma las galletas y aplánalas sobre una bandeja con papel de horno. Decora con las pasas si las usas.', false FROM public.recipes r WHERE r.slug='galletas-de-coco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Hornea a 180 °C por 15 minutos, hasta que estén firmes y doradas: así el huevo queda bien cocido. Sin horno: cocínalas en sartén a fuego medio con un poco de aceite de coco, dorándolas por ambos lados.', true FROM public.recipes r WHERE r.slug='galletas-de-coco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Prepara la versión con mitad avena para una textura más suave, omite las decoraciones y ofrécelas desmenuzadas en trocitos blandos.' FROM public.recipes r WHERE r.slug='galletas-de-coco' ON CONFLICT (recipe_id, age_band) DO NOTHING;
