INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Revisa una por una las ciruelas pasas y retira cualquier hueso que haya quedado: un hueso escondido puede atragantar o romper un diente.', true FROM public.recipes r WHERE r.slug='galletas-rellenas-de-ciruela-pasa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Cocina las ciruelas con el jugo de naranja a fuego bajo durante 10 minutos, hasta que estén muy blandas y el líquido casi se haya consumido.', false FROM public.recipes r WHERE r.slug='galletas-rellenas-de-ciruela-pasa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Tritúralas con la licuadora o el procesador hasta obtener una pasta espesa que se sostenga en la cuchara. Si queda muy líquida, devuélvela al fuego 3 minutos más.', false FROM public.recipes r WHERE r.slug='galletas-rellenas-de-ciruela-pasa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Deja enfriar el relleno mientras preparas la masa; caliente empapa la masa y la deja cruda por dentro.', false FROM public.recipes r WHERE r.slug='galletas-rellenas-de-ciruela-pasa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Mezcla la harina integral, las hojuelas de avena, la canela y la ralladura de naranja en un tazón.', false FROM public.recipes r WHERE r.slug='galletas-rellenas-de-ciruela-pasa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Agrega el aceite y frótalo con los dedos; luego suma el agua fría cucharada a cucharada hasta formar una masa que se una sin pegarse. Divídela en dos partes iguales.', false FROM public.recipes r WHERE r.slug='galletas-rellenas-de-ciruela-pasa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Precalienta el horno a 180 °C. Estira la primera mitad de la masa entre dos hojas de papel para hornear hasta formar un rectángulo de 20 x 25 cm y pásala a la bandeja con el papel de abajo.', false FROM public.recipes r WHERE r.slug='galletas-rellenas-de-ciruela-pasa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Extiende el relleno frío sobre la masa dejando 1 cm libre en los bordes, estira la segunda mitad del mismo tamaño y colócala encima. Presiona los bordes con un tenedor para sellarlos.', false FROM public.recipes r WHERE r.slug='galletas-rellenas-de-ciruela-pasa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 9, 'Pincha la superficie con un tenedor y marca 12 cuadritos con un cuchillo sin llegar hasta abajo, para que después sea fácil separarlos.', false FROM public.recipes r WHERE r.slug='galletas-rellenas-de-ciruela-pasa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 10, 'Hornea de 22 a 25 minutos, hasta que la superficie esté dorada y firme al tacto.', false FROM public.recipes r WHERE r.slug='galletas-rellenas-de-ciruela-pasa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 11, 'Deja enfriar por completo antes de cortar por las marcas: en caliente el relleno se desborda y las galletas se rompen.', false FROM public.recipes r WHERE r.slug='galletas-rellenas-de-ciruela-pasa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Ofrece medio cuadrito por porción y acompáñalo con agua: el relleno es pegajoso y conviene que coma sentado y sin prisa.' FROM public.recipes r WHERE r.slug='galletas-rellenas-de-ciruela-pasa' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_9a'::public.age_band, 'Un cuadrito entero es la porción para la lonchera escolar; combínalo con fruta fresca para equilibrar el dulzor.' FROM public.recipes r WHERE r.slug='galletas-rellenas-de-ciruela-pasa' ON CONFLICT (recipe_id, age_band) DO NOTHING;
