INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 0.5, 'cucharadita', 'poca; puedes reducirla aún más', 6 FROM public.recipes r, public.ingredients i WHERE r.slug='garbanzos-crujientes' AND i.code='sal' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Precalienta el horno a 200 °C.', false FROM public.recipes r WHERE r.slug='garbanzos-crujientes' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Enjuaga, escurre y seca muy bien los garbanzos con papel absorbente: mientras más secos, más crujientes quedarán.', false FROM public.recipes r WHERE r.slug='garbanzos-crujientes' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'En un tazón, mezcla el aceite de oliva con la paprika, el ajo en polvo, la cebolla en polvo y la sal.', false FROM public.recipes r WHERE r.slug='garbanzos-crujientes' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Vierte la mezcla sobre los garbanzos y revuelve hasta que queden bien impregnados.', false FROM public.recipes r WHERE r.slug='garbanzos-crujientes' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Distribuye los garbanzos en una bandeja forrada con papel de horno, sin amontonarlos.', false FROM public.recipes r WHERE r.slug='garbanzos-crujientes' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Hornea a 200 °C durante 30-35 minutos, removiendo cada 10 minutos para que se doren parejo y no se quemen.', false FROM public.recipes r WHERE r.slug='garbanzos-crujientes' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Apaga el horno y deja los garbanzos dentro 10 minutos más para que terminen de secarse; sácalos y deja enfriar por completo.', false FROM public.recipes r WHERE r.slug='garbanzos-crujientes' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Sírvelos solo a niños de 5 años en adelante: los garbanzos tostados duros pueden causar atragantamiento en los más pequeños.', true FROM public.recipes r WHERE r.slug='garbanzos-crujientes' ON CONFLICT (recipe_id, step_number) DO NOTHING;
