INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'taza', 'fresas, mango o uvas; elige fruta madura para que endulce sola', 1 FROM public.recipes r, public.ingredients i WHERE r.slug='gomitas-de-frutas' AND i.code='fruta_dulce' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
