INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'sobre', 'aprox. 7 g', 3 FROM public.recipes r, public.ingredients i WHERE r.slug='gomitas-de-frutas' AND i.code='gelatina_sin_sabor' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Licúa la fruta con el agua hasta obtener una mezcla homogénea.', false FROM public.recipes r WHERE r.slug='gomitas-de-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Vierte la mezcla en una olla pequeña, espolvorea la gelatina sin sabor por encima y deja hidratar 5 minutos.', false FROM public.recipes r WHERE r.slug='gomitas-de-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Calienta a fuego bajo revolviendo constantemente, solo hasta que la gelatina se disuelva por completo. No dejes que hierva: la gelatina hervida pierde su capacidad de cuajar.', false FROM public.recipes r WHERE r.slug='gomitas-de-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Vierte en moldes de silicona y refrigera de 3 a 4 horas hasta que cuajen por completo.', false FROM public.recipes r WHERE r.slug='gomitas-de-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Desmolda. Para menores de 5 años sírvelas en trozos pequeños y supervisa mientras las comen: las gomitas firmes pueden causar atragantamiento.', true FROM public.recipes r WHERE r.slug='gomitas-de-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Para los más pequeños prepara una versión más blanda: usa medio sobre de gelatina para la misma cantidad de fruta y sirve en cubos grandes tipo gelatina. Las gomitas firmes exigen supervisión en menores de 5 años.' FROM public.recipes r WHERE r.slug='gomitas-de-frutas' ON CONFLICT (recipe_id, age_band) DO NOTHING;
