INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Pica o muele finamente los frutos secos: para menores de 5 años nunca deben ir enteros ni en trozos grandes, por riesgo de atragantamiento.', true FROM public.recipes r WHERE r.slug='granola-casera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'En un bol grande, mezcla la avena, los frutos secos y el ajonjolí.', false FROM public.recipes r WHERE r.slug='granola-casera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'En una olla pequeña, calienta la miel con los dos aceites y la vainilla hasta integrar.', false FROM public.recipes r WHERE r.slug='granola-casera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Bate la clara de huevo con la pizca de sal hasta que espume; vierte la mezcla de aceites sobre los ingredientes secos, revuelve bien e incorpora la clara batida.', false FROM public.recipes r WHERE r.slug='granola-casera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'En horno: precalienta a 150 °C, esparce la mezcla sobre una bandeja con papel de hornear y hornea 30 minutos, removiendo a la mitad, hasta que esté dorada y seca. En sartén: cocina a fuego medio revolviendo constantemente hasta dorar. La clara debe quedar completamente cocida.', true FROM public.recipes r WHERE r.slug='granola-casera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Deja enfriar por completo en la bandeja para que termine de endurecer y guárdala en un frasco hermético.', false FROM public.recipes r WHERE r.slug='granola-casera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Usa los frutos secos finamente molidos (nunca enteros ni en trozos grandes) y ofrece la granola mezclada con yogur o fruta machacada para que se ablande.' FROM public.recipes r WHERE r.slug='granola-casera' ON CONFLICT (recipe_id, age_band) DO NOTHING;
