INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Lava y corta todas las verduras en trozos pequeños.', false FROM public.recipes r WHERE r.slug='guiso-arcoiris-de-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'En una olla con el aceite, sofríe la cebolla y el ajo picados hasta que estén dorados.', false FROM public.recipes r WHERE r.slug='guiso-arcoiris-de-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Añade el tomate rallado y cocina 5 minutos, hasta que reduzca.', false FROM public.recipes r WHERE r.slug='guiso-arcoiris-de-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Agrega la zanahoria, la papa y la calabacita, revolviendo bien.', false FROM public.recipes r WHERE r.slug='guiso-arcoiris-de-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Incorpora los ejotes, las arvejas y la paprika dulce; sazona con poca sal y pimienta.', false FROM public.recipes r WHERE r.slug='guiso-arcoiris-de-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Vierte el caldo y cocina a fuego medio 25-30 minutos, hasta que todas las verduras estén tiernas.', false FROM public.recipes r WHERE r.slug='guiso-arcoiris-de-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Antes de servir a menores de 4 años, aplasta las arvejas con un tenedor y corta los ejotes en trocitos pequeños: las legumbres enteras y redondas pueden causar atragantamiento.', true FROM public.recipes r WHERE r.slug='guiso-arcoiris-de-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Rectifica la sazón si hace falta y sirve caliente.', false FROM public.recipes r WHERE r.slug='guiso-arcoiris-de-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Tritura una porción sin sal hasta obtener un puré suave con un poco del caldo de cocción.' FROM public.recipes r WHERE r.slug='guiso-arcoiris-de-verduras' ON CONFLICT (recipe_id, age_band) DO NOTHING;
