INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Calienta el aceite en una sartén pequeña y sofríe la cebolla 2 minutos a fuego medio, hasta que esté transparente.', false FROM public.recipes r WHERE r.slug='huevito-en-salsa-de-tomate' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Ralla los tomates maduros por el lado grueso del rallador y descarta la cáscara que queda en tu mano; agrégalos a la sartén con el orégano.', false FROM public.recipes r WHERE r.slug='huevito-en-salsa-de-tomate' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Cocina la salsa 4 minutos a fuego medio, moviendo de vez en cuando, hasta que espese y pierda el sabor a tomate crudo.', false FROM public.recipes r WHERE r.slug='huevito-en-salsa-de-tomate' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Haz dos huecos en la salsa con la cuchara y casca un huevo dentro de cada uno.', false FROM public.recipes r WHERE r.slug='huevito-en-salsa-de-tomate' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Tapa la sartén y cocina de 4 a 5 minutos, hasta que la clara esté firme y la yema completamente cuajada. El huevo debe quedar bien cocido, sin partes líquidas.', true FROM public.recipes r WHERE r.slug='huevito-en-salsa-de-tomate' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Tuesta los bastones de pan integral, sirve el huevo con salsa encima y deja entibiar; para menores de 2 años pícalo con el tenedor antes de dárselo.', true FROM public.recipes r WHERE r.slug='huevito-en-salsa-de-tomate' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Pica el huevo cocido con el tenedor y mézclalo con un poco de salsa; sirve el pan en bastones blandos, sin corteza dura, y con muy poca sal.' FROM public.recipes r WHERE r.slug='huevito-en-salsa-de-tomate' ON CONFLICT (recipe_id, age_band) DO NOTHING;
