INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Cocina los huevos en agua hirviendo durante 10-12 minutos, hasta que la yema esté completamente firme. Enfríalos en agua fría y pélalos.', true FROM public.recipes r WHERE r.slug='huevos-de-colores' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Prepara los tintes: machaca la remolacha cocida en una taza de agua para el rosado y disuelve la cúrcuma en otra taza de agua tibia para el amarillo (o usa unas gotas de colorante alimenticio en cada recipiente).', false FROM public.recipes r WHERE r.slug='huevos-de-colores' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Parte los huevos por la mitad a lo largo y retira las yemas con una cucharita.', false FROM public.recipes r WHERE r.slug='huevos-de-colores' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Sumerge las claras en los líquidos de color durante 10-15 minutos, hasta que tomen el tono deseado; retíralas y sécalas con una servilleta.', false FROM public.recipes r WHERE r.slug='huevos-de-colores' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Aplasta las yemas con aguacate maduro, yogur natural o mayonesa comercial pasteurizada y unas especias suaves hasta formar una crema; también puedes rellenar con atún escurrido. Nunca uses mayonesa casera: lleva huevo crudo.', true FROM public.recipes r WHERE r.slug='huevos-de-colores' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Rellena las mitades de clara con la crema usando una cucharita o una manga.', false FROM public.recipes r WHERE r.slug='huevos-de-colores' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Refrigera hasta el momento de empacar y transporta siempre en lonchera térmica con gel refrigerante; consumir antes de 4 horas.', true FROM public.recipes r WHERE r.slug='huevos-de-colores' ON CONFLICT (recipe_id, step_number) DO NOTHING;
