INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Coloca en el procesador los garbanzos, el jugo de limón, el perejil, el tahini y el aceite de oliva.', false FROM public.recipes r WHERE r.slug='hummus-clasico' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Tritura hasta obtener una pasta espesa.', false FROM public.recipes r WHERE r.slug='hummus-clasico' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Agrega el agua poco a poco y sigue procesando hasta conseguir la textura deseada.', false FROM public.recipes r WHERE r.slug='hummus-clasico' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Refrigera 20 minutos antes de servir y consérvalo siempre en frío, hasta 3 días en recipiente tapado.', false FROM public.recipes r WHERE r.slug='hummus-clasico' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Prepáralo extra cremoso agregando más agua, y ofrécelo untado en pan suave o sobre bastones gruesos de verdura bien cocida.' FROM public.recipes r WHERE r.slug='hummus-clasico' ON CONFLICT (recipe_id, age_band) DO NOTHING;
