INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 100, 'gramo', NULL, 2 FROM public.recipes r, public.ingredients i WHERE r.slug='hummus-de-remolacha' AND i.code='remolacha_cocida' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
