INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 50, 'ml', 'del cocido de los garbanzos o de la remolacha, sin sal', 5 FROM public.recipes r, public.ingredients i WHERE r.slug='hummus-de-remolacha' AND i.code='caldo_coccion' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 10, 'ml', NULL, 6 FROM public.recipes r, public.ingredients i WHERE r.slug='hummus-de-remolacha' AND i.code='aceite_oliva' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Coloca todos los ingredientes en la licuadora o el procesador y mezcla hasta obtener una crema homogénea y espesa.', false FROM public.recipes r WHERE r.slug='hummus-de-remolacha' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Si deseas una textura más ligera, añade más caldo de cocción poco a poco.', false FROM public.recipes r WHERE r.slug='hummus-de-remolacha' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Sirve en un bol, decora con unas semillas de ajonjolí y consérvalo refrigerado hasta 3 días.', false FROM public.recipes r WHERE r.slug='hummus-de-remolacha' ON CONFLICT (recipe_id, step_number) DO NOTHING;
