INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 0.25, 'unidad', 'pequeña, cruda y pelada (unos 30-40 g)', 1 FROM public.recipes r, public.ingredients i WHERE r.slug='jugo-vitamina-c' AND i.code='remolacha' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 0.5, 'unidad', 'mediana, pelada y en trozos', 2 FROM public.recipes r, public.ingredients i WHERE r.slug='jugo-vitamina-c' AND i.code='zanahoria' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 0.5, 'unidad', 'sin corazón ni semillas, con cáscara bien lavada', 3 FROM public.recipes r, public.ingredients i WHERE r.slug='jugo-vitamina-c' AND i.code='manzana' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 0.5, 'unidad', 'pelada y sin semillas, o su jugo', 4 FROM public.recipes r, public.ingredients i WHERE r.slug='jugo-vitamina-c' AND i.code='naranja' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 0.5, 'taza', 'unos 120 ml, para facilitar el licuado', 5 FROM public.recipes r, public.ingredients i WHERE r.slug='jugo-vitamina-c' AND i.code='agua' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Lava muy bien la remolacha, la zanahoria, la manzana y la naranja. Pela la remolacha y la zanahoria, y retira el corazón y las semillas de la manzana y la naranja.', false FROM public.recipes r WHERE r.slug='jugo-vitamina-c' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Corta todo en trozos pequeños para que la licuadora trabaje sin esfuerzo.', false FROM public.recipes r WHERE r.slug='jugo-vitamina-c' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Licúa los trozos con el agua fría durante 1 a 2 minutos, hasta obtener una mezcla homogénea de color rubí.', false FROM public.recipes r WHERE r.slug='jugo-vitamina-c' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Cuela con un colador fino si prefieres una textura más ligera; para los niños más grandes puedes dejar la pulpa y conservar la fibra. Sirve enseguida y bien frío.', false FROM public.recipes r WHERE r.slug='jugo-vitamina-c' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Ofrece como máximo medio vaso pequeño (60-90 ml), diluido con agua a partes iguales y usando solo una rodaja pequeña de remolacha. A esta edad prioriza la fruta entera en trocitos blandos y el agua como bebida principal.' FROM public.recipes r WHERE r.slug='jugo-vitamina-c' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Sirve una porción pequeña de medio vaso (100-120 ml), colado para una textura suave. Ofrécelo como acompañamiento ocasional, no a diario.' FROM public.recipes r WHERE r.slug='jugo-vitamina-c' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_9a'::public.age_band, 'Sirve sin colar para conservar la fibra y agrega hielo; un vaso pequeño (alrededor de 150 ml) es suficiente.' FROM public.recipes r WHERE r.slug='jugo-vitamina-c' ON CONFLICT (recipe_id, age_band) DO NOTHING;
