INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 500, 'g', 'o harina de avena', 1 FROM public.recipes r, public.ingredients i WHERE r.slug='laminas-crocantes-de-masa' AND i.code='harina_trigo' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 2, 'cucharada', 'o ghee, a temperatura ambiente', 2 FROM public.recipes r, public.ingredients i WHERE r.slug='laminas-crocantes-de-masa' AND i.code='mantequilla' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 3, 'cucharada', 'rallada, para disolver en el agua (o 2 cucharadas de miel)', 3 FROM public.recipes r, public.ingredients i WHERE r.slug='laminas-crocantes-de-masa' AND i.code='panela' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 2, 'taza', 'tibia', 4 FROM public.recipes r, public.ingredients i WHERE r.slug='laminas-crocantes-de-masa' AND i.code='agua' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'unidad', 'solo la ralladura, opcional para aromatizar', 5 FROM public.recipes r, public.ingredients i WHERE r.slug='laminas-crocantes-de-masa' AND i.code='limon' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'cucharada', 'opcional, para espolvorear', 6 FROM public.recipes r, public.ingredients i WHERE r.slug='laminas-crocantes-de-masa' AND i.code='azucar' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Disuelve la panela rallada en el agua tibia y deja que se enfríe.', false FROM public.recipes r WHERE r.slug='laminas-crocantes-de-masa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Mezcla la harina con la mantequilla usando la punta de los dedos hasta lograr una textura arenosa.', false FROM public.recipes r WHERE r.slug='laminas-crocantes-de-masa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Agrega el agua de panela poco a poco y amasa hasta obtener una masa suave y manejable. Déjala reposar 10 minutos tapada.', false FROM public.recipes r WHERE r.slug='laminas-crocantes-de-masa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Extiende la masa sobre una superficie enharinada y estírala con un rodillo hasta obtener una lámina delgada (2-3 mm).', false FROM public.recipes r WHERE r.slug='laminas-crocantes-de-masa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Corta en tiras o rombos delgados y uniformes.', false FROM public.recipes r WHERE r.slug='laminas-crocantes-de-masa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Hornea a 180 °C durante 10-15 minutos hasta que se doren, o usa la freidora de aire a 180 °C por 8-10 minutos.', false FROM public.recipes r WHERE r.slug='laminas-crocantes-de-masa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Deja enfriar y, si quieres, espolvorea con la ralladura de limón o un poquito de azúcar antes de servir.', false FROM public.recipes r WHERE r.slug='laminas-crocantes-de-masa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Para los menores de 5 años, parte las láminas en trozos del tamaño de un bocado y sírvelas siempre con el niño sentado: los crocantes grandes se astillan en la boca.', true FROM public.recipes r WHERE r.slug='laminas-crocantes-de-masa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Estira la masa aún más fina y corta láminas pequeñas del tamaño de un bocado; sirve solo 2 o 3 por vez y siempre con el niño sentado, porque los trozos crocantes grandes se quiebran en astillas dentro de la boca.' FROM public.recipes r WHERE r.slug='laminas-crocantes-de-masa' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_9a'::public.age_band, 'Corta tiras largas o rombos y deja que el niño espolvoree la ralladura de limón al final: a esta edad disfrutan más la receta si participan en el acabado.' FROM public.recipes r WHERE r.slug='laminas-crocantes-de-masa' ON CONFLICT (recipe_id, age_band) DO NOTHING;
