INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 3, 'unidad', 'de cáscara amarilla con manchas negras; no es banana de fruta', 1 FROM public.recipes r, public.ingredients i WHERE r.slug='lasana-de-platano-maduro' AND i.code='platano_macho' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 300, 'g', 'o carne molida de res cocida', 2 FROM public.recipes r, public.ingredients i WHERE r.slug='lasana-de-platano-maduro' AND i.code='pechuga_pollo' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'taza', 'o cualquier queso que derrita bien', 3 FROM public.recipes r, public.ingredients i WHERE r.slug='lasana-de-platano-maduro' AND i.code='queso_mozzarella' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 2, 'cucharada', 'opcional, para gratinar', 4 FROM public.recipes r, public.ingredients i WHERE r.slug='lasana-de-platano-maduro' AND i.code='queso_parmesano' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'pizca', 'para sazonar el relleno; y pimienta al gusto', 5 FROM public.recipes r, public.ingredients i WHERE r.slug='lasana-de-platano-maduro' AND i.code='sal' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'cucharadita', 'para engrasar la fuente', 6 FROM public.recipes r, public.ingredients i WHERE r.slug='lasana-de-platano-maduro' AND i.code='aceite' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Cocina los plátanos macho con cáscara en agua hirviendo por 15-20 minutos, hasta que estén muy blandos. Pélalos y tritúralos en puré.', false FROM public.recipes r WHERE r.slug='lasana-de-platano-maduro' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Verifica que el pollo (o la carne molida) esté completamente cocido, sin partes rosadas, y sazónalo con la pizca de sal y pimienta.', true FROM public.recipes r WHERE r.slug='lasana-de-platano-maduro' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Engrasa una fuente para hornear y extiende una capa de puré de plátano.', false FROM public.recipes r WHERE r.slug='lasana-de-platano-maduro' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Agrega una capa de pollo desmenuzado y espolvorea queso mozzarella. Repite las capas hasta terminar los ingredientes.', false FROM public.recipes r WHERE r.slug='lasana-de-platano-maduro' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Cubre con una última capa de queso y, si lo deseas, el parmesano para gratinar.', false FROM public.recipes r WHERE r.slug='lasana-de-platano-maduro' ON CONFLICT (recipe_id, step_number) DO NOTHING;
