INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Cocina la pasta en agua con poca sal según las indicaciones del paquete y escúrrela.', false FROM public.recipes r WHERE r.slug='macarrones-con-queso-y-coliflor' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Licúa la coliflor cocida con la leche, el ajo y la mantequilla hasta obtener una salsa cremosa.', false FROM public.recipes r WHERE r.slug='macarrones-con-queso-y-coliflor' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Lleva la salsa a una sartén a fuego bajo, agrega el queso rallado y revuelve hasta que se derrita.', false FROM public.recipes r WHERE r.slug='macarrones-con-queso-y-coliflor' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Incorpora la pasta cocida y mezcla bien para que se impregne de la salsa; cocina 2 minutos más.', false FROM public.recipes r WHERE r.slug='macarrones-con-queso-y-coliflor' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Sirve caliente en casa o llévalo bien caliente en un termo precalentado para la lonchera.', false FROM public.recipes r WHERE r.slug='macarrones-con-queso-y-coliflor' ON CONFLICT (recipe_id, step_number) DO NOTHING;
