INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Cocina los macarrones en agua hirviendo sin sal hasta que estén bien blandos y escúrrelos.', false FROM public.recipes r WHERE r.slug='macarrones-con-salsa-de-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Cocina el brócoli al vapor hasta que esté muy tierno y déjalo entibiar.', false FROM public.recipes r WHERE r.slug='macarrones-con-salsa-de-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Tritura el brócoli tibio con la leche materna o fórmula hasta obtener una salsa cremosa; no la calientes de nuevo para no dañar la leche.', false FROM public.recipes r WHERE r.slug='macarrones-con-salsa-de-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
