INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Tritura los macarrones junto con la salsa hasta lograr un puré suave, sin trozos de pasta que puedan atragantar.' FROM public.recipes r WHERE r.slug='macarrones-con-salsa-de-brocoli' ON CONFLICT (recipe_id, age_band) DO NOTHING;
