INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 200, 'g', '1 grande, pelada y en cubos', 2 FROM public.recipes r, public.ingredients i WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' AND i.code='papa' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 80, 'g', 'fresco o congelado', 3 FROM public.recipes r, public.ingredients i WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' AND i.code='choclo' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'unidad', 'pequeña, pelada y en rodajas', 4 FROM public.recipes r, public.ingredients i WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' AND i.code='zanahoria' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'cucharadita', NULL, 5 FROM public.recipes r, public.ingredients i WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' AND i.code='aceite_oliva' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 500, 'ml', 'sin sal', 6 FROM public.recipes r, public.ingredients i WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' AND i.code='agua' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Coloca el muslo de pollo en una olla con el agua fría, lleva a hervor y cocina a fuego medio durante 20 minutos, hasta que la carne se separe sola y no quede ningún punto rosado ni jugo rosado al cortarla.', true FROM public.recipes r WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Agrega la papa, la zanahoria y el choclo a la misma olla durante los últimos 15 minutos, hasta que la papa se deshaga al pincharla.', false FROM public.recipes r WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Retira el pollo, déjalo entibiar y revísalo con los dedos: quita cualquier resto de hueso, cartílago o tendón antes de deshilacharlo.', true FROM public.recipes r WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Deshilacha el pollo en hebras muy finas, más cortas que tu uña. Las hebras largas o los trozos firmes de carne no son seguros a esta edad.', true FROM public.recipes r WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Aplasta los granos de choclo uno a uno con el dorso de un tenedor o pícalos finos: los granos enteros son redondos, resbalosos y del tamaño exacto que puede obstruir la vía aérea de un bebé.', true FROM public.recipes r WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Reserva dos bastones de papa cocida del largo de tu dedo y machaca el resto de la papa y la zanahoria con un tenedor, dejando grumos blandos a propósito: no la conviertas en puré liso.', false FROM public.recipes r WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Mezcla el machacado con las hebras de pollo, el choclo aplastado y el aceite de oliva, y agrega caldo de la cocción cucharada a cucharada hasta lograr una textura espesa que se sostenga en la cuchara.', false FROM public.recipes r WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Sirve el machacado tibio, a temperatura de mano, y coloca al lado los bastones de papa para que el bebé los tome con la mano y practique llevárselos solo a la boca.', false FROM public.recipes r WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 9, 'Acompáñalo durante toda la comida, con el bebé sentado y erguido en su silla, y nunca lo dejes comer solo ni acostado.', true FROM public.recipes r WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Deja los trozos más grandes y solo parte los granos de choclo por la mitad. Ya puedes agregar una pizca de sal y un poco de perejil picado, y servirlo con una cuchara para que coma solo.' FROM public.recipes r WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Sírvelo como guiso, con el pollo en trozos de bocado, la papa en cubos y el choclo entero, acompañado de arroz o de una ensalada picada fina.' FROM public.recipes r WHERE r.slug='machacado-de-pollo-choclo-y-papa-con-trocitos' ON CONFLICT (recipe_id, age_band) DO NOTHING;
