INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 2, 'taza', 'sin sal y sin piel', 1 FROM public.recipes r, public.ingredients i WHERE r.slug='mantequilla-de-mani-casera' AND i.code='mani' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'cucharada', 'o aceite de oliva', 2 FROM public.recipes r, public.ingredients i WHERE r.slug='mantequilla-de-mani-casera' AND i.code='aceite_coco' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'pizca', 'opcional; omítela para menores de 1 año', 3 FROM public.recipes r, public.ingredients i WHERE r.slug='mantequilla-de-mani-casera' AND i.code='sal' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Extiende el maní en una bandeja y tuéstalo en el horno a 180 °C por 10 minutos para resaltar su sabor.', false FROM public.recipes r WHERE r.slug='mantequilla-de-mani-casera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Deja entibiar y procesa en licuadora o procesador, raspando los bordes de vez en cuando: primero se hará polvo y luego una pasta (toma de 5 a 10 minutos, ten paciencia).', false FROM public.recipes r WHERE r.slug='mantequilla-de-mani-casera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Añade el aceite y sigue triturando hasta lograr una consistencia cremosa; agrega la pizca de sal solo si la usas.', false FROM public.recipes r WHERE r.slug='mantequilla-de-mani-casera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Guarda en un frasco hermético limpio.', false FROM public.recipes r WHERE r.slug='mantequilla-de-mani-casera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Sirve siempre untada en capa fina: nunca ofrezcas cucharadas grandes de crema espesa ni maní entero a menores de 5 años.', true FROM public.recipes r WHERE r.slug='mantequilla-de-mani-casera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Mezcla media cucharadita con puré de fruta o con su papilla de avena, o unta una capa muy fina sobre pan suave: así se introduce el maní de forma segura.' FROM public.recipes r WHERE r.slug='mantequilla-de-mani-casera' ON CONFLICT (recipe_id, age_band) DO NOTHING;
