INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 0.5, 'taza', 'para el fondo de la fuente', 5 FROM public.recipes r, public.ingredients i WHERE r.slug='manzana-asada-rellena-de-avena' AND i.code='agua' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Precalienta el horno a 180 °C.', false FROM public.recipes r WHERE r.slug='manzana-asada-rellena-de-avena' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Lava las manzanas y retira el corazón desde arriba con un descorazonador o un cuchillo pequeño, sin atravesar la base. Asegúrate de sacar todas las semillas y las partes duras: no pueden quedar restos en el hueco.', true FROM public.recipes r WHERE r.slug='manzana-asada-rellena-de-avena' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Mezcla en un bol la avena con la canela y la mantequilla derretida, y rellena con esa mezcla el hueco de cada manzana.', false FROM public.recipes r WHERE r.slug='manzana-asada-rellena-de-avena' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Acomódalas en una fuente, agrega el agua en el fondo para que no se sequen y hornea 30 minutos, hasta que la pulpa esté muy blanda al pincharla con un palillo.', false FROM public.recipes r WHERE r.slug='manzana-asada-rellena-de-avena' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Deja entibiar al menos 10 minutos antes de servir: el relleno guarda mucho calor. Retira la cáscara para los menores de 2 años, porque no la pueden masticar.', true FROM public.recipes r WHERE r.slug='manzana-asada-rellena-de-avena' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Retira la cáscara, saca la pulpa con una cuchara y machácala junto con la avena hasta lograr un puré grumoso y tibio.' FROM public.recipes r WHERE r.slug='manzana-asada-rellena-de-avena' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Sirve media manzana sin cáscara, cortada en trozos pequeños y bien blandos, con parte del relleno de avena mezclado.' FROM public.recipes r WHERE r.slug='manzana-asada-rellena-de-avena' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Sirve la manzana entera sin cáscara, en un plato hondo, acompañada de una cucharada de yogur natural.' FROM public.recipes r WHERE r.slug='manzana-asada-rellena-de-avena' ON CONFLICT (recipe_id, age_band) DO NOTHING;
