INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Pela la papa, córtala en trozos y cocínala en agua hirviendo unos 15 minutos, hasta que esté tierna; escúrrela y machácala.', false FROM public.recipes r WHERE r.slug='medallones-de-pescado-blanco-y-papa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Revisa el pescado cuidadosamente con los dedos y retira cualquier espina que encuentres.', true FROM public.recipes r WHERE r.slug='medallones-de-pescado-blanco-y-papa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'En una sartén con la mitad del aceite, sofríe la cebolla y el ajo picados hasta que estén dorados.', false FROM public.recipes r WHERE r.slug='medallones-de-pescado-blanco-y-papa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Tritura el pescado en un procesador de alimentos (o pícalo muy fino) y mézclalo en un tazón con la papa machacada, el sofrito, el huevo, el pan molido y el perejil; sazona con muy poca sal.', false FROM public.recipes r WHERE r.slug='medallones-de-pescado-blanco-y-papa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Forma medallones pequeños con la mezcla, del tamaño de la palma de una mano infantil.', false FROM public.recipes r WHERE r.slug='medallones-de-pescado-blanco-y-papa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Calienta el resto del aceite en la sartén y dora los medallones 3-4 minutos por lado, hasta que estén dorados y completamente cocidos por dentro (el huevo y el pescado no deben quedar crudos).', true FROM public.recipes r WHERE r.slug='medallones-de-pescado-blanco-y-papa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Sírvelos calientes con ensalada o una salsa ligera de yogur natural.', false FROM public.recipes r WHERE r.slug='medallones-de-pescado-blanco-y-papa' ON CONFLICT (recipe_id, step_number) DO NOTHING;
