INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 180, 'ml', 'agrégala poco a poco; usa solo la necesaria (150-180 ml)', 3 FROM public.recipes r, public.ingredients i WHERE r.slug='nachos-caseros' AND i.code='agua' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
