INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 2, 'cucharada', 'para la sartén y para pintar antes de hornear', 5 FROM public.recipes r, public.ingredients i WHERE r.slug='nachos-caseros' AND i.code='aceite' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Mezcla las harinas con la sal y agrega el agua poco a poco, amasando hasta obtener una masa flexible que no se pegue en las manos.', false FROM public.recipes r WHERE r.slug='nachos-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Deja reposar la masa tapada en el refrigerador durante 20 minutos.', false FROM public.recipes r WHERE r.slug='nachos-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Divide la masa en porciones pequeñas y estíralas con un rodillo hasta obtener tortillas delgadas.', false FROM public.recipes r WHERE r.slug='nachos-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Cocina cada tortilla en una sartén ligeramente engrasada a fuego alto, 1 minuto por lado. Este precocido es indispensable: las tortillas siempre se cocinan en sartén antes de pasar al horno.', false FROM public.recipes r WHERE r.slug='nachos-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Para que queden bien crujientes, deja secar las tortillas ya cocidas al aire, de 2 horas hasta un día: cuanto más secas, más crujiente el nacho.', false FROM public.recipes r WHERE r.slug='nachos-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Córtalas en triángulos, píntalos con un poco de aceite y hornéalos a 180 °C de 8 a 10 minutos, hasta que estén dorados y crujientes. Deja enfriar por completo antes de guardar.', false FROM public.recipes r WHERE r.slug='nachos-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
