INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Pela las peras maduras y rállalas por el lado grueso del rallador.', false FROM public.recipes r WHERE r.slug='natilla-de-maiz-con-pera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'En una olla, disuelve la fécula de maíz en la leche fría batiendo hasta que no quede ni un grumo. Siempre en frío: si la leche está caliente, la fécula se apelmaza.', false FROM public.recipes r WHERE r.slug='natilla-de-maiz-con-pera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Agrega la pera rallada y la rama de canela, lleva a fuego medio y cocina de 6 a 8 minutos moviendo sin parar, hasta que espese y cubra el reverso de la cuchara.', false FROM public.recipes r WHERE r.slug='natilla-de-maiz-con-pera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Retira del fuego y saca la rama de canela completa: no puede llegar al plato de los niños. Incorpora la vainilla y mezcla.', true FROM public.recipes r WHERE r.slug='natilla-de-maiz-con-pera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Reparte en vasitos individuales, deja entibiar sobre la mesa y refrigera al menos 1 hora antes de servir.', false FROM public.recipes r WHERE r.slug='natilla-de-maiz-con-pera' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Sirve una porción pequeña apenas fría y suma pera rallada fresca por encima en vez de trozos, para que la cuchara entre fácil.' FROM public.recipes r WHERE r.slug='natilla-de-maiz-con-pera' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Sírvela bien fría en su propio vasito y deja que la decore con cubos pequeños de pera y una pizca de canela.' FROM public.recipes r WHERE r.slug='natilla-de-maiz-con-pera' ON CONFLICT (recipe_id, age_band) DO NOTHING;
