INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Con el borde de un vaso pequeño, saca un círculo en el centro de cada rebanada de pan y reserva los círculos.', false FROM public.recipes r WHERE r.slug='nido-de-pan-integral-con-huevo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Calienta una sartén antiadherente a fuego medio-bajo con la mantequilla y coloca las rebanadas junto con los círculos de pan.', false FROM public.recipes r WHERE r.slug='nido-de-pan-integral-con-huevo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Casca un huevo dentro del hueco de cada rebanada, con cuidado de que no se desborde.', false FROM public.recipes r WHERE r.slug='nido-de-pan-integral-con-huevo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Tapa la sartén y cocina de 4 a 5 minutos, hasta que la clara esté blanca y firme y la yema completamente cuajada. No debe quedar nada líquido: el huevo va siempre bien cocido para los niños.', true FROM public.recipes r WHERE r.slug='nido-de-pan-integral-con-huevo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Voltea con una espátula ancha y dora 30 segundos más si quieres el pan más crocante.', false FROM public.recipes r WHERE r.slug='nido-de-pan-integral-con-huevo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Espolvorea el queso rallado y el perejil, deja entibiar y corta en tiras antes de servir a los más pequeños.', true FROM public.recipes r WHERE r.slug='nido-de-pan-integral-con-huevo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Corta el nido en tiras del ancho de un dedo, retirando los bordes más duros del pan, y sírvelo tibio para que pueda agarrarlo con la mano.' FROM public.recipes r WHERE r.slug='nido-de-pan-integral-con-huevo' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Déjalo sacar el círculo con el borde de un vaso y cascar el huevo dentro del hueco; sirve la rebanada entera con tenedor.' FROM public.recipes r WHERE r.slug='nido-de-pan-integral-con-huevo' ON CONFLICT (recipe_id, age_band) DO NOTHING;
