INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Mezcla en un bol el brócoli picado con la avena molida, el queso, el ajo, el orégano, la pizca de sal y la pimienta.', false FROM public.recipes r WHERE r.slug='nuggets-de-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Agrega el huevo y mezcla hasta obtener una masa compacta; si queda muy húmeda, suma 1 cucharada más de avena.', false FROM public.recipes r WHERE r.slug='nuggets-de-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Con las manos ligeramente húmedas, forma nuggets pequeños y aplanados, y pásalos por la avena o el pan rallado extra para que queden crujientes.', false FROM public.recipes r WHERE r.slug='nuggets-de-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Al horno: precalienta a 200 °C y hornéalos sobre una bandeja con papel de horno por 20-25 minutos, volteándolos a la mitad del tiempo.', false FROM public.recipes r WHERE r.slug='nuggets-de-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'En sartén: dóralos con 1 cucharada de aceite a fuego medio, 3-4 minutos por lado.', false FROM public.recipes r WHERE r.slug='nuggets-de-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Verifica que estén firmes y bien cocidos por dentro (la masa lleva huevo y debe quedar completamente cocida) y déjalos entibiar antes de empacar.', true FROM public.recipes r WHERE r.slug='nuggets-de-brocoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Prepara la masa sin sal, forma mini porciones bien aplanadas, cocínalas hasta que estén completamente cocidas por dentro y sírvelas partidas en trozos pequeños.' FROM public.recipes r WHERE r.slug='nuggets-de-brocoli' ON CONFLICT (recipe_id, age_band) DO NOTHING;
