INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Precalienta el horno a 180 °C (o ten lista una sartén con el aceite de oliva).', false FROM public.recipes r WHERE r.slug='nuggets-de-pollo-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Corta la pechuga de pollo en trozos pequeños, tamaño bocado y de grosor parejo.', false FROM public.recipes r WHERE r.slug='nuggets-de-pollo-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'En un tazón, bate el huevo con la pizca de sal.', false FROM public.recipes r WHERE r.slug='nuggets-de-pollo-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'En otro tazón, mezcla el pan molido con el ajo en polvo y el orégano.', false FROM public.recipes r WHERE r.slug='nuggets-de-pollo-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Pasa cada trozo de pollo primero por el huevo y luego por la mezcla de pan molido; lávate las manos al terminar de manipular el pollo crudo.', true FROM public.recipes r WHERE r.slug='nuggets-de-pollo-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Hornea 20 minutos volteando a la mitad (o dóralos en la sartén por tandas), hasta que estén dorados y completamente cocidos: corta el nugget más grande y verifica que no quede rosado por dentro.', true FROM public.recipes r WHERE r.slug='nuggets-de-pollo-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Mientras se hornean, mezcla el yogur natural con unas gotas de jugo de limón para el dip; si prefieres guacamole, machaca el aguacate con un poco de limón.', false FROM public.recipes r WHERE r.slug='nuggets-de-pollo-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Deja entibiar los nuggets un par de minutos y sírvelos con el dip.', false FROM public.recipes r WHERE r.slug='nuggets-de-pollo-caseros' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Corta los nuggets en trocitos pequeños antes de servir y comprueba que el interior esté suave y jugoso; ofrece el dip de yogur para que moje sin ayuda.' FROM public.recipes r WHERE r.slug='nuggets-de-pollo-caseros' ON CONFLICT (recipe_id, age_band) DO NOTHING;
