INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 9, 'Sirve siempre con un adulto presente. A los menores de 3 años dales la paleta en trocitos dentro de un tazón, sin el palito, para evitar accidentes.', true FROM public.recipes r WHERE r.slug='paletas-de-sandia-y-kiwi' ON CONFLICT (recipe_id, step_number) DO NOTHING;
