INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Precalienta el horno a 180 °C y forra dos bandejas con papel para hornear.', false FROM public.recipes r WHERE r.slug='palitos-crocantes-de-avena-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Mezcla en un tazón la harina integral, la avena molida, el ajonjolí, el orégano y la pizca de sal.', false FROM public.recipes r WHERE r.slug='palitos-crocantes-de-avena-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Agrega el aceite y frótalo con los dedos hasta que la mezcla parezca arena húmeda.', false FROM public.recipes r WHERE r.slug='palitos-crocantes-de-avena-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Vierte el agua tibia poco a poco y amasa 3 minutos hasta obtener una masa lisa que no se pegue a las manos. Déjala reposar 10 minutos tapada con un paño.', false FROM public.recipes r WHERE r.slug='palitos-crocantes-de-avena-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Estira la masa sobre la mesa enharinada hasta dejarla de 3 mm de grosor y córtala en tiras de 1 cm de ancho por 12 cm de largo con un cuchillo o una rueda de cortar pizza.', false FROM public.recipes r WHERE r.slug='palitos-crocantes-de-avena-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Acomoda los palitos en las bandejas separados entre sí y hornéalos de 18 a 22 minutos, hasta que estén dorados y suenen huecos al golpearlos.', false FROM public.recipes r WHERE r.slug='palitos-crocantes-de-avena-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Déjalos enfriar por completo sobre una rejilla: terminan de endurecer al enfriarse y solo así quedan bien crocantes.', false FROM public.recipes r WHERE r.slug='palitos-crocantes-de-avena-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Ofrece los palitos enteros para que el niño los muerda por la punta y nunca partidos en trocitos redondos. Debe comerlos sentado, sin correr ni hablar con la boca llena, porque los alimentos duros y pequeños son riesgo de atragantamiento antes de los 5 años.', true FROM public.recipes r WHERE r.slug='palitos-crocantes-de-avena-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Amasa los palitos más gruesos (como un lápiz) y hornéalos 3 minutos menos para que queden firmes pero no duros como vidrio. Ofrécele uno a la vez, siempre sentado y acompañado.' FROM public.recipes r WHERE r.slug='palitos-crocantes-de-avena-y-ajonjoli' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Dos o tres palitos son una porción de colación. Empácalos junto a bastones de zanahoria cocida o fruta firme para completar el recreo.' FROM public.recipes r WHERE r.slug='palitos-crocantes-de-avena-y-ajonjoli' ON CONFLICT (recipe_id, age_band) DO NOTHING;
