INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Ralla el calabacín y exprímelo con las manos para retirar el exceso de agua.', false FROM public.recipes r WHERE r.slug='pan-de-calabacin' ON CONFLICT (recipe_id, step_number) DO NOTHING;
