INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Hornea a 200 °C (horno precalentado) por 15-20 minutos, hasta que esté firme y al insertar un palillo salga limpio: así el huevo queda bien cocido.', true FROM public.recipes r WHERE r.slug='pan-de-calabacin' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Con prisa: cocina en microondas 2-3 minutos en un recipiente apto y verifica que el centro esté cocido.', false FROM public.recipes r WHERE r.slug='pan-de-calabacin' ON CONFLICT (recipe_id, step_number) DO NOTHING;
