INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Precalienta el horno a 180 °C y forra un molde rectangular de 20 x 10 cm con papel para hornear.', false FROM public.recipes r WHERE r.slug='pan-de-camote-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Cocina el camote al vapor durante 15 minutos, hasta que se deshaga al pincharlo con un tenedor, y machácalo hasta formar un puré liso. Déjalo entibiar.', false FROM public.recipes r WHERE r.slug='pan-de-camote-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Machaca el plátano maduro con un tenedor y mézclalo con el puré de camote, el aceite y el agua.', false FROM public.recipes r WHERE r.slug='pan-de-camote-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'En otro tazón mezcla la harina integral, las hojuelas de avena, el polvo para hornear, la canela y la pizca de sal.', false FROM public.recipes r WHERE r.slug='pan-de-camote-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Une los ingredientes secos con la mezcla de camote usando movimientos envolventes, sin batir de más: la masa debe quedar espesa y pegajosa.', false FROM public.recipes r WHERE r.slug='pan-de-camote-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Vierte la masa en el molde, alisa la superficie con una cuchara mojada y esparce el ajonjolí por encima.', false FROM public.recipes r WHERE r.slug='pan-de-camote-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Hornea de 35 a 40 minutos, hasta que un palillo insertado en el centro salga limpio.', false FROM public.recipes r WHERE r.slug='pan-de-camote-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Deja enfriar por completo sobre una rejilla antes de cortarlo. Si lo empacas tibio, el vapor lo humedece y la miga se apelmaza dentro de la lonchera.', false FROM public.recipes r WHERE r.slug='pan-de-camote-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 9, 'Corta rebanadas y, para menores de 4 años, divide cada rebanada en tiras del ancho de tu dedo: así las toman con la mano y no se llevan bocados grandes a la boca.', true FROM public.recipes r WHERE r.slug='pan-de-camote-y-ajonjoli' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Sirve media rebanada cortada en tiras del ancho de tu dedo y ofrécele agua para acompañar. La miga es densa: conviene que coma sentado, tranquilo y con supervisión.' FROM public.recipes r WHERE r.slug='pan-de-camote-y-ajonjoli' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Una rebanada cortada en cuatro tiras es una porción adecuada para la lonchera; acompáñala con fruta firme como manzana o mandarina.' FROM public.recipes r WHERE r.slug='pan-de-camote-y-ajonjoli' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_9a'::public.age_band, 'Dos rebanadas untadas con crema de semillas o de maní hacen una colación completa para la jornada escolar larga.' FROM public.recipes r WHERE r.slug='pan-de-camote-y-ajonjoli' ON CONFLICT (recipe_id, age_band) DO NOTHING;
