INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Forma bolitas pequeñas y colócalas en una bandeja engrasada o con papel para hornear, dejando espacio entre ellas.', false FROM public.recipes r WHERE r.slug='pan-de-queso' ON CONFLICT (recipe_id, step_number) DO NOTHING;
