INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'En un bol, mezcla la harina con la sal; agrega la mezcla de levadura y el aceite de oliva.', false FROM public.recipes r WHERE r.slug='pan-integral-casero' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Amasa de 8 a 10 minutos hasta obtener una masa suave y elástica.', false FROM public.recipes r WHERE r.slug='pan-integral-casero' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Tapa el bol con un paño y deja reposar 1 hora en un lugar tibio, hasta que la masa duplique su tamaño.', false FROM public.recipes r WHERE r.slug='pan-integral-casero' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Forma un pan, colócalo en un molde engrasado y déjalo reposar 15 minutos más mientras precalientas el horno.', false FROM public.recipes r WHERE r.slug='pan-integral-casero' ON CONFLICT (recipe_id, step_number) DO NOTHING;
