INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Agrega el puré de zanahoria, la remolacha rallada, el aceite y el agua tibia poco a poco. Incorporar los vegetales desde el inicio, antes del leudado, asegura un color parejo y una masa que crece bien.', false FROM public.recipes r WHERE r.slug='pan-rosado' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Amasa de 8 a 10 minutos hasta obtener una masa suave y elástica.', false FROM public.recipes r WHERE r.slug='pan-rosado' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Deja levar la masa cubierta en un lugar tibio durante 1 hora, hasta que casi doble su tamaño.', false FROM public.recipes r WHERE r.slug='pan-rosado' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Desgasifica suavemente, forma bolitas pequeñas y colócalas en una bandeja engrasada, dejando espacio entre ellas.', false FROM public.recipes r WHERE r.slug='pan-rosado' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Deja levar 45 minutos más, hasta que se vean esponjadas.', false FROM public.recipes r WHERE r.slug='pan-rosado' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Hornea a 180 °C de 20 a 25 minutos, hasta que estén doradas y suenen huecas al golpear la base.', false FROM public.recipes r WHERE r.slug='pan-rosado' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Deja enfriar sobre una rejilla antes de guardar.', false FROM public.recipes r WHERE r.slug='pan-rosado' ON CONFLICT (recipe_id, step_number) DO NOTHING;
