INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'pizca', 'solo a partir de los 12 meses', 8 FROM public.recipes r, public.ingredients i WHERE r.slug='panecitos-de-maiz-y-choclo' AND i.code='sal' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Mezcla la linaza molida con 3 cucharadas de agua en un vasito y déjala reposar 10 minutos, hasta que tome consistencia de gel: ese es el ligante que reemplaza al huevo.', false FROM public.recipes r WHERE r.slug='panecitos-de-maiz-y-choclo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Precalienta el horno a 190 °C y engrasa con aceite un molde para 10 panecitos o forra los huecos con capacillos de papel.', false FROM public.recipes r WHERE r.slug='panecitos-de-maiz-y-choclo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Cocina el choclo en agua hirviendo durante 5 minutos si está fresco, o 3 minutos si es congelado, y escúrrelo bien.', false FROM public.recipes r WHERE r.slug='panecitos-de-maiz-y-choclo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Aplasta los granos de choclo con un tenedor o pícalos groseramente: enteros son redondos y firmes, y representan riesgo de atragantamiento para menores de 4 años.', true FROM public.recipes r WHERE r.slug='panecitos-de-maiz-y-choclo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'En un tazón grande mezcla la harina de maíz, la harina integral, el polvo para hornear y la pizca de sal.', false FROM public.recipes r WHERE r.slug='panecitos-de-maiz-y-choclo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Agrega el gel de linaza, el aceite y el agua, y revuelve solo hasta integrar; después incorpora el choclo machacado.', false FROM public.recipes r WHERE r.slug='panecitos-de-maiz-y-choclo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Reparte la mezcla en el molde llenando cada hueco hasta tres cuartos de su capacidad.', false FROM public.recipes r WHERE r.slug='panecitos-de-maiz-y-choclo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Hornea de 22 a 25 minutos, hasta que estén dorados por arriba y un palillo salga limpio del centro.', false FROM public.recipes r WHERE r.slug='panecitos-de-maiz-y-choclo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 9, 'Déjalos enfriar por completo sobre una rejilla antes de empacarlos: si van tibios sudan dentro del recipiente y se ponen gomosos.', false FROM public.recipes r WHERE r.slug='panecitos-de-maiz-y-choclo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Prepara la tanda con el choclo bien machacado o picado, nunca en granos enteros, y ofrece medio panecito partido en tiras del ancho de tu dedo.' FROM public.recipes r WHERE r.slug='panecitos-de-maiz-y-choclo' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Un panecito entero es una porción de colación; sigue partiendo o machacando los granos de choclo hasta los 4 años.' FROM public.recipes r WHERE r.slug='panecitos-de-maiz-y-choclo' ON CONFLICT (recipe_id, age_band) DO NOTHING;
