INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Cuece la pechuga en agua hirviendo unos 15 minutos, hasta que esté completamente cocida, sin partes rosadas en el centro.', true FROM public.recipes r WHERE r.slug='pizza-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Procesa el pollo cocido con el huevo, la sal, la pimienta y el orégano.', false FROM public.recipes r WHERE r.slug='pizza-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Agrega las claras y la maicena, y mezcla hasta obtener una masa uniforme.', false FROM public.recipes r WHERE r.slug='pizza-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Extiende la masa en forma de base circular. En sartén: cocina a fuego medio-bajo 15 minutos hasta que compacte. En horno: hornea sobre papel de hornear a 180 °C por 15 minutos. El huevo y las claras deben quedar completamente cocidos y la base firme.', true FROM public.recipes r WHERE r.slug='pizza-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Cubre con la pasta de tomate, las verduras y el queso rallado, y regresa al horno o a la sartén tapada hasta gratinar.', false FROM public.recipes r WHERE r.slug='pizza-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Deja entibiar y corta en porciones antes de servir o empacar.', false FROM public.recipes r WHERE r.slug='pizza-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Usa muy poca sal, pica los champiñones finamente y corta la pizza en tiras pequeñas fáciles de tomar con la mano.' FROM public.recipes r WHERE r.slug='pizza-de-pollo' ON CONFLICT (recipe_id, age_band) DO NOTHING;
