INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Elige un plátano bien maduro, de cáscara amarilla con manchas negras: de ahí sale todo el dulzor, sin necesidad de agregar azúcar.', false FROM public.recipes r WHERE r.slug='platano-maduro-dorado-con-queso-fresco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Pélalo y córtalo en rodajas de un centímetro de grosor.', false FROM public.recipes r WHERE r.slug='platano-maduro-dorado-con-queso-fresco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Calienta una sartén antiadherente a fuego medio con el aceite y acomoda las rodajas sin encimarlas.', false FROM public.recipes r WHERE r.slug='platano-maduro-dorado-con-queso-fresco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Dóralas de 3 a 4 minutos por lado, hasta que estén caramelizadas por fuera y muy blandas por dentro; deben ceder sin esfuerzo al presionarlas con la espátula.', false FROM public.recipes r WHERE r.slug='platano-maduro-dorado-con-queso-fresco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Aplasta ligeramente cada rodaja con el tenedor o pártela en trozos pequeños antes de servir a menores de 5 años: el plátano cocido es pegajoso y en rodajas enteras puede atragantar.', true FROM public.recipes r WHERE r.slug='platano-maduro-dorado-con-queso-fresco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Desmenuza el queso fresco encima, espolvorea la canela y deja entibiar antes de llevar a la mesa.', false FROM public.recipes r WHERE r.slug='platano-maduro-dorado-con-queso-fresco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Aplasta cada rodaja con el tenedor hasta dejarla plana y blanda, o córtala en trocitos pequeños: el plátano cocido es pegajoso y las rodajas redondas enteras no son seguras a esta edad.' FROM public.recipes r WHERE r.slug='platano-maduro-dorado-con-queso-fresco' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Sirve las rodajas cortadas por la mitad y deja que arme sus propios bocaditos poniendo el queso encima.' FROM public.recipes r WHERE r.slug='platano-maduro-dorado-con-queso-fresco' ON CONFLICT (recipe_id, age_band) DO NOTHING;
