INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Tritura la quinua con las verduras y un poco de agua hasta obtener un puré suave.' FROM public.recipes r WHERE r.slug='quinoa-con-verduras-al-vapor' ON CONFLICT (recipe_id, age_band) DO NOTHING;
