INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Enjuaga la quinua bajo el chorro de agua frotándola con las manos: así pierde el sabor amargo natural.', false FROM public.recipes r WHERE r.slug='quinua-salteada-con-pavo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Cocínala con las 2 tazas de agua a fuego medio, tapada, unos 15 minutos, hasta que se vea el germen en espiral y el agua se haya absorbido. Deja reposar 5 minutos y suéltala con un tenedor.', false FROM public.recipes r WHERE r.slug='quinua-salteada-con-pavo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Mientras tanto, calienta el aceite en un sartén amplio y sofríe la cebolla y el ajo 2 minutos, hasta que se vean transparentes.', false FROM public.recipes r WHERE r.slug='quinua-salteada-con-pavo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Agrega la zanahoria, la calabacita y el pimiento en cubitos y cocina 6-7 minutos, moviendo, hasta que estén blandos y se aplasten fácil con el tenedor.', false FROM public.recipes r WHERE r.slug='quinua-salteada-con-pavo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Suma el pavo molido y cocínalo desmenuzándolo con la cuchara hasta que no quede ninguna parte rosada por dentro, unos 6-8 minutos.', true FROM public.recipes r WHERE r.slug='quinua-salteada-con-pavo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Incorpora la quinua cocida, mezcla todo 2 minutos para que tome sabor y retira del fuego. Separa la porción del bebé antes de agregar sal.', true FROM public.recipes r WHERE r.slug='quinua-salteada-con-pavo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Sirve tibio. Guarda el resto en el refrigerador hasta 2 días, o congélalo en porciones hasta 2 meses.', true FROM public.recipes r WHERE r.slug='quinua-salteada-con-pavo-y-verduras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Cocina las verduras hasta que se aplasten con el tenedor y pica el pavo muy fino. Aplasta ligeramente la mezcla antes de servir y ofrécela en porciones pequeñas. Sin sal.' FROM public.recipes r WHERE r.slug='quinua-salteada-con-pavo-y-verduras' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Sirve tal cual pero con las verduras en cubitos del tamaño de un garbanzo. Poca o nada de sal.' FROM public.recipes r WHERE r.slug='quinua-salteada-con-pavo-y-verduras' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Sirve tal cual. Deja que tu peque revuelva la mezcla en el plato: participar aumenta las ganas de probar.' FROM public.recipes r WHERE r.slug='quinua-salteada-con-pavo-y-verduras' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_9a'::public.age_band, 'Sirve tal cual, con un chorrito de limón si le gusta. Va perfecta en termo para la lonchera.' FROM public.recipes r WHERE r.slug='quinua-salteada-con-pavo-y-verduras' ON CONFLICT (recipe_id, age_band) DO NOTHING;
