INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Calienta el caldo de verduras en una olla pequeña y mantenlo caliente a fuego bajo.', false FROM public.recipes r WHERE r.slug='risotto-de-champinones' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'En una sartén amplia con el aceite de oliva, sofríe la cebolla y el ajo picados hasta que estén tiernos.', false FROM public.recipes r WHERE r.slug='risotto-de-champinones' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Agrega los champiñones laminados y cocina hasta que reduzcan su tamaño.', false FROM public.recipes r WHERE r.slug='risotto-de-champinones' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Incorpora el arroz y tuéstalo ligeramente durante 2 minutos.', false FROM public.recipes r WHERE r.slug='risotto-de-champinones' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Añade un cucharón de caldo caliente y revuelve hasta que el arroz lo absorba.', false FROM public.recipes r WHERE r.slug='risotto-de-champinones' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Continúa agregando caldo poco a poco, revolviendo con frecuencia, hasta que el arroz esté cremoso y tierno (20-25 minutos).', false FROM public.recipes r WHERE r.slug='risotto-de-champinones' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Retira del fuego, incorpora el queso parmesano y mezcla bien; prueba y ajusta con muy poca sal solo si hace falta.', false FROM public.recipes r WHERE r.slug='risotto-de-champinones' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Sirve caliente, con perejil picado por encima si lo deseas.', false FROM public.recipes r WHERE r.slug='risotto-de-champinones' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Sirve la porción del bebé sin sal y con muy poco queso, y pica los champiñones en trozos pequeños y bien cocidos; la textura cremosa del risotto es ideal a esta edad.' FROM public.recipes r WHERE r.slug='risotto-de-champinones' ON CONFLICT (recipe_id, age_band) DO NOTHING;
