INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Mezcla la harina de avena con la sal, la canela, la leche y el huevo hasta obtener una masa uniforme.', false FROM public.recipes r WHERE r.slug='rollitos-de-banana' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Calienta una sartén con un poco de aceite y cocina la masa formando una tortilla delgada; dórala por ambos lados hasta que el huevo esté completamente cocido.', true FROM public.recipes r WHERE r.slug='rollitos-de-banana' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Unta la tortilla con la crema de maní y coloca la banana entera en el centro.', false FROM public.recipes r WHERE r.slug='rollitos-de-banana' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Enrolla con cuidado y regresa el rollo un minuto a la sartén para sellarlo.', false FROM public.recipes r WHERE r.slug='rollitos-de-banana' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Corta en rodajas de unos 2 centímetros y dóralas de nuevo por ambos lados si las quieres más firmes.', false FROM public.recipes r WHERE r.slug='rollitos-de-banana' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Prepara la tortilla sin sal, unta la crema de maní en capa muy fina y corta rodajas pequeñas; parte cada ruedita en cuartos para que sea fácil y segura de tomar.' FROM public.recipes r WHERE r.slug='rollitos-de-banana' ON CONFLICT (recipe_id, age_band) DO NOTHING;
