INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 8, 'trozo', 'o film APTO para cocción a altas temperaturas; nunca papel film común', 8 FROM public.recipes r, public.ingredients i WHERE r.slug='salchichas-de-pollo-caseras' AND i.code='papel_horno' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'cucharadita', 'solo para dorarlas (opcional)', 9 FROM public.recipes r, public.ingredients i WHERE r.slug='salchichas-de-pollo-caseras' AND i.code='aceite' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Mezcla en un bol el pollo molido, la zanahoria rallada, el ajo, la mostaza, la avena, la pizca de sal y la pimienta hasta obtener una masa uniforme.', false FROM public.recipes r WHERE r.slug='salchichas-de-pollo-caseras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Divide la mezcla en 8 porciones y, con las manos húmedas, forma cilindros del tamaño de una salchicha.', false FROM public.recipes r WHERE r.slug='salchichas-de-pollo-caseras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Envuelve cada cilindro en papel de horno o en film apto para cocción a altas temperaturas (nunca papel film común, que puede transferir plásticos al alimento) y gira los extremos como un caramelo para sellar.', true FROM public.recipes r WHERE r.slug='salchichas-de-pollo-caseras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Cocina las salchichas envueltas en agua hirviendo por 12-15 minutos; al cortar una por el centro no debe quedar ninguna parte rosada.', true FROM public.recipes r WHERE r.slug='salchichas-de-pollo-caseras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Retira el envoltorio y, si quieres una textura más dorada, pásalas por una sartén con un poquito de aceite.', false FROM public.recipes r WHERE r.slug='salchichas-de-pollo-caseras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Para menores de 5 años, corta las salchichas a lo largo en cuartos y luego en trozos pequeños; nunca en rodajas redondas tipo moneda, que pueden causar atragantamiento.', true FROM public.recipes r WHERE r.slug='salchichas-de-pollo-caseras' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Prepara la masa sin sal y sin mostaza, cocina la salchicha hasta que esté completamente cocida y sírvela desmenuzada o en trocitos muy pequeños.' FROM public.recipes r WHERE r.slug='salchichas-de-pollo-caseras' ON CONFLICT (recipe_id, age_band) DO NOTHING;
