INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 0.5, 'taza', 'opcional, para la versión en capas (o avena en hojuelas tostada)', 10 FROM public.recipes r, public.ingredients i WHERE r.slug='salpicon-de-frutas' AND i.code='granola' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 2, 'cucharada', 'opcional, para la versión en capas; siempre finamente triturados. Alérgeno: frutos secos; confirma la política de la escuela (muchas son libres de maní)', 11 FROM public.recipes r, public.ingredients i WHERE r.slug='salpicon-de-frutas' AND i.code='nuez' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Lava y pela las frutas; córtalas en trozos pequeños, del tamaño de un bocado de niño.', false FROM public.recipes r WHERE r.slug='salpicon-de-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Si agregas uvas, córtalas siempre en cuartos a lo largo para los menores de 5 años: enteras son riesgo de atragantamiento.', true FROM public.recipes r WHERE r.slug='salpicon-de-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Coloca las frutas en un tazón o jarra, vierte el jugo de naranja y mezcla bien.', false FROM public.recipes r WHERE r.slug='salpicon-de-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Refrigera al menos 30 minutos y sirve bien frío.', false FROM public.recipes r WHERE r.slug='salpicon-de-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Para la versión en capas (ensalada de frutas): omite el jugo y alterna capas de frutas con yogur griego en un vaso; corona con granola justo antes de comer para que no se ablande.', false FROM public.recipes r WHERE r.slug='salpicon-de-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Si agregas frutos secos, tritúralos muy finos: antes de los 5 años los frutos secos enteros o en trozos están prohibidos por riesgo de atragantamiento.', true FROM public.recipes r WHERE r.slug='salpicon-de-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Empaca en recipiente hermético con gel refrigerante y consume antes de 4 horas: la fruta picada necesita cadena de frío.', true FROM public.recipes r WHERE r.slug='salpicon-de-frutas' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Tritura las frutas maduras (banana, papaya, mango) como puré suave, sin jugo de naranja añadido: los jugos no se recomiendan antes de los 12 meses.' FROM public.recipes r WHERE r.slug='salpicon-de-frutas' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Machaca las frutas blandas o sírvelas en trocitos muy blandos; usa la manzana rallada o cocida y omite el jugo de naranja.' FROM public.recipes r WHERE r.slug='salpicon-de-frutas' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Sirve las frutas en trozos pequeños con apenas un chorrito de jugo de naranja natural, o sin jugo.' FROM public.recipes r WHERE r.slug='salpicon-de-frutas' ON CONFLICT (recipe_id, age_band) DO NOTHING;
