INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Calienta la bebida de avena a fuego bajo en una cacerola pequeña.', false FROM public.recipes r WHERE r.slug='salsa-de-algarroba' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Añade la harina de algarroba y revuelve constantemente hasta que la mezcla espese.', false FROM public.recipes r WHERE r.slug='salsa-de-algarroba' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Retira del fuego e incorpora el aceite de coco, mezclando hasta integrar.', false FROM public.recipes r WHERE r.slug='salsa-de-algarroba' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Deja enfriar un poco y sirve como cobertura para frutas, panqueques o avena.', false FROM public.recipes r WHERE r.slug='salsa-de-algarroba' ON CONFLICT (recipe_id, step_number) DO NOTHING;
