INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 30, 'g', '⅓ de taza', 2 FROM public.recipes r, public.ingredients i WHERE r.slug='untable-de-girasol-y-coco' AND i.code='coco_rallado' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
