INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'pizca', 'opcional', 4 FROM public.recipes r, public.ingredients i WHERE r.slug='untable-de-girasol-y-coco' AND i.code='canela' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Precalienta el horno a 160 °C y extiende las semillas de girasol en una bandeja en una sola capa.', false FROM public.recipes r WHERE r.slug='untable-de-girasol-y-coco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Tuéstalas de 8 a 10 minutos, moviéndolas a la mitad del tiempo, hasta que huelan a nuez y tomen un color dorado claro. Si se queman amargan toda la crema.', false FROM public.recipes r WHERE r.slug='untable-de-girasol-y-coco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Agrega el coco rallado a la bandeja durante el último minuto, solo para que tome color, y retira todo del horno.', false FROM public.recipes r WHERE r.slug='untable-de-girasol-y-coco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Deja entibiar 5 minutos y pasa las semillas y el coco al procesador o a una licuadora de vaso resistente.', false FROM public.recipes r WHERE r.slug='untable-de-girasol-y-coco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Procesa en tandas de 1 minuto, raspando las paredes con una espátula entre cada tanda. Pasará por etapas de harina, de pasta espesa y por fin de crema: toma entre 8 y 12 minutos en total, ten paciencia.', false FROM public.recipes r WHERE r.slug='untable-de-girasol-y-coco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Agrega el aceite de coco derretido y la canela, y procesa 1 minuto más hasta que quede brillante y fluida.', false FROM public.recipes r WHERE r.slug='untable-de-girasol-y-coco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Pásala a un frasco de vidrio limpio y completamente seco; cualquier gota de agua acorta su duración.', false FROM public.recipes r WHERE r.slug='untable-de-girasol-y-coco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 8, 'Sírvela siempre untada en capa fina sobre pan, tortilla o fruta. No ofrezcas cucharadas espesas de untables a menores de 4 años: pueden pegarse al paladar y provocar atragantamiento.', true FROM public.recipes r WHERE r.slug='untable-de-girasol-y-coco' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '12_24m'::public.age_band, 'Úntalo en capa muy fina sobre pan o fruta y evita dárselo a cucharadas: la crema espesa puede pegarse al paladar. Empieza con media cucharadita para comprobar tolerancia.' FROM public.recipes r WHERE r.slug='untable-de-girasol-y-coco' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '2_5a'::public.age_band, 'Una cucharadita bien extendida sobre pan integral o rueditas de manzana es suficiente por porción.' FROM public.recipes r WHERE r.slug='untable-de-girasol-y-coco' ON CONFLICT (recipe_id, age_band) DO NOTHING;
