INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'pizca', NULL, 7 FROM public.recipes r, public.ingredients i WHERE r.slug='waffles-de-pollo' AND i.code='pimienta' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'cucharadita', 'para engrasar la wafflera o la sartén', 8 FROM public.recipes r, public.ingredients i WHERE r.slug='waffles-de-pollo' AND i.code='aceite' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Mezcla en un tazón el pollo desmenuzado con la avena, el huevo y la leche hasta obtener una masa homogénea.', false FROM public.recipes r WHERE r.slug='waffles-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Agrega el polvo de hornear, la pizca de sal y la pimienta, y bate bien hasta integrar todo.', false FROM public.recipes r WHERE r.slug='waffles-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Precalienta la wafflera y engrásala con un poco de aceite.', false FROM public.recipes r WHERE r.slug='waffles-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Vierte una porción de la mezcla y cocina 4-5 minutos, hasta que el waffle esté dorado y completamente cocido en el centro (la masa lleva huevo).', true FROM public.recipes r WHERE r.slug='waffles-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Si no tienes wafflera, cocina la mezcla en una sartén engrasada como si fueran panqueques, 3 minutos por lado.', false FROM public.recipes r WHERE r.slug='waffles-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Deja enfriar sobre una rejilla antes de empacar para que no se humedezcan.', false FROM public.recipes r WHERE r.slug='waffles-de-pollo' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Prepara la masa sin sal y sirve el waffle en tiras blandas o trocitos pequeños, bien cocido por dentro.' FROM public.recipes r WHERE r.slug='waffles-de-pollo' ON CONFLICT (recipe_id, age_band) DO NOTHING;
