INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'pizca', 'opcional', 4 FROM public.recipes r, public.ingredients i WHERE r.slug='yogur-con-compota-de-manzana' AND i.code='nuez_moscada' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 3, 'cucharada', 'para cocinar la manzana', 5 FROM public.recipes r, public.ingredients i WHERE r.slug='yogur-con-compota-de-manzana' AND i.code='agua' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Pela y corta la manzana en trozos pequeños.', false FROM public.recipes r WHERE r.slug='yogur-con-compota-de-manzana' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Ponla en una olla pequeña con el agua y cocina a fuego medio unos 10 minutos, hasta que se ablande.', false FROM public.recipes r WHERE r.slug='yogur-con-compota-de-manzana' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Agrega la canela y, si quieres, la pizca de nuez moscada; mezcla bien.', false FROM public.recipes r WHERE r.slug='yogur-con-compota-de-manzana' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Tritura o machaca con tenedor hasta lograr una compota suave y déjala enfriar por completo.', false FROM public.recipes r WHERE r.slug='yogur-con-compota-de-manzana' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'En un vaso o bol, coloca una capa de yogur natural.', false FROM public.recipes r WHERE r.slug='yogur-con-compota-de-manzana' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Suma una capa de compota y repite hasta terminar, alternando capas.', false FROM public.recipes r WHERE r.slug='yogur-con-compota-de-manzana' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 7, 'Refrigera 10 minutos y sirve frío.', false FROM public.recipes r WHERE r.slug='yogur-con-compota-de-manzana' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Mezcla la compota bien triturada con el yogur natural entero hasta lograr un puré homogéneo, y omite la nuez moscada.' FROM public.recipes r WHERE r.slug='yogur-con-compota-de-manzana' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Machaca la manzana cocida con tenedor en lugar de triturarla, para que encuentre trocitos blandos dentro del yogur.' FROM public.recipes r WHERE r.slug='yogur-con-compota-de-manzana' ON CONFLICT (recipe_id, age_band) DO NOTHING;
