INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'cucharada', 'opcional', 4 FROM public.recipes r, public.ingredients i WHERE r.slug='yogur-con-fresas-y-arandanos' AND i.code='semilla_chia' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Lava bien las fresas y los arándanos.', false FROM public.recipes r WHERE r.slug='yogur-con-fresas-y-arandanos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Corta las fresas en trocitos pequeños y, para menores de 4 años, parte los arándanos por la mitad o aplástalos: enteros pueden atragantar.', true FROM public.recipes r WHERE r.slug='yogur-con-fresas-y-arandanos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Coloca el yogur natural como base en un vaso o bol.', false FROM public.recipes r WHERE r.slug='yogur-con-fresas-y-arandanos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Agrega las frutas por encima y mezcla con suavidad.', false FROM public.recipes r WHERE r.slug='yogur-con-fresas-y-arandanos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Si quieres, espolvorea las semillas de chía para un toque crocante.', false FROM public.recipes r WHERE r.slug='yogur-con-fresas-y-arandanos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Sirve de inmediato o refrigera 5 minutos para que quede más fresco.', false FROM public.recipes r WHERE r.slug='yogur-con-fresas-y-arandanos' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Tritura las frutas con el yogur hasta lograr un puré suave y homogéneo; si usas semillas de chía, muélelas antes.' FROM public.recipes r WHERE r.slug='yogur-con-fresas-y-arandanos' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '9_11m'::public.age_band, 'Aplasta los arándanos con un tenedor y pica las fresas muy finas antes de mezclarlas con el yogur.' FROM public.recipes r WHERE r.slug='yogur-con-fresas-y-arandanos' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipes (slug, title, description, category, min_age_months, max_age_months, texture_stages, prep_minutes, cook_minutes, servings, difficulty, suitable_slots, is_batch_friendly, is_lunchbox_friendly, is_economic, requires_oven, requires_blender, conservation, is_freezable, freezer_months, protein_group, veggie_colors, carb_base, has_free_sugars, is_occasional_sweet, nutrition_blurb, tips, family_mode_note, source_book, source_numbers, image_filename, fallback_image) VALUES (
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 1, 'litro', NULL, 1 FROM public.recipes r, public.ingredients i WHERE r.slug='yogur-griego-casero' AND i.code='leche_entera' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 3, 'cucharada', 'da un yogur más firme y cremoso', 2 FROM public.recipes r, public.ingredients i WHERE r.slug='yogur-griego-casero' AND i.code='leche_en_polvo' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, sort_order) SELECT r.id, i.id, 200, 'ml', 'sin azúcar y con cultivos vivos (griego o natural)', 3 FROM public.recipes r, public.ingredients i WHERE r.slug='yogur-griego-casero' AND i.code='yogur_natural' ON CONFLICT (recipe_id, ingredient_id, sort_order) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 1, 'Paso solo para adultos: disuelve la leche en polvo en la leche y caliéntala en una olla a fuego medio hasta 82-85 °C, midiendo con termómetro de cocina. Nunca compruebes la temperatura con el dedo.', true FROM public.recipes r WHERE r.slug='yogur-griego-casero' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 2, 'Retira la olla del fuego y deja enfriar la leche hasta 42-45 °C, verificando de nuevo con el termómetro: si está más caliente, los cultivos del yogur mueren y no fermenta.', false FROM public.recipes r WHERE r.slug='yogur-griego-casero' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 3, 'Agrega el yogur natural y mezcla bien hasta integrarlo por completo.', false FROM public.recipes r WHERE r.slug='yogur-griego-casero' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 4, 'Vierte la mezcla en un recipiente hermético, envuélvelo con una toalla y déjalo fermentar de 8 a 12 horas en un lugar tibio, oscuro y sin corrientes de aire.', false FROM public.recipes r WHERE r.slug='yogur-griego-casero' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 5, 'Cuela el yogur con un paño limpio sobre un colador, dentro del refrigerador, por 2 a 4 horas para separar el suero, hasta lograr la textura griega que te guste.', false FROM public.recipes r WHERE r.slug='yogur-griego-casero' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_steps (recipe_id, step_number, instruction, is_safety_critical) SELECT r.id, 6, 'Guárdalo en un frasco tapado en el refrigerador y consúmelo en un máximo de 7 días.', true FROM public.recipes r WHERE r.slug='yogur-griego-casero' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO public.recipe_variants (recipe_id, age_band, adaptation_text) SELECT r.id, '6_8m'::public.age_band, 'Sírvelo natural mezclado con puré de fruta madura; nunca le agregues miel ni azúcar.' FROM public.recipes r WHERE r.slug='yogur-griego-casero' ON CONFLICT (recipe_id, age_band) DO NOTHING;
INSERT INTO public.recipes (slug, title, description, category, min_age_months, max_age_months, texture_stages, prep_minutes, cook_minutes, servings, difficulty, suitable_slots, is_batch_friendly, is_lunchbox_friendly, is_economic, requires_oven, requires_blender, conservation, is_freezable, freezer_months, protein_group, veggie_colors, carb_base, has_free_sugars, is_occasional_sweet, nutrition_blurb, tips, family_mode_note, source_book, source_numbers, image_filename, fallback_image) VALUES
('batido-de-fresa-y-banana', 'Batido de Fresa y Banana', 'Un batido cremoso y naturalmente dulce de fresa y banana con yogur. Sin azucar anadida: la fruta madura endulza todo por si sola.', 'bebida', 12, NULL, ARRAY[3,4,5]::INT[], 5, 0, 2, 1, ARRAY['desayuno','colacion_am','colacion_pm']::public.meal_slot[], false, false, true, false, true, 'requiere_frio', false, NULL, 'lacteo', ARRAY[]::TEXT[], NULL, false, false, 'El yogur aporta calcio y probioticos, la banana potasio y la fresa vitamina C. Al licuar la fruta entera conservas la fibra que se pierde en los jugos.', 'Si queda muy espeso agrega un poco mas de leche; si lo quieres helado, usa la banana congelada en trozos.', 'Para los adultos puedes anadir avena o un punado de espinaca sin cambiar el sabor.', 'nueva', NULL, 'receta-batido-de-fresa-y-banana.webp', 'placeholder-categoria-bebidas.webp'),
('leche-de-avena-casera', 'Leche de Avena Casera', 'Bebida de avena suave y cremosa hecha en casa, sin azucar ni conservantes. Perfecta para el desayuno o para cocinar.', 'bebida', 12, NULL, ARRAY[3,4,5]::INT[], 10, 0, 4, 1, ARRAY['desayuno','colacion_am']::public.meal_slot[], true, false, true, false, true, 'requiere_frio', false, NULL, NULL, ARRAY[]::TEXT[], NULL, false, false, 'Una alternativa vegetal economica y sin conservantes. No reemplaza la leche materna ni la formula en menores de 1 ano; a partir de ahi es una bebida mas dentro de una dieta variada.', 'Cuela con un pano limpio para que quede bien lisa y guardala en frasco tapado hasta 3 dias.', 'Sirve para preparar avena, panqueques o batidos de toda la familia.', 'nueva', NULL, 'receta-leche-de-avena-casera.webp', 'placeholder-categoria-bebidas.webp'),
('chocolate-caliente-sin-azucar', 'Chocolate Caliente Sin Azucar', 'Chocolate caliente cremoso endulzado solo con datil, con cacao puro. Un abrazo en taza, sin azucar anadida.', 'bebida', 24, NULL, ARRAY[4,5]::INT[], 5, 5, 2, 1, ARRAY['desayuno','colacion_pm']::public.meal_slot[], false, false, true, false, true, 'requiere_frio', false, NULL, 'lacteo', ARRAY[]::TEXT[], NULL, false, true, 'El cacao puro aporta antioxidantes y hierro, y el datil endulza con la dulzura de la fruta en vez de azucar refinada. Una version mas noble del clasico de la tarde.', 'Bate bien para que no queden grumos de cacao y prueba la temperatura antes de servir a tu peque.', 'Agrega una pizca de canela o un toque de cafe para la taza de los adultos.', 'nueva', NULL, 'receta-chocolate-caliente-sin-azucar.webp', 'placeholder-categoria-bebidas.webp'),
('batido-verde-de-mango-y-espinaca', 'Batido Verde de Mango y Espinaca', 'Un batido dulce de mango donde la espinaca se esconde: color divertido y sabor a fruta. Verduras que si se toman.', 'bebida', 12, NULL, ARRAY[3,4,5]::INT[], 5, 0, 2, 1, ARRAY['desayuno','colacion_am']::public.meal_slot[], false, false, true, false, true, 'requiere_frio', false, NULL, NULL, ARRAY['verde','naranja']::TEXT[], NULL, false, false, 'La espinaca aporta hierro y folato sin que se note el sabor, gracias a la dulzura del mango maduro. Una via facil de sumar verduras de hoja verde al dia.', 'Empieza con poca espinaca y ve subiendo; el color verde suele encantarles como si fuera magia.', 'Un chorrito de limon lo refresca para el gusto de los grandes.', 'nueva', NULL, 'receta-batido-verde-de-mango-y-espinaca.webp', 'placeholder-categoria-bebidas.webp'),
('avena-cremosa-de-manzana-y-canela', 'Avena Cremosa de Manzana y Canela', 'Avena calientita cocida con manzana rallada y canela. Un desayuno que abriga, con fibra y sin azucar anadida.', 'desayuno', 8, NULL, ARRAY[2,3,4,5]::INT[], 5, 10, 2, 1, ARRAY['desayuno']::public.meal_slot[], true, false, true, false, false, 'requiere_frio', true, 1, NULL, ARRAY[]::TEXT[], 'avena', false, false, 'La avena da energia de liberacion lenta y fibra que ayuda a la digestion, y la manzana suma dulzor natural y mas fibra. Un desayuno que sostiene la manana sin picos de azucar.', 'Prepara doble y guarda en el refri; al dia siguiente se calienta con un chorrito de leche.', 'Agrega nueces molidas o pasas para los mayores de la casa.', 'nueva', NULL, 'receta-avena-cremosa-de-manzana-y-canela.webp', 'placeholder-categoria-desayunos.webp'),
('huevos-revueltos-con-espinaca-y-queso', 'Huevos Revueltos con Espinaca y Queso', 'Huevos suaves y esponjosos con espinaca finita y queso derretido. Proteina completa para arrancar el dia.', 'desayuno', 9, NULL, ARRAY[3,4,5]::INT[], 5, 5, 1, 1, ARRAY['desayuno','cena']::public.meal_slot[], false, false, true, false, false, 'requiere_frio', false, NULL, 'huevo', ARRAY['verde']::TEXT[], NULL, false, false, 'El huevo aporta proteina de alta calidad y colina para el cerebro, la espinaca hierro y el queso calcio. Un desayuno completo en cinco minutos.', 'Cocina a fuego bajo y revuelve suave para que queden cremosos y no secos.', 'Sirve con pan integral tostado para acompanar a los grandes.', 'nueva', NULL, 'receta-huevos-revueltos-con-espinaca-y-queso.webp', 'placeholder-categoria-desayunos.webp'),
('sopa-casera-de-verduras-con-fideos', 'Sopa Casera de Verduras con Fideos', 'Sopa reconfortante de verduras con fideos finos. Ligera para la cena, con el sabor casero de siempre.', 'cena', 12, NULL, ARRAY[3,4,5]::INT[], 10, 20, 4, 1, ARRAY['cena','almuerzo']::public.meal_slot[], true, false, true, false, false, 'requiere_frio', true, 2, NULL, ARRAY['naranja','verde','blanco']::TEXT[], NULL, false, false, 'Una cena ligera y calentita que hidrata y suma varias verduras en un solo plato. Los fideos finos dan energia sin pesar antes de dormir.', 'Congela en porciones individuales; es la cena de emergencia perfecta para los dias sin tiempo.', 'Sirve la porcion del nino y luego ajusta la sal del resto de la olla para los adultos.', 'nueva', NULL, 'receta-sopa-casera-de-verduras-con-fideos.webp', 'placeholder-categoria-comidas.webp'),
('tortilla-de-papa-y-zanahoria-al-horno', 'Tortilla de Papa y Zanahoria al Horno', 'Una tortilla de huevo horneada con papa y zanahoria, jugosa por dentro. Se corta en cuadros y encanta a toda edad.', 'cena', 12, NULL, ARRAY[4,5]::INT[], 15, 25, 4, 2, ARRAY['cena','almuerzo','lonchera']::public.meal_slot[], true, true, true, true, false, 'requiere_frio', true, 2, 'huevo', ARRAY['naranja','blanco']::TEXT[], NULL, false, false, 'Combina la proteina del huevo con la energia de la papa y el betacaroteno de la zanahoria. Horneada usa menos aceite que la de sarten y queda mas ligera.', 'Corta en cuadritos y guarda: sirve para la cena, para la lonchera del dia siguiente o para un snack.', 'Agrega cebolla dorada o hierbas para darle mas caracter en la mesa de los grandes.', 'nueva', NULL, 'receta-tortilla-de-papa-y-zanahoria-al-horno.webp', 'placeholder-categoria-comidas.webp'),
('wrap-integral-de-pollo-y-aguacate', 'Wrap Integral de Pollo y Aguacate', 'Tortilla integral enrollada con pollo desmenuzado y aguacate cremoso. Se come con la mano, perfecta para la lonchera.', 'lonchera', 18, NULL, ARRAY[4,5]::INT[], 10, 0, 2, 1, ARRAY['lonchera','almuerzo']::public.meal_slot[], false, true, true, false, false, 'requiere_frio', false, NULL, 'pollo_pavo', ARRAY['verde','rojo']::TEXT[], NULL, false, false, 'Un almuerzo portatil y completo: proteina del pollo, grasas buenas del aguacate y fibra de la tortilla integral. Ideal para comer fuera de casa sin ensuciar.', 'Envuelvelo en papel encerado y cortalo a la mitad; asi entra facil en la lonchera y no se desarma.', 'Suma un poco de picante o mostaza al wrap de los adultos.', 'nueva', NULL, 'receta-wrap-integral-de-pollo-y-aguacate.webp', 'placeholder-categoria-loncheras.webp'),
('bastones-de-verduras-con-hummus', 'Bastones de Verduras con Hummus', 'Palitos crujientes de zanahoria y pepino con hummus suave para mojar. Colacion divertida que si trae verduras.', 'colacion', 12, NULL, ARRAY[5]::INT[], 10, 0, 2, 1, ARRAY['colacion_am','colacion_pm','lonchera']::public.meal_slot[], false, true, true, false, true, 'requiere_frio', false, NULL, 'legumbre', ARRAY['naranja','verde']::TEXT[], NULL, false, false, 'El hummus de garbanzo aporta proteina vegetal y fibra, y mojar los bastones convierte las verduras en un juego. Una colacion salada mas noble que las galletas.', 'Ofrece los bastones solo cuando tu peque ya mastica bien; para los mas pequenos, cuecelos al vapor unos minutos.', 'Agrega un toque de comino o paprika al hummus de los grandes.', 'nueva', NULL, 'receta-bastones-de-verduras-con-hummus.webp', 'placeholder-categoria-meriendas.webp'),
('gelatina-de-frutas-naturales', 'Gelatina de Frutas Naturales', 'Gelatina hecha con jugo de fruta natural y trocitos de fruta, sin polvos artificiales ni colorantes. Postre divertido y ligero.', 'postre', 18, NULL, ARRAY[4,5]::INT[], 15, 5, 4, 1, ARRAY['colacion_pm','almuerzo']::public.meal_slot[], false, false, true, false, false, 'requiere_frio', false, NULL, NULL, ARRAY[]::TEXT[], NULL, false, false, 'Una version casera del postre favorito, sin colorantes ni azucar anadida: solo jugo de fruta y grenetina, que aporta la textura divertida que tanto les gusta.', 'Usa fruta en trozos pequenos y evita kiwi o pina crudos, que impiden que la gelatina cuaje.', 'Sirve en vasitos individuales para que cada quien tenga el suyo.', 'nueva', NULL, 'receta-gelatina-de-frutas-naturales.webp', 'placeholder-categoria-postres.webp')
